function setWentianMobilePdfStatus(message = "", mode = "") {
  const status = view.querySelector("[data-wentian-pdf-status]");
  if (!status) return;
  status.textContent = message ? translateWentianText(message) : "";
  status.classList.toggle("is-ready", mode === "ready");
  status.classList.toggle("is-error", mode === "error");
}

function fitWentianPdfBlocksToPages(report, pageHeight) {
  report.querySelectorAll(".wentian-pdf-text-card").forEach((card) => {
    card.style.marginTop = "";
  });
  report.querySelectorAll(".wentian-pdf-chapter").forEach((chapter) => {
    chapter.style.height = "auto";
    chapter.style.minHeight = `${pageHeight}px`;
    chapter.querySelectorAll(".wentian-pdf-text-card").forEach((card) => {
      const chapterTop = chapter.getBoundingClientRect().top;
      const cardRect = card.getBoundingClientRect();
      const cardTop = Math.max(0, cardRect.top - chapterTop);
      const cardHeight = Math.ceil(cardRect.height);
      const pageOffset = cardTop % pageHeight;
      if (cardHeight < pageHeight - 64 && pageOffset + cardHeight > pageHeight - 44) {
        card.style.marginTop = `${Math.ceil(pageHeight - pageOffset + 24)}px`;
      }
    });
  });
  const blocks = report.querySelectorAll(
    ".wentian-pdf-cover, .wentian-pdf-basic-section, .wentian-pdf-chart-section, .wentian-pdf-chapter"
  );
  blocks.forEach((block) => {
    block.style.height = "auto";
    block.style.minHeight = `${pageHeight}px`;
    const measuredHeight = Math.max(
      block.scrollHeight || 0,
      Math.ceil(block.getBoundingClientRect().height || 0),
      pageHeight
    );
    const pageCount = Math.max(1, Math.ceil(measuredHeight / pageHeight));
    block.style.height = `${pageCount * pageHeight}px`;
    block.style.minHeight = "0";
  });
}

function getWentianPdfBlockRenderOptions(blockHeight, pageWidth, pageHeight) {
  return {
    margin: [0, 0, 0, 0],
    image: { type: "jpeg", quality: 0.96 },
    html2canvas: {
      scale: 2,
      useCORS: true,
      backgroundColor: "#f7f2e9",
      width: pageWidth,
      height: blockHeight,
      windowWidth: pageWidth,
      windowHeight: blockHeight,
      x: 0,
      y: 0,
      scrollX: 0,
      scrollY: 0,
    },
    jsPDF: { unit: "px", format: [pageWidth, pageHeight], orientation: "portrait" },
    pagebreak: { mode: [] },
  };
}

async function waitForWentianPdfReportAssets(report) {
  if (document.fonts?.ready) {
    await document.fonts.ready.catch(() => {});
  }
  await Promise.all(Array.from(report.querySelectorAll("img")).map((img) => {
    if (img.complete) return Promise.resolve();
    return new Promise((resolve) => {
      img.addEventListener("load", resolve, { once: true });
      img.addEventListener("error", resolve, { once: true });
    });
  }));
}

function createWentianPdfPageFrame(report, block, pageIndex, pageWidth, pageHeight) {
  const host = report.parentElement;
  if (!host) throw new Error("PDF export host is unavailable.");
  const frame = document.createElement("div");
  frame.className = "wentian-pdf-report";
  frame.setAttribute("aria-hidden", "true");
  Object.assign(frame.style, {
    position: "relative",
    width: `${pageWidth}px`,
    height: `${pageHeight}px`,
    minHeight: `${pageHeight}px`,
    overflow: "hidden",
    background: "#f7f2e9",
  });
  const clone = block.cloneNode(true);
  Object.assign(clone.style, {
    position: "absolute",
    left: "0",
    top: `${-pageIndex * pageHeight}px`,
    width: `${pageWidth}px`,
    margin: "0",
  });
  frame.appendChild(clone);
  host.appendChild(frame);
  return frame;
}

async function saveWentianPdfReportByBlocks(html2pdf, report, filename, pageWidth, pageHeight) {
  const blocks = Array.from(report.querySelectorAll(
    ".wentian-pdf-cover, .wentian-pdf-basic-section, .wentian-pdf-chart-section, .wentian-pdf-chapter"
  ));
  if (!blocks.length) throw new Error("PDF report is empty.");
  const firstWorker = html2pdf()
    .set(getWentianPdfBlockRenderOptions(pageHeight, pageWidth, pageHeight))
    .from(blocks[0])
    .toPdf();
  const pdf = await firstWorker.get("pdf");
  const totalPages = blocks.reduce((total, block) => {
    const blockHeight = Math.max(pageHeight, Math.ceil(block.getBoundingClientRect().height));
    return total + Math.max(1, Math.round(blockHeight / pageHeight));
  }, 0);
  let outputPageNumber = 1;
  for (const block of blocks.slice(1)) {
    const blockHeight = Math.max(pageHeight, Math.ceil(block.getBoundingClientRect().height));
    const pageCount = Math.max(1, Math.round(blockHeight / pageHeight));
    for (let pageIndex = 0; pageIndex < pageCount; pageIndex += 1) {
      const frame = createWentianPdfPageFrame(report, block, pageIndex, pageWidth, pageHeight);
      let canvas;
      try {
        canvas = await html2pdf()
          .set(getWentianPdfBlockRenderOptions(pageHeight, pageWidth, pageHeight))
          .from(frame)
          .toCanvas()
          .get("canvas");
      } finally {
        frame.remove();
      }
      const context = canvas.getContext("2d");
      if (!context) throw new Error("PDF canvas is unavailable.");
      outputPageNumber += 1;
      const canvasScale = canvas.width / pageWidth;
      context.save();
      context.setTransform(1, 0, 0, 1, 0, 0);
      context.strokeStyle = "#d9c9ad";
      context.lineWidth = 0.5 * canvasScale;
      context.beginPath();
      context.moveTo(24 * canvasScale, (pageHeight - 29) * canvasScale);
      context.lineTo((pageWidth - 24) * canvasScale, (pageHeight - 29) * canvasScale);
      context.stroke();
      context.fillStyle = "#8e774c";
      context.font = `${7 * canvasScale}px Arial, sans-serif`;
      context.textBaseline = "alphabetic";
      context.textAlign = "left";
      context.fillText("YUETIAN AI", 24 * canvasScale, (pageHeight - 16) * canvasScale);
      context.textAlign = "right";
      context.fillText(
        `${String(outputPageNumber).padStart(2, "0")} / ${String(totalPages).padStart(2, "0")}`,
        (pageWidth - 24) * canvasScale,
        (pageHeight - 16) * canvasScale
      );
      context.restore();
      pdf.addPage([pageWidth, pageHeight], "portrait");
      pdf.addImage(canvas.toDataURL("image/jpeg", 0.96), "JPEG", 0, 0, pageWidth, pageHeight, undefined, "FAST");
      canvas.width = 1;
      canvas.height = 1;
    }
  }
  pdf.setProperties({
    title: filename.replace(/\.pdf$/i, ""),
    author: "Yuetian AI",
    creator: "Yuetian AI",
  });
  pdf.save(filename);
}

async function downloadWentianMingbookPdf() {
  const saved = getWentianDisplayChartState();
  const btn = view.querySelector('[data-action="wentian-open-mingbook-onepage"]');
  const originalText = btn?.textContent || translateWentianText("下载PDF");
  if (!saved) {
    setWentianMobilePdfStatus("请先完成排盘。", "error");
    return;
  }
  if (!isWentianMingbookPdfReady()) {
    setWentianMobilePdfStatus("解读完成后才能下载PDF。", "error");
    return;
  }
  if (btn) {
    btn.disabled = true;
    btn.textContent = translateWentianText("正在打包PDF…");
  }
  setWentianMobilePdfStatus("正在打包PDF…", "ready");
  const host = document.createElement("div");
  host.className = "wentian-pdf-export-host";
  document.body.classList.add("is-wentian-pdf-exporting");
  try {
    const report = buildWentianMobilePdfReportElement(saved);
    host.appendChild(report);
    document.body.appendChild(host);
    await new Promise((resolve) => window.requestAnimationFrame(resolve));
    await waitForWentianPdfReportAssets(report);
    fitWentianPdfBlocksToPages(report, WENTIAN_PDF_PAGE_HEIGHT);
    const html2pdf = await loadWentianHtml2Pdf();
    const filename = `${safeWentianPdfFileName(saved?.form?.name || "个人命盘")}-${formatWentianPdfDateKey(saved)}-紫微命盘深度报告.pdf`;
    await saveWentianPdfReportByBlocks(
      html2pdf,
      report,
      filename,
      WENTIAN_PDF_PAGE_WIDTH,
      WENTIAN_PDF_PAGE_HEIGHT
    );
    setWentianMobilePdfStatus("PDF已开始下载。", "ready");
  } catch (error) {
    console.error(error);
    setWentianMobilePdfStatus("PDF下载失败，请检查网络后重试。", "error");
  } finally {
    document.body.classList.remove("is-wentian-pdf-exporting");
    host.remove();
    if (btn) {
      btn.disabled = false;
      btn.textContent = originalText;
    }
  }
}

function getWentianArchiveDisplay(archive) {
  const form = archive?.form || {};
  const chartData = archive?.chartData || {};
  const sizhu = chartData.sizhu || {};
  const virtualAgeInfo = getWentianArchiveVirtualAgeInfo(archive);
  const baseName = getWentianArchiveRawName(archive) || getWentianArchiveGenericName(archive);
  const name = virtualAgeInfo?.ok && Number.isFinite(virtualAgeInfo.age) && virtualAgeInfo.age >= 1 && !/[岁歲]/.test(baseName)
    ? `${baseName} · ${virtualAgeInfo.age}岁`
    : (baseName || getWentianArchiveResolvedName(archive));
  const normalizedGender = normalizeWentianArchiveGender(archive);
  const gender = normalizedGender === "female" ? "女" : normalizedGender === "male" ? "男" : "未填";
  const datetime = (form.datetime || chartData.birthDate || chartData.solarTime || "").replace("T", " ").replace(/:00$/, "");
  const pillars = [sizhu.year, sizhu.month, sizhu.day, sizhu.hour].filter(Boolean).join(" ");
  return {
    name,
    gender,
    datetime,
    pillars: pillars || "命盘资料待补全",
    tag: "四柱八字",
    badge: archive?.id === getWentianStoredSelectedArchiveId() ? "默认" : "",
    ageBadge: virtualAgeInfo?.ok ? "虚岁" : "",
  };
}

function normalizeWentianGenderValue(value) {
  const text = String(value || "").trim().toLowerCase();
  if (["male", "m", "man", "boy", "1", "男", "阳男", "陽男", "阴男", "陰男", "阳性", "陽性", "男性"].includes(text)) return "male";
  if (["female", "f", "woman", "girl", "0", "女", "阴女", "陰女", "阳女", "陽女", "阴性", "陰性", "女性"].includes(text)) return "female";
  return "";
}

function normalizeWentianArchiveGender(archive) {
  return normalizeWentianGenderValue(
    archive?.form?.gender
    || archive?.chartData?.gender
    || archive?.gender
    || archive?.form?.remoteRaw?.gender
  );
}

function parseWentianArchiveBirthDate(archive) {
  const form = archive?.form || {};
  const chartData = archive?.chartData || {};
  const raw = [
    form.datetime,
    form.remoteRaw?.datetime,
    form.remoteRaw?.dateStr,
    chartData.birthDate,
    chartData.solarTime,
  ].find(Boolean);
  const match = String(raw || "").match(/(\d{4})[-/.年](\d{1,2})[-/.月](\d{1,2})/);
  if (!match) return null;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (!year || month < 1 || month > 12 || day < 1 || day > 31) return null;
  const date = new Date(year, month - 1, day, 12, 0, 0, 0);
  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) return null;
  return date;
}

function getWentianArchiveAgeInfo(archive, now = new Date()) {
  const birthDate = parseWentianArchiveBirthDate(archive);
  if (!birthDate) return { ok: false, code: "missing-birth", birthDate: null, age: null };
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 12, 0, 0, 0);
  if (birthDate.getTime() > today.getTime()) return { ok: false, code: "future-birth", birthDate, age: null };
  let age = today.getFullYear() - birthDate.getFullYear();
  const hadBirthday = today.getMonth() > birthDate.getMonth()
    || (today.getMonth() === birthDate.getMonth() && today.getDate() >= birthDate.getDate());
  if (!hadBirthday) age -= 1;
  return { ok: true, code: "ok", birthDate, age };
}

function getWentianHepanPersonLabel(archive) {
  return getWentianArchiveDisplay(archive).name || "该档案";
}

