function stabilizeWentianLanguageText(root = view) {
  const scheduledCode = getWentianLanguageCode();
  if (scheduledCode === "zh-Hans") return;
  [0, 60, 180, 420, 900].forEach((delay) => {
    window.setTimeout(() => {
      if (getWentianLanguageCode() !== scheduledCode) return;
      applyWentianLanguageText(root, scheduledCode, { force: true });
    }, delay);
  });
}

function scheduleWentianLanguageApply() {
  const displayCode = getWentianDisplayLanguageCode();
  if (displayCode === "zh-Hans") return;
  queueWentianLanguageApply(view, displayCode);
}

function ensureWentianLanguageObserver() {
  if (wentianI18nObserver || typeof MutationObserver === "undefined" || !view) return;
  wentianI18nObserver = new MutationObserver(scheduleWentianLanguageApply);
  wentianI18nObserver.observe(view, {
    childList: true,
    subtree: true,
    characterData: true,
    attributes: true,
    attributeFilter: ["placeholder"]
  });
}

function getWentianRouteFromClickPoint(event) {
  const routeTargets = Array.from(document.querySelectorAll("[data-route]"));
  const hitTargets = routeTargets.map((element, index) => {
    const rect = element.getBoundingClientRect();
    const style = window.getComputedStyle(element);
    const visible = rect.width > 0 && rect.height > 0 && style.display !== "none" && style.visibility !== "hidden";
    const inside = event.clientX >= rect.left && event.clientX <= rect.right && event.clientY >= rect.top && event.clientY <= rect.bottom;
    return visible && inside ? { element, index, z: Number.parseInt(style.zIndex, 10) || 0 } : null;
  }).filter(Boolean).sort((a, b) => b.z - a.z || b.index - a.index);
  if (hitTargets[0]?.element?.dataset.route) return hitTargets[0].element.dataset.route;

  const phone = event.target.closest?.(".figma-phone") || view?.querySelector?.(".figma-phone");
  if (!phone) return "";
  const phoneRect = phone.getBoundingClientRect();
  if (
    event.clientX < phoneRect.left ||
    event.clientX > phoneRect.right ||
    event.clientY < phoneRect.top ||
    event.clientY > phoneRect.bottom
  ) return "";
  const scale = phoneRect.width ? phoneRect.width / WENTIAN_PHONE_WIDTH : 1;
  const x = (event.clientX - phoneRect.left) / (scale || 1);
  const y = (event.clientY - phoneRect.top) / (scale || 1);
  const screenNo = Number(String(state.route || "").replace("screen-", ""));
  const hotspots = getScreenFlowHotspots(screenNo);
  for (let index = hotspots.length - 1; index >= 0; index -= 1) {
    const [left, top, width, height, route] = hotspots[index];
    if (x >= left && x <= left + width && y >= top && y <= top + height) return route;
  }
  return "";
}

function navigateWentianClickRoute(route) {
  if (!route) return;
  if (route !== "screen-17") setLiuyaoCasterModalOpen(false);
  if (liuyaoTossAnimation?.active && route !== "screen-17") clearLiuyaoTossAnimation();
  if (route === "screen-4") clearWentianXuChatContext();
  if (route === "screen-26") {
    wentianArchiveDeleteConfirmId = "";
    clearWentianArchiveEditContext();
  }
  navigate(route);
}

function handleWentianRoutePointerCapture(event) {
  if (event.pointerType === "mouse" && event.button !== 0) return;
  if (event.target.closest?.("input, textarea, select, [contenteditable='true']")) return;
  if (event.target.closest?.('.wentian-floating-profile-confirm [data-action="wentian-profile-confirm"]')) {
    wentianPointerRouteSuppressUntil = Date.now() + 350;
    event.preventDefault();
    event.stopPropagation();
    confirmWentianProfileSelection();
    return;
  }
  if (event.target.closest?.('.wentian-floating-chart-submit [data-action="wentian-chart-submit"]')) {
    wentianPointerRouteSuppressUntil = Date.now() + 350;
    event.preventDefault();
    event.stopPropagation();
    submitWentianChartForm();
    return;
  }
  if (event.target.closest?.("[data-action]")) return;
  const route = event.target.closest?.("[data-route]")?.dataset.route || getWentianRouteFromClickPoint(event);
  if (!route) return;
  wentianPointerRouteSuppressUntil = Date.now() + 350;
  event.preventDefault();
  event.stopPropagation();
  navigateWentianClickRoute(route);
}

function getWentianProfile() {
  const meta = wentianAuthSession?.user?.user_metadata || readWentianStoredSession()?.user?.user_metadata || {};
  const defaultNickname = isWentianEnglishUi() ? "Guest" : "谢广周";
  const defaults = {
    nickname: defaultNickname,
    email: meta.profile_email || "",
    phone: meta.phone || "",
  };
  try {
    const raw = localStorage.getItem(WENTIAN_PROFILE_STORAGE_KEY);
    const saved = raw ? JSON.parse(raw) : null;
    const local = { ...defaults, ...(saved || {}) };
    return {
      ...local,
      nickname: saved?.nickname && saved.nickname !== "谢广周" ? local.nickname : (meta.nickname || meta.display_name || local.nickname),
    };
  } catch (_err) {
    return defaults;
  }
}

function getWentianUrlParams(source) {
  const raw = String(source || "").replace(/^[?#]/, "");
  return new URLSearchParams(raw);
}

function hasWentianAuthParams(params) {
  return ["access_token", "refresh_token", "code", "error", "error_code", "error_description"].some((key) => params.has(key));
}

function isWentianAuthCallbackUrl() {
  return hasWentianAuthParams(getWentianUrlParams(window.location.hash)) || hasWentianAuthParams(getWentianUrlParams(window.location.search));
}

function getWentianAuthCallbackError() {
  const hashParams = getWentianUrlParams(window.location.hash);
  const searchParams = getWentianUrlParams(window.location.search);
  return hashParams.get("error_description") || searchParams.get("error_description") || hashParams.get("error") || searchParams.get("error") || "";
}

function getWentianAuthCallbackValue(key) {
  const hashValue = getWentianUrlParams(window.location.hash).get(key);
  if (hashValue) return hashValue;
  return getWentianUrlParams(window.location.search).get(key);
}

function buildWentianAuthSessionFromCallback() {
  const accessToken = getWentianAuthCallbackValue("access_token");
  const refreshToken = getWentianAuthCallbackValue("refresh_token");
  if (!accessToken || !refreshToken) return null;
  const expiresIn = Number(getWentianAuthCallbackValue("expires_in") || 3600);
  const expiresAt = Number(getWentianAuthCallbackValue("expires_at"))
    || Math.floor(Date.now() / 1000) + (Number.isFinite(expiresIn) ? expiresIn : 3600);
  return {
    access_token: accessToken,
    refresh_token: refreshToken,
    expires_at: expiresAt,
    expires_in: Number.isFinite(expiresIn) ? expiresIn : null,
    token_type: getWentianAuthCallbackValue("token_type") || "bearer",
    user: null,
  };
}

function clearWentianAuthReturnState() {
  try {
    localStorage.removeItem(WENTIAN_AUTH_RETURN_KEY);
  } catch (_err) {}
}

function getWentianAuthReturnState() {
  try {
    const raw = localStorage.getItem(WENTIAN_AUTH_RETURN_KEY);
    const saved = raw ? JSON.parse(raw) : null;
    if (!saved || Date.now() - Number(saved.ts || 0) > 10 * 60 * 1000) {
      clearWentianAuthReturnState();
      return null;
    }
    return saved;
  } catch (_err) {
    clearWentianAuthReturnState();
    return null;
  }
}

function setWentianAuthReturnState(data = {}) {
  try {
    localStorage.setItem(WENTIAN_AUTH_RETURN_KEY, JSON.stringify({ ...data, ts: Date.now() }));
  } catch (_err) {}
}

function getWentianExternalReturnUrl(returnState) {
  if (!returnState?.returnUrl) return "";
  try {
    const url = new URL(returnState.returnUrl, window.location.origin);
    if (url.origin !== window.location.origin) return "";
    if (url.pathname !== "/yl.html") return "";
    return url.href;
  } catch (_err) {
    return "";
  }
}

function completeWentianExternalAuthReturn(returnState) {
  const returnUrl = getWentianExternalReturnUrl(returnState);
  if (!returnUrl) return false;
  clearWentianAuthReturnState();
  window.location.href = returnUrl;
  return true;
}

function replaceWentianUrlRoute(route) {
  const params = new URLSearchParams(window.location.search);
  ["code", "state", "error", "error_code", "error_description", "auth", "screen"].forEach((key) => params.delete(key));
  const query = params.toString();
  const nextUrl = `${window.location.pathname}${query ? `?${query}` : ""}#${route}`;
  window.history.replaceState(null, "", nextUrl);
}

function replaceCurrentWentianRoute(route) {
  const nextRoute = resolveRoute(route);
  replaceWentianUrlRoute(nextRoute);
  navigate(nextRoute, false, false);
}

function returnToPreviousWentianRoute(fallbackRoute = "screen-1") {
  const previousRoute = state.stack[state.stack.length - 1];
  if (previousRoute && window.history.length > 1) {
    window.history.back();
    return;
  }
  const targetRoute = previousRoute || fallbackRoute;
  if (previousRoute) state.stack.pop();
  navigate(targetRoute, false);
}

function getWentianGoogleRedirectUrl() {
  return getWentianAppUrl();
}

function readWentianStoredSession() {
  try {
    const raw = localStorage.getItem(WENTIAN_AUTH_SESSION_KEY);
    const session = raw ? JSON.parse(raw) : null;
    return session?.access_token && session?.user ? session : null;
  } catch (_err) {
    return null;
  }
}

function saveWentianAuthSession(session) {
  try {
    if (session?.access_token && session?.refresh_token) {
      localStorage.setItem(WENTIAN_AUTH_SESSION_KEY, JSON.stringify(session));
    } else {
      localStorage.removeItem(WENTIAN_AUTH_SESSION_KEY);
    }
  } catch (_err) {}
}

function setWentianAuthSession(session) {
  const previousUserId = wentianAuthSession?.user?.id || "";
  const storedUserId = readWentianStoredSession()?.user?.id || "";
  const nextUserId = session?.user?.id || "";
  const guestChartTransfer = nextUserId
    ? captureWentianGuestChartTransfer({ explicitGuest: Boolean(previousUserId || storedUserId) })
    : null;
  wentianAuthSession = session || null;
  saveWentianAuthSession(session);
  const appliedGuestChartTransfer = guestChartTransfer ? applyWentianGuestChartTransfer(guestChartTransfer) : null;
  wentianMemberState.loaded = false;
  wentianOrderState.loaded = false;
  wentianInviteState.loaded = false;
  if (previousUserId !== nextUserId || appliedGuestChartTransfer) {
    wentianArchiveRemoteLoaded = false;
    wentianArchiveRemoteLoadedScope = "";
    if (nextUserId && typeof window !== "undefined") {
      window.setTimeout(() => {
        if ((wentianAuthSession?.user?.id || "") === nextUserId) {
          hydrateWentianArchivesFromRemote({
            force: true,
            rerender: true,
            forcePush: Boolean(appliedGuestChartTransfer),
            guestTransfer: appliedGuestChartTransfer,
          });
        }
      }, 0);
    }
  }
}

function isWentianSessionExpiring(session) {
  if (!session?.expires_at) return false;
  return Date.now() >= (Number(session.expires_at) * 1000) - WENTIAN_AUTH_REFRESH_SKEW_MS;
}

function phoneToWentianEmail(phone) {
  const digits = String(phone || "").replace(/\D/g, "");
  if (!digits || digits.length < 6 || digits.length > 20) return "";
  return `phone_${digits}@yuetianai.local`;
}

function inputToWentianAuthEmail(value) {
  const raw = String(value || "").trim();
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(raw)) return raw.toLowerCase();
  return phoneToWentianEmail(raw);
}

function syncWentianAuthDraftFromDom() {
  const accountInput = document.getElementById("wentian-auth-phone");
  const passwordInput = document.getElementById("wentian-auth-password");
  if (accountInput) wentianAuthState.account = accountInput.value || "";
  if (passwordInput) wentianAuthState.password = passwordInput.value || "";
}

function clearWentianAuthDraft() {
  wentianAuthState.account = "";
  wentianAuthState.password = "";
}

function getWentianAuthStatusText() {
  if (wentianAuthState.error) return wentianAuthState.error;
  const pendingInviteCode = getWentianPendingInviteCode();
  return pendingInviteCode ? `已记录邀请码 ${pendingInviteCode}，登录后自动绑定` : "";
}

function getWentianAuthStatusTone() {
  if (wentianAuthState.error) return "error";
  return getWentianPendingInviteCode() ? "notice" : "";
}

function syncWentianAuthUi() {
  const status = document.getElementById("wentian-auth-status");
  if (status) {
    status.textContent = getWentianAuthStatusText();
    status.dataset.tone = getWentianAuthStatusTone();
  }
  const submitText = document.getElementById("source-login-submit-text");
  if (submitText) {
    submitText.textContent = wentianAuthState.loading
      ? "处理中..."
      : (wentianAuthState.mode === "register" ? "注册并登录" : "登录并继续");
  }
  const submitBox = document.getElementById("source-login-submit");
  if (submitBox) {
    submitBox.style.background = wentianAuthState.loading
      ? "#d8c7aa"
      : "linear-gradient(180deg,#b74e39,#983323)";
    submitBox.style.boxShadow = wentianAuthState.loading
      ? "0 8px 18px rgba(120,94,46,.10)"
      : "0 12px 24px rgba(158,61,43,.16)";
  }
  const submitHit = document.getElementById("source-login-submit-hit");
  if (submitHit) {
    submitHit.disabled = wentianAuthState.loading;
    submitHit.style.pointerEvents = wentianAuthState.loading ? "none" : "auto";
  }
}

function normalizeWentianAuthErrorMessage(message) {
  const text = String(message || "").trim();
  if (!text) return "登录失败";
  if (/invalid login credentials|invalid credentials|wrong password|密码错误|密码有误/i.test(text)) {
    return "密码有误，请重新输入";
  }
  return text;
}

function getWentianAuthUserLabel(session = wentianAuthSession) {
  const user = session?.user;
  if (!user) return "";
  return user.user_metadata?.phone || user.email || "已登录";
}

function getWentianAuthDisplay() {
  const profile = getWentianProfile();
  const session = wentianAuthSession?.user ? wentianAuthSession : readWentianStoredSession();
  if (session?.user && !wentianAuthSession) wentianAuthSession = session;
  const label = getWentianAuthUserLabel(session);
  if (!session?.user) {
    return {
      loggedIn: false,
      name: "登录/注册",
      sub: "登录 / 注册后可支付与同步订单",
      email: "未登录",
      initial: "登",
    };
  }
  const nickname = profile.nickname && !["谢广周", "Guest"].includes(profile.nickname) ? profile.nickname : label;
  return {
    loggedIn: true,
    name: nickname || "已登录",
    sub: "账号已登录",
    email: label,
    initial: (nickname || label || "问").slice(0, 1),
  };
}

function getWentianCompactAccountTitle(account = {}) {
  const rawName = String(account.name || "").trim();
  const rawEmail = String(account.email || "").trim();
  if (!rawName) return "";
  if (rawEmail && rawName === rawEmail && rawEmail.includes("@")) {
    const local = rawEmail.split("@")[0] || rawEmail;
    return local.length > 14 ? `${local.slice(0, 14)}…` : local;
  }
  return rawName;
}

async function getWentianAuthSession(options = {}) {
  const current = wentianAuthSession || readWentianStoredSession();
  if (current && !options.force && !isWentianSessionExpiring(current)) {
    wentianAuthSession = current;
    return current;
  }
  if (!current?.refresh_token) {
    wentianAuthSession = current || null;
    return wentianAuthSession;
  }
  try {
    const data = await wentianFetchJson("/api/auth/refresh", {
      method: "POST",
      body: { refreshToken: current.refresh_token },
      noAuth: true,
    });
    setWentianAuthSession(data?.session || null);
    return wentianAuthSession;
  } catch (_err) {
    setWentianAuthSession(null);
    return null;
  }
}

async function getWentianAuthToken() {
  const session = await getWentianAuthSession();
  return session?.access_token || "";
}

async function getWentianAuthHeaders() {
  const token = await getWentianAuthToken();
  return token ? { Authorization: `Bearer ${token}` } : {};
}

function refreshWentianAuthScreens() {
  if (["screen-1", "screen-22", "screen-24", "screen-30", "screen-31", "screen-33", "screen-34", "screen-38", "screen-39", "screen-40", "screen-41", "screen-48"].includes(state.route)) {
    navigatePreservingScroll(state.route, false);
  }
}

async function initWentianAuth() {
  if (wentianAuthReadyPromise) return wentianAuthReadyPromise;
  wentianAuthReadyPromise = getWentianAuthSession().then((session) => {
    setWentianAuthSession(session || null);
    if (wentianAuthSession?.user) {
      window.setTimeout(() => bindWentianPendingInvite({ rerender: true }), 80);
      window.setTimeout(() => hydrateWentianInvite({ force: true, rerender: true }), 160);
    }
    return wentianAuthSession;
  }).catch(() => null);
  return wentianAuthReadyPromise;
}

async function requireWentianAuth() {
  const session = await getWentianAuthSession();
  if (session?.user) return session;
  wentianAuthState.mode = "login";
  wentianAuthState.error = "请先登录后再支付，会员和订单会绑定到账号。";
  wentianPendingPaymentAfterLogin = true;
  navigate("screen-40");
  return null;
}

function openWentianLogoutConfirm() {
  wentianLogoutConfirmOpen = true;
  navigate("screen-38", false);
}

function closeWentianLogoutConfirm() {
  wentianLogoutConfirmOpen = false;
  navigate("screen-38", false);
}

function setWentianPasswordStatus(text, tone = "") {
  wentianPasswordState.status = text || "";
  wentianPasswordState.error = tone === "error" ? text || "" : "";
  wentianPasswordState.tone = tone || "";
  const el = document.getElementById("wentian-password-status");
  if (!el) return;
  el.textContent = text || "";
  el.dataset.tone = tone;
}

function saveWentianProfile(profile) {
  try {
    localStorage.setItem(WENTIAN_PROFILE_STORAGE_KEY, JSON.stringify(profile));
  } catch (_err) {}
}

function setWentianProfileStatus(text, tone = "") {
  const el = document.getElementById("wentian-profile-status");
  if (!el) return;
  el.textContent = text;
  el.dataset.tone = tone;
}

function collectWentianProfileForm() {
  const nickname = (document.getElementById("wentian-profile-nickname")?.value || "").trim();
  const email = (document.getElementById("wentian-profile-email")?.value || "").trim();
  const phone = (document.getElementById("wentian-profile-phone")?.value || "").trim();
  if (!nickname) {
    return { error: getWentianLanguageCode() === "en" ? "Please enter a nickname." : "请填写昵称" };
  }
  if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return { error: getWentianLanguageCode() === "en" ? "Enter a valid email address." : "邮箱格式不正确" };
  }
  return { nickname, email, phone };
}

function submitWentianProfileForm() {
  const profile = collectWentianProfileForm();
  if (profile.error) {
    setWentianProfileStatus(profile.error, "error");
    return;
  }
  saveWentianProfile(profile);
  const isEn = getWentianLanguageCode() === "en";
  setWentianProfileStatus(
    wentianAuthSession?.user
      ? (isEn ? "Saved locally. You can sync it to your account below." : "已保存到本机，可点下方同步到账号")
      : (isEn ? "Saved locally." : "已保存到本机"),
    "ok"
  );
}

async function syncWentianProfileToAccount() {
  const profile = collectWentianProfileForm();
  if (profile.error) {
    setWentianProfileStatus(profile.error, "error");
    return;
  }
  saveWentianProfile(profile);
  const session = await getWentianAuthSession();
  if (!session?.user) {
    setWentianProfileStatus(getWentianLanguageCode() === "en" ? "Please sign in before syncing to your account." : "请先登录，再同步到账号", "error");
    return;
  }
  setWentianProfileStatus(getWentianLanguageCode() === "en" ? "Syncing to your account..." : "正在同步到账号...", "");
  try {
    const data = await wentianFetchJson("/api/auth/profile", {
      method: "POST",
      body: { profile },
    });
    if (data?.user) {
      setWentianAuthSession({ ...session, user: data.user });
    }
    setWentianProfileStatus(getWentianLanguageCode() === "en" ? "Synced to your account. It will follow you after signing in on another device." : "已同步到账号，换设备登录后可带出资料", "ok");
  } catch (error) {
    setWentianProfileStatus(error.message || (getWentianLanguageCode() === "en" ? "Sync failed. Please try again later." : "同步失败，请稍后重试"), "error");
  }
}

function getCurrentWentianArchive() {
  const archives = getWentianArchiveList();
  const current = getWentianSavedChart();
  const currentId = current?.archiveId || current?.form?.archiveId || "";
  const selectedId = currentId || getWentianSelectedArchiveId(archives);
  return archives.find((item) => item.id === selectedId) || archives[0] || null;
}

function applyWentianArchiveToCurrent(archive) {
  if (!archive) return false;
  const chartRecordId = archive.chartRecordId || archive.chartData?.chartRecordId || makeWentianUuid();
  try {
    setWentianScopedLocalStorageItem(WENTIAN_CHART_RECORD_STORAGE_KEY, chartRecordId);
  } catch (_err) {
    wentianFallbackChartRecordId = chartRecordId;
  }
  setWentianSelectedArchiveId(archive.id);
  saveWentianChart({
    archiveId: archive.id,
    chart: archive.chart || null,
    chartData: { ...archive.chartData, chartRecordId },
    form: { ...(archive.form || {}), archiveId: archive.id },
    createdAt: archive.createdAt || new Date().toISOString(),
  }, { upsertArchive: false });
  resetWentianXuChatRuntime();
  void pushWentianArchivesToRemote(getWentianArchiveList(), { statusOnError: true, verify: true });
  return true;
}

function setWentianArchiveAsDefault(id) {
  const archive = findWentianArchiveById(id);
  if (!archive || archive.id === getWentianStoredSelectedArchiveId()) return;
  wentianArchiveDeleteConfirmId = "";
  wentianArchiveDraftId = null;
  setWentianSelectedArchiveId(archive.id);
  const archives = markWentianArchiveDefault(sortWentianArchivesByDefault(getWentianArchiveList(), archive.id), archive.id);
  writeWentianArchives(archives);
  const selectedArchive = archives.find((item) => item.id === archive.id) || archive;
  if (!applyWentianArchiveToCurrent(selectedArchive)) return;
  navigatePreservingScroll(state.route, false);
}

function getWentianProfileConfirmLabel(id, archives = getWentianArchiveList()) {
  const archive = archives.find((item) => item.id === id) || archives[0] || null;
  if (!archive) return "";
  const name = getWentianArchiveDisplay(archive).name;
  return getWentianLanguageCode() === "en" ? `Selected: ${name}` : `已选：${name}`;
}

function updateWentianProfileSelectionDom(id) {
  for (const card of document.querySelectorAll(".wentian-profile-card[data-archive-id]")) {
    const selected = card.dataset.archiveId === id;
    card.classList.toggle("is-selected", selected);
    card.setAttribute("aria-pressed", selected ? "true" : "false");
    const pick = card.querySelector(".wentian-profile-pick");
    if (pick) pick.setAttribute("aria-pressed", selected ? "true" : "false");
    const check = card.querySelector(".wentian-archive-check");
    if (check) check.textContent = selected ? "✓" : "";
  }
  const label = getWentianProfileConfirmLabel(id);
  for (const node of document.querySelectorAll(".wentian-profile-confirm-name")) {
    node.textContent = label;
  }
}

function pickWentianProfileArchive(id) {
  const archives = getWentianArchiveList();
  if (!archives.some((archive) => archive.id === id)) return;
  wentianArchiveDraftId = id;
  wentianArchiveDeleteConfirmId = "";
  updateWentianProfileSelectionDom(id);
}

function pickWentianArchive(id) {
  wentianArchiveDraftId = id;
  for (const row of document.querySelectorAll("[data-wentian-archive-option]")) {
    const selected = row.dataset.archiveId === id;
    row.classList.toggle("is-selected", selected);
    row.setAttribute("aria-pressed", selected ? "true" : "false");
    const pick = row.querySelector(".wentian-archive-pick");
    if (pick) pick.setAttribute("aria-pressed", selected ? "true" : "false");
    const check = row.querySelector(".wentian-archive-check");
    if (check) check.textContent = selected ? "✓" : "";
  }
  requestAnimationFrame(() => revealWentianArchiveSelection(id));
}

function revealWentianArchiveSelection(id = wentianArchiveDraftId) {
  const list = document.querySelector(".wentian-archive-list");
  if (!(list instanceof HTMLElement) || !id) return;
  const selected = list.querySelector(`[data-wentian-archive-option][data-archive-id="${CSS.escape(id)}"]`);
  if (!(selected instanceof HTMLElement)) return;
  const maxScrollTop = Math.max(0, list.scrollHeight - list.clientHeight);
  const targetScrollTop = Math.min(maxScrollTop, Math.max(0, selected.offsetTop - 8));
  if (Math.abs((list.scrollTop || 0) - targetScrollTop) < 2) return;
  list.scrollTo({
    top: targetScrollTop,
    behavior: "smooth",
  });
}

function confirmWentianProfileSelection() {
  const archives = getWentianArchiveList();
  const id = wentianArchiveDraftId || getWentianSelectedArchiveId(archives);
  const archive = archives.find((item) => item.id === id) || archives[0];
  if (!archive) {
    setWentianArchiveStatus(
      getWentianCompactText("请先新建至少一个命盘", "Create a chart first"),
      "error"
    );
    refreshWentianArchiveStatusView();
    return;
  }
  resetWentianProfileBatchState();
  if (!applyWentianArchiveToCurrent(archive)) return;
  wentianArchiveDraftId = null;
  clearWentianXuChatContext();
  navigate("screen-27");
}

function confirmWentianArchiveSelection() {
  const archives = getWentianArchiveList();
  const id = wentianArchiveDraftId || getWentianSelectedArchiveId(archives);
  const archive = archives.find((item) => item.id === id) || archives[0];
  if (!archive) {
    setWentianArchiveStatus(
      getWentianCompactText("请先新建至少一个命盘", "Create a chart first"),
      "error"
    );
    refreshWentianArchiveStatusView();
    return;
  }
  if (!applyWentianArchiveToCurrent(archive)) return;
  wentianArchiveDraftId = null;
  clearWentianXuChatContext();
  navigate("screen-4");
}

function cancelWentianArchiveSelection() {
  wentianArchiveDraftId = null;
  returnToPreviousWentianRoute("screen-1");
}

function resetWentianXuChatRuntime() {
  if (wentianXuChat.typingTimer) {
    clearTimeout(wentianXuChat.typingTimer);
    wentianXuChat.typingTimer = null;
  }
  wentianXuChat.sessionId = null;
  wentianXuChat.sessionPromise = null;
  wentianXuChat.payloadKey = "";
  wentianXuChat.messages = [];
  wentianXuChat.loading = false;
  wentianXuChat.autoScroll = true;
  wentianXuChat.userPinned = false;
  wentianXuChat.contextSheetOpen = false;
  wentianXuChat.faqMode = "initial";
  wentianXuChat.suppressNextFaqFocus = false;
}

function getWentianXuChatContext() {
  if (wentianXuChat.context && (wentianXuChat.context.type === "liuyao" || wentianXuChat.context.type === "hepan" || wentianXuChat.context.type === "liuren")) return wentianXuChat.context;
  try {
    const parsed = JSON.parse(sessionStorage.getItem(WENTIAN_XU_CONTEXT_KEY) || "null");
    if ((parsed?.type === "liuyao" || parsed?.type === "hepan" || parsed?.type === "liuren") && isWentianUuid(parsed.recordId)) {
      wentianXuChat.context = parsed;
      return parsed;
    }
  } catch (_err) {}
  return null;
}

function setWentianXuChatContext(context) {
  wentianXuChat.context = context || null;
  try {
    if (context) sessionStorage.setItem(WENTIAN_XU_CONTEXT_KEY, JSON.stringify(context));
    else sessionStorage.removeItem(WENTIAN_XU_CONTEXT_KEY);
  } catch (_err) {}
  resetWentianXuChatRuntime();
}

function clearWentianXuChatContext() {
  setWentianXuChatContext(null);
}

function getWentianXuChatPayload() {
  const context = getWentianXuChatContext();
  if (context?.type === "liuyao" && isWentianUuid(context.recordId)) {
    const divinationChartData = {
      chartRecordId: context.recordId,
      chatMode: "liuyao",
      source: "六爻占卜",
      divinationContext: context,
    };
    return {
      mode: "liuyao",
      chartRecordId: context.recordId,
      chartData: divinationChartData,
      divinationContext: context,
    };
  }
  if (context?.type === "hepan" && isWentianUuid(context.recordId)) {
    const hepanChartData = {
      chartRecordId: context.recordId,
      chatMode: "hepan",
      source: context.title || "关系合盘",
      hepanContext: context,
      hepanRules: WENTIAN_HEPAN_AI_RULES,
      hepanDocTerms: context.docTerms || WENTIAN_HEPAN_DOC_TERMS,
      hepanRelationship: {
        label: context.relationLabel,
        displayTitle: context.relationDisplayTitle,
        note: context.relationNote,
        scope: context.relationScope,
        evidence: context.relationEvidence || [],
      },
      leftChart: context.left?.chart,
      rightChart: context.right?.chart,
    };
    return {
      mode: "hepan",
      chartRecordId: context.recordId,
      chartData: hepanChartData,
      divinationContext: context,
    };
  }
  if (context?.type === "liuren" && isWentianUuid(context.recordId)) {
    const liurenChartData = {
      chartRecordId: context.recordId,
      chatMode: "liuren",
      source: "六壬法",
      divinationContext: context,
    };
    return {
      mode: "liuren",
      chartRecordId: context.recordId,
      chartData: liurenChartData,
      divinationContext: context,
    };
  }
  if (context?.type === "yijing" && isWentianUuid(context.recordId)) {
    const baseChartData = getWentianChartPayload();
    const yijingChartData = {
      ...baseChartData,
      chartRecordId: context.recordId,
      sourceChartRecordId: context.sourceChartRecordId || baseChartData.chartRecordId,
      chatMode: "yijing",
      source: "易经推命",
      yijingContext: context,
    };
    return {
      mode: "yijing",
      chartRecordId: context.recordId,
      chartData: yijingChartData,
      divinationContext: context,
    };
  }
  const chartData = getWentianChartPayload();
  return {
    mode: "chart",
    chartRecordId: chartData.chartRecordId,
    chartData,
    divinationContext: null,
  };
}

function getWentianXuPayloadKey(payload) {
  if (!payload) return "";
  const contextRecordId = payload.divinationContext?.recordId || "";
  return [payload.mode || "chart", payload.chartRecordId || "", contextRecordId].join("|");
}

function ensureWentianXuPayloadRuntime(payload = getWentianXuChatPayload()) {
  const payloadKey = getWentianXuPayloadKey(payload);
  if (wentianXuChat.payloadKey && wentianXuChat.payloadKey !== payloadKey) resetWentianXuChatRuntime();
  wentianXuChat.payloadKey = payloadKey;
  return payloadKey;
}

function buildWentianXuOutboundMessage(message, context) {
  if (context?.type === "hepan") {
    return [
      "【关系合盘追问】",
      `本次不是单人命盘读盘，请只围绕本次${context.relationDisplayTitle || context.relationLabel || "关系合盘"}回答。`,
      "合盘前置规则：",
      context.rules || WENTIAN_HEPAN_AI_RULES,
      `固定合名范围：${WENTIAN_HEPAN_DOC_TERM_NAMES}。不在范围内的统一写“夫妻宫落X宫”，不要写命宫合、子女合、父母合。`,
      `关系类型：${context.relationDisplayTitle || context.relationLabel || ""}，${context.relationScope || ""}`,
      context.relationNote ? `关系备注：${context.relationNote}` : "",
      `宫位落点：${(context.relationEvidence || []).join("；")}`,
      `对象A：${context.left?.name || ""}，${context.left?.gender || ""}，${context.left?.datetime || ""}，${context.left?.age ?? ""}岁，四柱：${context.left?.pillars || ""}`,
      `对象A命盘摘要：${JSON.stringify(context.left?.chart || {})}`,
      `对象B：${context.right?.name || ""}，${context.right?.gender || ""}，${context.right?.datetime || ""}，${context.right?.age ?? ""}岁，四柱：${context.right?.pillars || ""}`,
      `对象B命盘摘要：${JSON.stringify(context.right?.chart || {})}`,
      `页面合盘：${context.score || ""}分，${context.level || ""}`,
      `维度：${(context.dimensions || []).map(([label, score, note]) => `${label}${score}分：${note}`).join("；")}`,
      context.advice ? `页面建议：${context.advice}` : "",
      "回答要求：先判断关系前提是否成立，再按关系类型讲互动点、冲突点、长期节奏和可执行建议。非情侣关系不得输出婚恋、暧昧、结婚或同居判断。",
      "",
      `我的追问：${message}`,
    ].filter(Boolean).join("\n");
  }
  if (context?.type === "liuren") {
    return [
      "【六壬法追问】",
      "请按小六壬当下课式回答，不要提紫微、命盘或六爻纳甲。",
      "如果用户没有说清具体事情，先请他补一句所问之事；但仍可按当前落宫给方向。",
      `起课时间：${context.castAtText || "未记录"}`,
      `农历课时：${context.lunarText || ""} · ${context.hourName || ""}时`,
      `顺推路径：${context.formula || ""}`,
      `月令落宫：${context.monthPalace || ""}`,
      `日辰落宫：${context.dayPalace || ""}`,
      `时辰落宫：${context.palaceName || ""}（${context.nature || ""}）`,
      `关键词：${(context.keys || []).join("、")}`,
      context.summary ? `页面初判：${context.summary}` : "",
      context.advice ? `页面建议：${context.advice}` : "",
      "回答要求：先一句话断核心结果，再讲成败快慢、阻力和下一步。不要长篇，不要说“结合命盘”。",
      "",
      `我的追问：${message}`,
    ].filter(Boolean).join("\n");
  }
  if (context?.type === "yijing") {
    return [
      "【易经推命追问】",
      "请结合当前命盘和易经推命模块回答，重点围绕当前卦象、先后天/流年位置与命盘主线。",
      `当前模块：${context.tabTitle || ""}`,
      `卦象：${context.hexagramName || ""}`,
      context.liunianHeadline ? `流年：${context.liunianHeadline}` : "",
      context.original ? `古籍原文：${context.original}` : "",
      context.masterTitle ? `名师讲解标题：${context.masterTitle}` : "",
      context.detail ? `名师讲解：${context.detail}` : "",
      "回答要求：先用白话给结论，再讲依据和行动建议；不要长篇照抄原文。英文模式下只输出自然英文。",
      "",
      `我的追问：${message}`,
    ].filter(Boolean).join("\n");
  }
  if (context?.type !== "liuyao") return message;
  return [
    "【六爻占卜追问】",
    "请按六爻占卜专批来断，围绕所问之事、本卦、变卦、动爻和页面初判回答；不要提紫微或命盘。",
    `所问之事：${context.question || "未填写"}`,
    `起卦时间：${context.castAtText || "未记录"}`,
    `本卦：${context.primaryText || ""}`,
    `变卦：${context.changedText || ""}`,
    `动爻：${context.movingText || "无"}`,
    `六爻：${context.linesText || ""}`,
    context.primaryOriginalText ? `本卦原文：${context.primaryOriginalText}` : "",
    context.changedOriginalText ? `变卦原文：${context.changedOriginalText}` : "",
    context.advice ? `页面初判：${context.advice}` : "",
    "回答格式：先断这件事，再讲变化点，再给应对和取舍。不要说“结合命盘”。",
    "",
    `我的追问：${message}`,
  ].filter(Boolean).join("\n");
}

function getWentianTransientKey(recordId = getWentianXuChatPayload().chartRecordId) {
  return `wentian-xudashi-transient:${recordId}`;
}

function loadWentianTransientState(recordId) {
  try {
    const raw = sessionStorage.getItem(getWentianTransientKey(recordId));
    return raw ? JSON.parse(raw) : null;
  } catch (_err) {
    return null;
  }
}

function saveWentianTransientState(state, recordId) {
  try {
    if (state) sessionStorage.setItem(getWentianTransientKey(recordId), JSON.stringify(state));
    else sessionStorage.removeItem(getWentianTransientKey(recordId));
  } catch (_err) {}
}

function waitWentian(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function isWentianRetryableError(error) {
  const text = `${error?.name || ""} ${error?.message || ""}`.toLowerCase();
  return /abort|timeout|failed to fetch|network|load failed/.test(text);
}

function getWentianFriendlyError(error) {
  if (isWentianRetryableError(error)) return "网络有点慢，许大师刚才没接上，请再点一次发送。";
  return error?.message || "许大师暂时不可用";
}

function flattenWentianReplyCandidate(value) {
  if (typeof value === "string") return value.trim();
  if (Array.isArray(value)) {
    return value.map(flattenWentianReplyCandidate).filter(Boolean).join("\n").trim();
  }
  if (!value || typeof value !== "object") return "";
  return flattenWentianReplyCandidate(
    value.reply
      ?? value.finalAnswer
      ?? value.answer
      ?? value.output_text
      ?? value.output
      ?? value.text
      ?? value.content
      ?? value.message
      ?? value.data
      ?? value.result
      ?? value.assistant
      ?? value.choices?.[0]?.message
      ?? ""
  );
}

function extractWentianReplyText(data) {
  const direct = [
    data?.reply,
    data?.finalAnswer,
    data?.answer,
    data?.output,
    data?.content,
    data?.message,
    data?.data,
    data?.result,
    data?.assistant,
    data?.choices,
  ];
  for (const item of direct) {
    const text = flattenWentianReplyCandidate(item);
    if (text) return text;
  }
  const historyLists = [data?.messages, data?.transientState?.messages];
  for (const history of historyLists) {
    if (!Array.isArray(history)) continue;
    const assistant = history.slice().reverse().find((item) => {
      const role = item?.role || item?.sender;
      return role === "assistant";
    });
    const text = flattenWentianReplyCandidate(assistant?.content || assistant?.text || assistant?.reply || "");
    if (text) return text;
  }
  return "";
}

function getWentianEmptyReplyText() {
  return "这轮回复没有生成完整内容，问题已保留，请再点一次发送。";
}

async function wentianPostJsonOnce(path, payload, timeoutMs) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(new DOMException("request timeout", "TimeoutError")), timeoutMs);
  try {
    const headers = { "Content-Type": "application/json", ...getWentianClientHeaders() };
    const token = await getWentianAuthToken();
    if (token) headers.Authorization = `Bearer ${token}`;
    const response = await fetch(`${getWentianApiBase()}${path}`, {
      method: "POST",
      headers,
      body: JSON.stringify(payload),
      signal: controller.signal,
    });
    const contentType = String(response.headers.get("content-type") || "");
    const data = contentType.includes("application/json")
      ? await response.json()
      : { error: await response.text() };
    if (!response.ok || data.error) throw new Error(data.error || `许大师服务异常 ${response.status}`);
    return data;
  } finally {
    clearTimeout(timer);
  }
}

async function wentianPostJson(path, payload, timeoutMs = 90000, retries = 1) {
  let lastError = null;
  for (let attempt = 0; attempt <= retries; attempt += 1) {
    try {
      return await wentianPostJsonOnce(path, payload, timeoutMs);
    } catch (error) {
      lastError = error;
      if (attempt >= retries || !isWentianRetryableError(error)) break;
      await waitWentian(900 + attempt * 700);
    }
  }
  if (lastError) lastError.userMessage = getWentianFriendlyError(lastError);
  throw lastError;
}

async function wentianFetchJson(path, options = {}) {
  const method = options.method || (options.body ? "POST" : "GET");
  const headers = {
    ...(options.body ? { "Content-Type": "application/json" } : { "Accept": "application/json" }),
    ...getWentianClientHeaders(),
  };
  if (options.authToken) {
    headers.Authorization = `Bearer ${options.authToken}`;
  } else if (!options.noAuth) {
    const token = await getWentianAuthToken();
    if (token) headers.Authorization = `Bearer ${token}`;
  }
  const response = await fetch(`${getWentianApiBase()}${path}`, {
    method,
    headers,
    body: options.body ? JSON.stringify(options.body) : undefined,
  });
  const contentType = String(response.headers.get("content-type") || "");
  const data = contentType.includes("application/json")
    ? await response.json()
    : { error: await response.text() };
  if (!response.ok || data.error) throw new Error(data.error || `服务异常 ${response.status}`);
  return data;
}

function refreshWentianInviteScreens() {
  if (["screen-22", "screen-24", "screen-31", "screen-34", "screen-40"].includes(state.route)) {
    navigatePreservingScroll(state.route, false);
  }
}

async function hydrateWentianInvite(options = {}) {
  if (wentianInviteState.loading && !options.force) return wentianInviteReadyPromise;
  if (wentianInviteState.loaded && !options.force) return wentianInviteState.summary || getWentianInviteSnapshot();
  const before = JSON.stringify({
    loaded: wentianInviteState.loaded,
    error: wentianInviteState.error,
    summary: wentianInviteState.summary,
  });
  const refreshIfChanged = () => {
    const after = JSON.stringify({
      loaded: wentianInviteState.loaded,
      error: wentianInviteState.error,
      summary: wentianInviteState.summary,
    });
    if (options.rerender && before !== after) refreshWentianInviteScreens();
  };
  const session = await getWentianAuthSession();
  if (!session?.user) {
    wentianInviteState.loaded = true;
    wentianInviteState.loading = false;
    wentianInviteState.error = "";
    wentianInviteState.summary = getWentianInviteSnapshot();
    refreshIfChanged();
    return wentianInviteState.summary;
  }
  wentianInviteState.loading = true;
  wentianInviteState.error = "";
  wentianInviteReadyPromise = wentianFetchJson("/api/referrals/summary")
    .then((data) => {
      wentianInviteState.loaded = true;
      wentianInviteState.summary = data;
      return data;
    })
    .catch((error) => {
      wentianInviteState.loaded = true;
      wentianInviteState.error = error.message || "邀请记录读取失败";
      return getWentianInviteSnapshot();
    })
    .finally(() => {
      wentianInviteState.loading = false;
      refreshIfChanged();
    });
  return wentianInviteReadyPromise;
}

function setWentianInviteStatus(text, tone = "") {
  wentianInviteState.status = text || "";
  ["wentian-invite-status", "wentian-share-status"].forEach((id) => {
    const el = document.getElementById(id);
    if (!el) return;
    el.textContent = wentianInviteState.status;
    el.dataset.tone = tone;
  });
}

function requireWentianInviteAccount() {
  if (wentianAuthSession?.user) return true;
  wentianAuthState.mode = "register";
  navigate("screen-40");
  return false;
}

async function bindWentianInviteCode(code, options = {}) {
  const normalized = normalizeWentianInviteCode(code);
  if (!isWentianInviteCode(normalized)) {
    setWentianInviteStatus("请输入正确的邀请码", "error");
    return null;
  }
  const session = await getWentianAuthSession();
  if (!session?.user) {
    setWentianPendingInviteCode(normalized);
    wentianAuthState.mode = "register";
    setWentianInviteStatus("已记录邀请码，登录/注册后自动绑定。", "ok");
    if (options.rerender) navigate("screen-40");
    return null;
  }
  try {
    const data = await wentianFetchJson("/api/referrals/bind", {
      method: "POST",
      body: { inviteCode: normalized },
    });
    clearWentianPendingInviteCode();
    setWentianLocalInviteStatus({ inviteCode: data.inviteCode, boundAt: data.invitedAt || new Date().toISOString() });
    setWentianInviteStatus(data.message || "邀请码已绑定", "ok");
    await hydrateWentianInvite({ force: true, rerender: options.rerender });
    return data;
  } catch (error) {
    setWentianInviteStatus(error.message || "邀请码绑定失败", "error");
    return null;
  }
}

async function bindWentianPendingInvite(options = {}) {
  const code = getWentianPendingInviteCode();
  if (!isWentianInviteCode(code)) return null;
  return bindWentianInviteCode(code, options);
}

async function writeWentianClipboardText(text) {
  if (navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(text);
    return true;
  }
  const input = document.createElement("textarea");
  input.value = text;
  input.style.position = "fixed";
  input.style.opacity = "0";
  input.style.pointerEvents = "none";
  document.body.appendChild(input);
  input.focus();
  input.select();
  const copied = document.execCommand("copy");
  input.remove();
  return copied;
}

async function copyWentianText(text, okText, failText = "复制失败，请长按文本手动复制", failTone = "error") {
  const isEn = getWentianLanguageCode() === "en";
  try {
    const copied = await writeWentianClipboardText(text);
    if (!copied) throw new Error("copy failed");
    setWentianInviteStatus(isEn ? (okText || "Copied.") : (okText || "已复制"), "ok");
    return true;
  } catch (_err) {
    setWentianInviteStatus(isEn ? "Copy blocked by the browser. Long-press the text above to copy it." : failText, failTone);
    return false;
  }
}

