function resizeWentianChatInput(input) {
  if (!input) return 0;
  const minHeight = 48;
  const maxHeight = 118;
  input.style.height = `${minHeight}px`;
  const nextHeight = Math.max(minHeight, Math.min(maxHeight, input.scrollHeight || minHeight));
  input.style.height = `${nextHeight}px`;
  input.style.overflowY = input.scrollHeight > maxHeight ? "auto" : "hidden";
  return nextHeight - minHeight;
}

function applyWentianChatFaqModeClass(starters, mode) {
  if (!starters) return;
  const safeMode = ["initial", "compact", "expanded"].includes(mode) ? mode : "initial";
  starters.dataset.wentianFaqMode = safeMode;
  starters.classList.toggle("is-compact", safeMode === "compact");
  starters.classList.toggle("is-mode-initial", safeMode === "initial");
  starters.classList.toggle("is-mode-expanded", safeMode === "expanded");
}

function setWentianChatFaqTitleVisible(visible) {
  const faqTitle = document.querySelector('[data-node-id="source-4-faq-title"]');
  if (faqTitle) faqTitle.style.display = visible ? "" : "none";
}

function setWentianChatFaqMode(mode, options = {}) {
  const safeMode = ["initial", "compact", "expanded"].includes(mode) ? mode : "initial";
  wentianXuChat.faqMode = safeMode;
  const starters = document.querySelector(".wentian-chat-starters");
  if (!starters) return;
  applyWentianChatFaqModeClass(starters, safeMode);
  const groups = Array.from(starters.querySelectorAll(".wentian-chat-faq-group"));
  if (safeMode === "compact") {
    groups.forEach((group) => group.removeAttribute("open"));
  }
  if (safeMode === "expanded" && options.openGroupLabel) {
    const openLabel = String(options.openGroupLabel || "").trim();
    let didOpen = false;
    groups.forEach((group) => {
      const label = group.querySelector(".wentian-chat-faq-summary span")?.textContent?.trim() || "";
      const shouldOpen = label === openLabel;
      if (shouldOpen) {
        group.setAttribute("open", "");
        didOpen = true;
      } else {
        group.removeAttribute("open");
      }
    });
    if (!didOpen && options.openFirst) groups[0]?.setAttribute("open", "");
  }
  if (safeMode === "expanded" && options.openFirst && !groups.some((group) => group.open)) {
    groups[0]?.setAttribute("open", "");
  }
  setWentianChatFaqTitleVisible(safeMode !== "compact");
  syncWentianChatFaqLayout();
}

function expandWentianChatFaqFromInput() {
  if (wentianXuChat.loading) return;
  if (wentianXuChat.suppressNextFaqFocus) {
    wentianXuChat.suppressNextFaqFocus = false;
    return;
  }
  if (wentianXuChat.faqMode === "compact") {
    setWentianChatFaqMode("expanded", { openFirst: true });
  }
}

function syncWentianChatFaqLayout() {
  const phone = document.querySelector('.figma-phone[data-node-id="screen-4"]');
  const starters = document.querySelector(".wentian-chat-starters");
  const faqTitle = document.querySelector('[data-node-id="source-4-faq-title"]');
  const log = document.getElementById("wentian-chat-messages");
  const scrollBottom = document.getElementById("wentian-chat-scroll-bottom");
  const inputBg = document.querySelector('[data-node-id="source-4-input-bg"]');
  const input = document.getElementById("wentian-chat-input");
  const send = document.getElementById("wentian-chat-send");
  const disclaimer = document.querySelector('[data-node-id="source-4-disclaimer"]');
  if (!phone || !starters || !faqTitle || !log || !inputBg || !input || !send || !disclaimer) return;

  const faqMode = starters.dataset.wentianFaqMode || getWentianChatFaqModeForRender();
  const isCompact = faqMode === "compact";
  applyWentianChatFaqModeClass(starters, faqMode);
  setWentianChatFaqTitleVisible(!isCompact);

  const openGroup = isCompact ? null : starters.querySelector(".wentian-chat-faq-group[open]");
  const naturalListHeight = Math.ceil(starters.scrollHeight || 0);
  const baseListHeight = isCompact ? 42 : faqMode === "expanded" ? 180 : Math.max(160, Math.min(184, naturalListHeight || 174));
  const basePhoneHeight = 892;
  const basePositions = {
    faqTitle: 582,
    starters: 608,
    inputBg: 790,
    input: 804,
    send: 812,
    disclaimer: 862,
  };

  const inputExtra = resizeWentianChatInput(input);
  const fieldHeight = 48 + inputExtra;
  const desktop = window.matchMedia?.("(min-width: 881px)")?.matches || false;
  const viewportHeight = Math.max(window.innerHeight || 0, window.visualViewport?.height || 0);
  const viewportWidth = window.visualViewport?.width || window.innerWidth || document.documentElement.clientWidth || WENTIAN_PHONE_WIDTH;
  const currentScale = Number.parseFloat(getComputedStyle(phone).getPropertyValue("--wentian-phone-scale"));
  const fallbackScale = Math.max(0.78, Math.min(1, viewportWidth / WENTIAN_PHONE_WIDTH));
  const phoneScale = Number.isFinite(currentScale) && currentScale > 0 ? currentScale : fallbackScale;
  const visiblePhoneHeight = viewportHeight ? Math.floor(viewportHeight / phoneScale) : basePhoneHeight;

  starters.classList.toggle("is-expanded", Boolean(openGroup));

  if (!desktop) {
    const inputBgHeight = 102 + inputExtra;
    const phoneHeight = Math.max(680 + inputExtra, Math.min(basePhoneHeight + inputExtra, visiblePhoneHeight || basePhoneHeight));
    const inputBgTop = Math.min(basePositions.inputBg, Math.max(560, phoneHeight - inputBgHeight));
    const starterBottom = inputBgTop - (isCompact ? 14 : 24);
    const startersTop = isCompact
      ? Math.max(408, starterBottom - baseListHeight)
      : Math.max(408, Math.min(basePositions.starters, starterBottom - baseListHeight));
    const minStartersHeight = isCompact ? 42 : 112;
    const startersHeight = Math.max(minStartersHeight, Math.min(baseListHeight, starterBottom - startersTop));
    const faqTitleTop = Math.max(382, startersTop - 26);
    const logTop = Number.parseFloat(getComputedStyle(log).top) || (log.classList.contains("is-with-context") ? 224 : 136);
    const logBottomLimit = isCompact ? startersTop : faqTitleTop;
    const logHeight = Math.max(log.classList.contains("is-with-context") ? 132 : 210, logBottomLimit - logTop - 24);

    phone.style.height = `${phoneHeight}px`;
    log.style.height = `${logHeight}px`;
    if (scrollBottom) scrollBottom.style.top = `${logTop + logHeight - 6}px`;
    faqTitle.style.top = `${faqTitleTop}px`;
    starters.style.top = `${startersTop}px`;
    starters.style.maxHeight = `${startersHeight}px`;
    starters.style.overflow = "hidden auto";
    inputBg.style.top = `${inputBgTop}px`;
    inputBg.style.height = `${inputBgHeight}px`;
    input.style.top = `${inputBgTop + 14}px`;
    send.style.top = `${inputBgTop + 14 + fieldHeight - 40}px`;
    disclaimer.style.top = `${inputBgTop + 72 + inputExtra}px`;
    scheduleWentianPhoneFit();
    return;
  }

  starters.style.overflow = "";
  starters.style.maxHeight = isCompact ? `${baseListHeight}px` : openGroup ? "none" : "";
  starters.style.top = isCompact ? `${basePositions.inputBg - baseListHeight - 14}px` : "";
  faqTitle.style.top = "";
  log.style.height = "";
  if (scrollBottom) scrollBottom.style.top = "";

  const listHeight = isCompact ? baseListHeight : openGroup ? Math.ceil(starters.scrollHeight) : baseListHeight;
  const faqExtra = !isCompact && openGroup ? Math.max(0, listHeight - baseListHeight + 18) : 0;
  const totalExtra = faqExtra + inputExtra;

  phone.style.height = `${basePhoneHeight + totalExtra}px`;
  inputBg.style.top = `${basePositions.inputBg + faqExtra}px`;
  inputBg.style.height = `${102 + inputExtra}px`;
  input.style.top = `${basePositions.input + faqExtra}px`;
  send.style.top = `${basePositions.input + faqExtra + fieldHeight - 40}px`;
  disclaimer.style.top = `${basePositions.disclaimer + totalExtra}px`;
  scheduleWentianPhoneFit();
}

function setWentianQuota(quota) {
  const el = document.querySelector('[data-node-id="source-4-left"]');
  if (quota) wentianMemberState.quota = normalizeWentianQuota({ ...(wentianMemberState.quota || {}), ...quota });
  if (!el || !quota) return;
  if (getWentianXuChatContext()) return;
  const normalized = wentianMemberState.quota || normalizeWentianQuota(quota);
  const remainingValue = getWentianQuotaRemaining(normalized, "--");
  const remaining = remainingValue === null || remainingValue === undefined || remainingValue === "" ? "--" : remainingValue;
  el.textContent = isWentianEnglishUi()
    ? (remaining === "--" ? "Quota" : `${remaining} left`)
    : `余${remaining}次`;
}

function splitWentianLongSentence(sentence, maxLength = 58) {
  const chunks = String(sentence || "").match(/[^，、,]+[，、,]?/g) || [sentence];
  const groups = [];
  let current = "";
  for (const chunk of chunks) {
    if (current && current.length + chunk.length > maxLength) {
      groups.push(current.trim());
      current = "";
    }
    current += chunk;
  }
  if (current.trim()) groups.push(current.trim());
  return groups;
}

function splitWentianReplyParagraphs(text) {
  const raw = String(text || "").replace(/\r/g, "").trim();
  if (!raw) return [""];
  const explicitBlocks = raw.includes("\n")
    ? raw.split(/\n+/).map((item) => item.trim()).filter(Boolean)
    : [raw.replace(/\s+/g, " ").trim()];
  const paragraphs = [];

  for (const block of explicitBlocks) {
    const sentences = block.match(/[^。！？!?；;]+[。！？!?；;]?/g) || [block];
    const pieces = sentences.flatMap((sentence) => sentence.length > 76 ? splitWentianLongSentence(sentence) : [sentence.trim()]);
    let current = "";
    let sentenceCount = 0;
    for (const piece of pieces.filter(Boolean)) {
      const shouldBreak = current && (current.length + piece.length > 70 || sentenceCount >= 1);
      if (shouldBreak) {
        paragraphs.push(current.trim());
        current = "";
        sentenceCount = 0;
      }
      current += piece;
      sentenceCount += 1;
    }
    if (current.trim()) paragraphs.push(current.trim());
  }

  return paragraphs.length ? paragraphs : [raw];
}

function stripWentianEnglishUiText(text) {
  const preserved = preserveWentianAllowedGlossaryParentheses(text);
  const stripped = preserved.text
    .replace(/[（(][^()（）]*[\u3400-\u9fff][^()（）]*[)）]/g, "")
    .replace(/[\u3400-\u9fff]+/g, "")
    .replace(/[，。！？；：、【】《》“”‘’￥…—]/g, "")
    .replace(/([.!?])(?=[A-Z])/g, "$1 ")
    .replace(/\(\s*\)/g, "")
    .replace(/^[)\]）]+/gm, "")
    .replace(/[（(][^()（）]*$/g, "")
    .replace(/[ \t]+([,.;:!?])/g, "$1")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]{2,}/g, " ")
    .trim();
  return restoreWentianAllowedGlossaryParentheses(stripped, preserved.placeholders);
}

function isWentianMeaningfulEnglishText(text) {
  const raw = String(text || "").trim();
  if (!raw) return false;
  const letters = (raw.match(/[A-Za-z]/g) || []).length;
  const words = (raw.match(/[A-Za-z][A-Za-z'-]{1,}/g) || []).length;
  const visible = raw.replace(/\s/g, "").length || 1;
  return letters >= 16 && words >= 4 && letters / visible >= 0.35;
}

function isWentianEnglishAssistantFailureText(text) {
  return /clean English answer|send your question again|Regenerate in English|Chinese text has not been translated/i.test(String(text || ""));
}

function normalizeWentianEnglishAssistantText(text) {
  const cleaned = stripWentianEnglishUiText(text);
  if (isWentianMeaningfulEnglishText(cleaned)) return cleaned;
  return "I did not receive a clean English answer. Please send your question again, and I will answer in English only.";
}

function renderWentianChatMessageContent(message, role) {
  const rawText = String(message.text || "");
  if (role !== "assistant") return escapeHtml(rawText);
  if (message.pending) {
    const pendingText = isWentianEnglishMode() ? "Master Xu is reading the chart..." : (rawText || "许大师正在解读");
    return `
      <span class="wentian-chat-thinking">
        <i></i><i></i><i></i>
        <em>${escapeHtml(pendingText)}</em>
      </span>
    `;
  }
  const shouldNormalizeEnglishAssistant = role === "assistant" && isWentianEnglishMode() && !message.typing;
  const text = shouldNormalizeEnglishAssistant ? normalizeWentianEnglishAssistantText(rawText) : rawText;
  return splitWentianReplyParagraphs(text)
    .map((paragraph) => `<p>${renderWentianSafeInlineMarkdown(paragraph)}</p>`)
    .join("");
}

function getWentianChatUserAvatarText() {
  const account = getWentianAuthDisplay();
  const archive = getCurrentWentianArchive();
  const display = getWentianArchiveDisplay(archive);
  const label = account.loggedIn ? account.initial : (display.name || account.initial || "我");
  return String(label || "我").trim().slice(0, 1) || "我";
}

function isWentianChatNearBottom(box, threshold = 48) {
  if (!box) return true;
  return box.scrollHeight - box.scrollTop - box.clientHeight <= threshold;
}

function updateWentianChatScrollButton() {
  const btn = document.getElementById("wentian-chat-scroll-bottom");
  if (!btn) return;
  btn.classList.toggle("is-visible", !!wentianXuChat.userPinned);
}

function syncWentianChatScrollState() {
  const box = document.getElementById("wentian-chat-messages");
  if (!box) return;
  const nearBottom = isWentianChatNearBottom(box);
  wentianXuChat.autoScroll = nearBottom;
  wentianXuChat.userPinned = !nearBottom;
  updateWentianChatScrollButton();
}

function scrollWentianChatToBottom(force = false) {
  const box = document.getElementById("wentian-chat-messages");
  if (!box) return;
  if (!force && !wentianXuChat.autoScroll) return;
  requestAnimationFrame(() => {
    if (!force && !wentianXuChat.autoScroll) return;
    box.scrollTop = box.scrollHeight;
    wentianXuChat.autoScroll = true;
    wentianXuChat.userPinned = false;
    updateWentianChatScrollButton();
  });
}

function bindWentianChatScrollBox() {
  const box = document.getElementById("wentian-chat-messages");
  if (!box || box.dataset.scrollBound === "1") return;
  box.dataset.scrollBound = "1";
  box.addEventListener("scroll", syncWentianChatScrollState, { passive: true });
}

function renderWentianMessages(options = {}) {
  const box = document.getElementById("wentian-chat-messages");
  if (!box) return;
  const shouldStick = options.forceScroll || wentianXuChat.autoScroll || isWentianChatNearBottom(box);
  box.innerHTML = wentianXuChat.messages.map((message) => {
    const role = message.role === "user" ? "user" : message.role === "system" ? "system" : "assistant";
    const avatar = role === "user" ? ` data-avatar="${escapeHtml(getWentianChatUserAvatarText())}"` : "";
    const pendingClass = message.pending ? "is-pending" : "";
    return `<div class="wentian-chat-msg is-${role} ${message.typing ? "is-typing" : ""} ${pendingClass}"${avatar}>${renderWentianChatMessageContent(message, role)}</div>`;
  }).join("");
  bindWentianChatScrollBox();
  if (shouldStick) scrollWentianChatToBottom(!!options.forceScroll);
  else updateWentianChatScrollButton();
}

function finishWentianTyping(render = true) {
  if (wentianXuChat.typingTimer) {
    clearTimeout(wentianXuChat.typingTimer);
    wentianXuChat.typingTimer = null;
  }
  const typingMessage = wentianXuChat.messages.find((message) => message.typing);
  if (typingMessage) {
    typingMessage.text = typingMessage.fullText || typingMessage.text || "";
    typingMessage.typing = false;
    typingMessage.pending = false;
    delete typingMessage.fullText;
  }
  if (render) renderWentianMessages();
}

function startWentianTyping(message) {
  if (wentianXuChat.typingTimer) {
    clearTimeout(wentianXuChat.typingTimer);
    wentianXuChat.typingTimer = null;
  }
  wentianXuChat.messages.forEach((item) => {
    if (item !== message && item.typing) {
      item.text = item.fullText || item.text || "";
      item.typing = false;
      item.pending = false;
      delete item.fullText;
    }
  });
  const fullText = message.fullText || "";
  let index = 0;
  const tick = () => {
    if (!wentianXuChat.messages.includes(message)) return;
    if (index >= fullText.length) {
      message.typing = false;
      message.pending = false;
      delete message.fullText;
      wentianXuChat.typingTimer = null;
      renderWentianMessages();
      return;
    }
    const char = fullText[index];
    index += 1;
    message.text = fullText.slice(0, index);
    renderWentianMessages();
    const delay = /[。！？!?]/.test(char) ? 120 : /[，、；;：:\n]/.test(char) ? 55 : 18;
    wentianXuChat.typingTimer = setTimeout(tick, delay);
  };
  tick();
}

function addWentianMessage(role, text, options = {}) {
  const rawText = String(text || "");
  const safeText = role === "assistant" && isWentianEnglishMode()
    ? normalizeWentianEnglishAssistantText(rawText)
    : rawText;
  const message = options.typewriter && role === "assistant"
    ? { role, text: "", fullText: safeText, typing: true }
    : { role, text: safeText };
  if (options.pending) message.pending = true;
  wentianXuChat.messages.push(message);
  if (wentianXuChat.messages.length > 30) wentianXuChat.messages.shift();
  renderWentianMessages({ forceScroll: !!options.forceScroll });
  if (message.typing) startWentianTyping(message);
}

function setWentianChatBusy(busy) {
  wentianXuChat.loading = busy;
  const input = document.getElementById("wentian-chat-input");
  const send = document.getElementById("wentian-chat-send");
  if (input) input.disabled = busy;
  if (send) send.disabled = busy;
}

function getWentianXuModeText(mode, phase = "ready") {
  const map = {
    liuyao: { connecting: "接入占卜中…", ready: "占卜已接入", typing: "许大师正在看卦…" },
    hepan: { connecting: "接入合盘中…", ready: "合盘已接入", typing: "许大师正在看合盘…" },
    liuren: { connecting: "接入六壬中…", ready: "六壬已接入", typing: "许大师正在看课…" },
    yijing: { connecting: "接入易经推命中…", ready: "易经推命已接入", typing: "许大师正在看这组卦…" },
    chart: { connecting: "接入中…", ready: "已连接", typing: "许大师正在看盘…" },
  };
  return (map[mode] || map.chart)[phase] || map.chart[phase] || "";
}

function getWentianXuOpeningText(payload = getWentianXuChatPayload()) {
  if (isWentianEnglishMode()) {
    if (payload.mode === "liuyao") return "I have the hexagram loaded. Ask your follow-up in English.";
    if (payload.mode === "hepan") return "I have the compatibility chart loaded. Ask your relationship question in English.";
    if (payload.mode === "liuren") return "I have the Liuren reading loaded. Ask your follow-up in English.";
    if (payload.mode === "yijing") return "I have this hexagram reading loaded. Ask your follow-up in English.";
    return "I am here. Ask about your chart.";
  }
  if (payload.mode === "liuyao") return getLiuyaoXuOpeningMessage(payload.divinationContext);
  if (payload.mode === "hepan") return getHepanXuOpeningMessage(payload.divinationContext);
  if (payload.mode === "liuren") return getLiurenXuOpeningMessage(payload.divinationContext);
  if (payload.mode === "yijing") return `这组${payload.divinationContext?.summaryLine || "易经推命"}已接入。你可以继续问成败、应期、家宅、六亲或下一步怎么做。`;
  return "我在，看命盘直接问。";
}

async function ensureWentianXuSession(options = {}) {
  const silent = !!options.silent;
  const payload = getWentianXuChatPayload();
  const payloadKey = getWentianXuPayloadKey(payload);
  if (wentianXuChat.payloadKey && wentianXuChat.payloadKey !== payloadKey) resetWentianXuChatRuntime();
  wentianXuChat.payloadKey = payloadKey;
  if (wentianXuChat.sessionId) return wentianXuChat.sessionId;
  if (wentianXuChat.sessionPromise) return wentianXuChat.sessionPromise;

  if (!silent) setWentianChatStatus(getWentianXuModeText(payload.mode, "connecting"));
  const languageParams = getWentianAiLanguageParams();
  wentianXuChat.sessionPromise = wentianPostJson("/api/ai/chat/session", {
    chartRecordId: payload.chartRecordId,
    chartData: { ...payload.chartData, ...languageParams },
    chatMode: payload.mode,
    divinationContext: payload.divinationContext,
    ...languageParams,
    extraParams: languageParams,
    transientState: loadWentianTransientState(payload.chartRecordId),
  }, 90000, 1).then((data) => {
    wentianXuChat.sessionId = data.sessionId || `transient:${payload.chartRecordId}`;
    if (data.transientState) saveWentianTransientState(data.transientState, payload.chartRecordId);
    setWentianQuota(data.quota);
    setWentianChatStatus(data.transientMode ? "临时会话" : getWentianXuModeText(payload.mode, "ready"), data.transientMode ? "warn" : "ok");
    if (!wentianXuChat.messages.length) {
      const historyMessages = Array.isArray(data.messages)
        ? data.messages.slice(-12).map((item) => ({
          role: item.sender === "user" ? "user" : item.sender === "system" ? "system" : "assistant",
          text: item.content || "",
        })).filter((item) => {
          if (!isWentianEnglishMode()) return true;
          if (hasWentianDisallowedEnglishHanText(item.text)) return false;
          return !(item.role === "assistant" && isWentianEnglishAssistantFailureText(item.text));
        })
        : [];
      if (historyMessages.length) {
        wentianXuChat.messages = historyMessages;
      } else {
        addWentianMessage("assistant", getWentianXuOpeningText(payload));
      }
      renderWentianMessages();
    }
    return wentianXuChat.sessionId;
  }).catch((error) => {
    if (silent) {
      setWentianChatStatus("已接入", "ok");
    } else {
      setWentianChatStatus("暂时未连上", "error");
      if (!wentianXuChat.messages.length) addWentianMessage("system", `连接失败：${getWentianFriendlyError(error)}`);
    }
    throw error;
  }).finally(() => {
    wentianXuChat.sessionPromise = null;
  });
  return wentianXuChat.sessionPromise;
}

async function sendWentianXuChat(promptText = "") {
  if (wentianXuChat.loading) return;
  finishWentianTyping(false);
  const input = document.getElementById("wentian-chat-input");
  const message = (promptText || input?.value || "").trim();
  if (!message) return;
  if (input) {
    input.value = "";
    syncWentianChatFaqLayout();
    if (isWentianMobileKeyboardViewport()) input.blur();
  }
  setWentianChatFaqMode("compact");

  const payload = getWentianXuChatPayload();
  ensureWentianXuPayloadRuntime(payload);
  const outboundMessage = buildWentianXuOutboundMessage(message, payload.divinationContext);
  window.yuetianTrack?.("ai_question_submit", { surface: "wentian_mobile", chat_mode: payload.mode || "chart" });
  wentianXuChat.autoScroll = true;
  wentianXuChat.userPinned = false;
  addWentianMessage("user", message, { forceScroll: true });
  addWentianMessage("assistant", getWentianXuModeText(payload.mode, "typing"), { pending: true, forceScroll: true });
  setWentianChatBusy(true);

  try {
    await ensureWentianXuSession({ silent: false });
    const languageParams = getWentianAiLanguageParams();
    const data = await wentianPostJson("/api/ai/chat/send", {
      chartRecordId: payload.chartRecordId,
      message: outboundMessage,
      displayMessage: message,
      chartData: { ...payload.chartData, ...languageParams },
      chatMode: payload.mode,
      divinationContext: payload.divinationContext,
      ...languageParams,
      extraParams: languageParams,
      transientState: loadWentianTransientState(payload.chartRecordId),
    }, 70000, 0);
    wentianXuChat.messages.pop();
    wentianXuChat.sessionId = data.sessionId || wentianXuChat.sessionId || `transient:${payload.chartRecordId}`;
    if (data.transientState) saveWentianTransientState(data.transientState, payload.chartRecordId);
    setWentianQuota(data.quota);
    setWentianChatStatus(data.transientMode ? "临时会话" : getWentianXuModeText(payload.mode, "ready"), data.transientMode ? "warn" : "ok");
    const replyText = extractWentianReplyText(data);
    if (replyText) window.yuetianTrack?.("ai_answer_success", { surface: "wentian_mobile", chat_mode: payload.mode || "chart" });
    if (!replyText) setWentianChatStatus("回复未生成", "warn");
    addWentianMessage("assistant", replyText || getWentianEmptyReplyText(), { typewriter: true });
  } catch (error) {
    wentianXuChat.messages.pop();
    setWentianChatStatus("发送未完成", "error");
    addWentianMessage("system", getWentianFriendlyError(error));
  } finally {
    setWentianChatBusy(false);
    if (!isWentianMobileKeyboardViewport()) {
      wentianXuChat.suppressNextFaqFocus = true;
      input?.focus();
    }
  }
}

function initWentianXuChat() {
  const input = document.getElementById("wentian-chat-input");
  const send = document.getElementById("wentian-chat-send");
  if (!input || !send) return;

  const payload = getWentianXuChatPayload();
  ensureWentianXuPayloadRuntime(payload);
  const saved = getWentianSavedChart();
  const archiveDisplay = payload.mode === "chart" ? getWentianArchiveDisplay(getCurrentWentianArchive()) : null;
  const sizhu = payload.mode === "chart" ? saved?.chartData?.sizhu : null;
  if (sizhu) {
    const stems = [sizhu.yearStem, sizhu.monthStem, sizhu.dayStem, sizhu.hourStem];
    const branches = [sizhu.yearBranch, sizhu.monthBranch, sizhu.dayBranch, sizhu.hourBranch];
    stems.forEach((text, index) => {
      const el = document.querySelector(`[data-node-id="source-4-bazi-top-${index}"]`);
      if (el) el.textContent = text || "—";
    });
    branches.forEach((text, index) => {
      const el = document.querySelector(`[data-node-id="source-4-bazi-bottom-${index}"]`);
      if (el) el.textContent = text || "—";
    });
    const archiveName = archiveDisplay?.name || saved.form?.name || payload.chartData?.name || "";
    const nameEl = document.querySelector('[data-node-id="source-4-bazi-name"]');
    if (nameEl) nameEl.textContent = `${archiveName || "当前"}的八字`;
    const profileEl = document.querySelector('[data-node-id="source-4-profile-text"]');
    const compactArchiveName = isWentianEnglishUi()
      ? archiveName.replace(/\s*[·•-]\s*(?:Age\s*)?\d+\s*(?:岁|歲)?\s*$/i, "")
      : archiveName;
    if (profileEl && compactArchiveName) profileEl.textContent = compactArchiveName;
    const profileSubEl = document.querySelector('[data-node-id="source-4-profile-sub"]');
    if (profileSubEl) profileSubEl.textContent = "切换";
    const footEl = document.querySelector('[data-node-id="source-4-bazi-foot"]');
    if (footEl) footEl.textContent = `日主：${sizhu.dayStem || "—"}    生肖：${saved.chartData?.zodiac || "—"}`;
  }

  send.onclick = () => sendWentianXuChat();
  input.addEventListener("input", syncWentianChatFaqLayout);
  input.addEventListener("focus", expandWentianChatFaqFromInput);
  input.addEventListener("click", expandWentianChatFaqFromInput);
  input.onkeydown = (event) => {
    if (event.key === "Enter" && (event.metaKey || event.ctrlKey)) {
      event.preventDefault();
      sendWentianXuChat();
    }
  };

  if (!wentianXuChat.messages.length) {
    addWentianMessage("assistant", getWentianXuOpeningText(payload));
  } else {
    renderWentianMessages();
  }
  setWentianChatStatus(getWentianXuModeText(payload.mode, "ready"), "ok");
  syncWentianChatFaqLayout();
  ensureWentianXuSession({ silent: true }).catch(() => {});
}

function formatWentianMemberDate(value) {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  return `${date.getFullYear()}-${padWentianNumber(date.getMonth() + 1)}-${padWentianNumber(date.getDate())}`;
}

function getWentianQuotaValue(key, fallback = "--") {
  const quota = wentianMemberState.quota || {};
  const value = quota[key];
  return value === null || value === undefined || value === "" ? fallback : value;
}

function getWentianQuotaMode(quota = wentianMemberState.quota || {}) {
  return quota.quotaMode || (quota.isMember ? "daily" : "lifetime");
}

function getWentianQuotaLimit(quota = wentianMemberState.quota || {}, fallback = "--") {
  const value = getWentianQuotaMode(quota) === "daily"
    ? (quota.dailyLimit ?? quota.limit)
    : (quota.lifetimeLimit ?? quota.limit);
  return value === null || value === undefined || value === "" ? fallback : value;
}

function getWentianQuotaRemaining(quota = wentianMemberState.quota || {}, fallback = "--") {
  const value = getWentianQuotaMode(quota) === "daily"
    ? (quota.dailyRemaining ?? quota.remaining)
    : (quota.lifetimeRemaining ?? quota.remaining);
  return value === null || value === undefined || value === "" ? fallback : value;
}

function normalizeWentianQuota(quota) {
  if (!quota) return quota;
  if (quota.testingUnlimited) return quota;
  const isMember = !!quota.isMember;
  const quotaMode = getWentianQuotaMode(quota);
  const fallbackLimit = isMember
    ? (quota.plan === "unlimited" ? WENTIAN_UNLIMITED_DAILY_LIMIT : WENTIAN_PAID_DAILY_LIMIT)
    : (quota.plan === "guest" ? WENTIAN_GUEST_LIFETIME_LIMIT : WENTIAN_FREE_LIFETIME_LIMIT);
  const rawLimit = Number(quotaMode === "daily" ? (quota.dailyLimit ?? quota.limit) : (quota.lifetimeLimit ?? quota.limit));
  const limit = Number.isFinite(rawLimit) && rawLimit > 0 ? rawLimit : fallbackLimit;
  const rawRemaining = Number(quotaMode === "daily"
    ? (quota.dailyRemaining ?? quota.remaining)
    : (quota.lifetimeRemaining ?? quota.remaining));
  const rawUsed = Number(quotaMode === "daily"
    ? (quota.dailyUsed ?? quota.used)
    : (quota.lifetimeUsed ?? quota.used));
  const used = Number.isFinite(rawUsed) ? Math.max(0, Math.min(limit, rawUsed)) : 0;
  const remaining = Number.isFinite(rawRemaining) ? Math.max(0, rawRemaining) : Math.max(0, limit - used);
  return quotaMode === "daily"
    ? { ...quota, quotaMode, dailyLimit: limit, dailyUsed: used, dailyRemaining: remaining, limit, remaining }
    : { ...quota, quotaMode, lifetimeLimit: limit, lifetimeUsed: used, lifetimeRemaining: remaining, limit, remaining };
}

function getWentianMemberSnapshot() {
  const quota = wentianMemberState.quota || {};
  const product = wentianMemberState.product || {};
  const isMember = !!quota.isMember;
  const quotaPending = !wentianMemberState.loaded && !wentianMemberState.quota;
  const isGuest = quota.plan === "guest" || !getWentianAuthDisplay().loggedIn;
  const quotaMode = getWentianQuotaMode(quota);
  const defaultLimit = isMember
    ? (quota.plan === "unlimited" ? WENTIAN_UNLIMITED_DAILY_LIMIT : WENTIAN_PAID_DAILY_LIMIT)
    : (isGuest ? WENTIAN_GUEST_LIFETIME_LIMIT : WENTIAN_FREE_LIFETIME_LIMIT);
  const limit = getWentianQuotaLimit(quota, defaultLimit);
  const remaining = getWentianQuotaRemaining(quota, limit);
  const planName = isMember ? (quota.planName || WENTIAN_PAID_PRODUCT_NAME) : (isGuest ? "未登录体验" : "免费用户");
  const chartLimit = quota.chartLimit == null && isMember ? null : Number(quota.chartLimit || 1);
  const chartUsed = Math.max(0, Number(quota.chartUsage?.used || 0));
  return {
    isMember,
    title: planName,
    subtitle: isMember
      ? `有效期至 ${formatWentianMemberDate(quota.memberExpiresAt) || "当前周期"}`
      : `${isGuest ? "未登录" : "已登录"} · 共${limit}次追问`,
    quotaMode,
    daily: quotaPending ? "同步中" : `${remaining}/${limit}`,
    dailyLimit: quotaPending ? "同步中" : `${limit}次${quotaMode === "daily" ? "/天" : ""}`,
    quotaLabel: quotaMode === "daily" ? "今日追问" : "可用追问",
    limitLabel: quotaMode === "daily" ? "每日次数" : "全部次数",
    chartLimit,
    chartUsed,
    chartText: chartLimit == null ? `已用${chartUsed}位` : `${chartUsed}/${chartLimit}位命主`,
    productName: isMember ? planName : WENTIAN_PAID_PRODUCT_NAME,
    amountYuan: product.amountYuan || "19.90",
    description: WENTIAN_PAID_PRODUCT_DESC,
  };
}

function formatWentianQuotaTextForUi(value, isEn = isWentianEnglishUi()) {
  const raw = String(value ?? "");
  if (!isEn) return raw;
  if (!raw || raw === "同步中") return "Syncing";
  return raw
    .replace(/测试不限/g, "Test unlimited")
    .replace(/今日已满/g, "No uses left")
    .replace(/今日剩余\s*/g, "")
    .replace(/每日额度\s*/g, "")
    .replace(/次\s*\/\s*天/g, "/day")
    .replace(/次/g, " uses")
    .trim();
}

function getWentianPaymentProviders() {
  const list = Array.isArray(wentianMemberState.providers) ? wentianMemberState.providers : [];
  const byKey = new Map(list.map((item) => [item.provider, item]));
  const alipayMeta = byKey.get("alipay") || {};
  const alipayLabel = alipayMeta.label || "\u652f\u4ed8\u5b9d";
  return [
    { provider: "wechat", label: "微信支付", enabled: true, ...(byKey.get("wechat") || {}) },
    { ...alipayMeta, provider: "alipay", label: "支付宝", enabled: alipayMeta.enabled !== false },
    { provider: "paypal", label: "PayPal", enabled: false, ...(byKey.get("paypal") || {}) },
  ].map((item) => (item.provider === "alipay" ? { ...item, label: alipayLabel } : item));
}

function getWentianPaymentProviderMeta(provider = wentianPaymentState.provider) {
  return getWentianPaymentProviders().find((item) => item.provider === provider) || getWentianPaymentProviders()[0];
}

function setWentianPayProviderNodeState(provider, item, options) {
  if (!view) return;
  const active = wentianPaymentState.provider === provider;
  const disabled = !item.enabled;
  const box = view.querySelector(`[data-node-id="${options.boxPrefix}-${provider}"]`);
  const text = view.querySelector(`[data-node-id="${options.textPrefix}-${provider}${options.textSuffix || ""}"]`);
  const hit = view.querySelector(`[data-node-id="${options.hitPrefix}-${provider}${options.hitSuffix || ""}"]`);
  if (box) {
    box.style.borderColor = active ? options.activeBorder : "#eadfce";
    box.style.background = active ? "#fff3d9" : "#fffdf8";
  }
  if (text) text.style.color = disabled ? "#b4aaa0" : (active ? "#8f3d30" : "#756d63");
  if (hit) hit.setAttribute("aria-pressed", active ? "true" : "false");
}

function setWentianNodeText(nodeId, text) {
  const node = view?.querySelector?.(`[data-node-id="${nodeId}"]`);
  if (node) node.textContent = text;
}

function refreshWentianPayProviderSelection() {
  const providers = getWentianPaymentProviders();
  providers.forEach((item) => {
    setWentianPayProviderNodeState(item.provider, item, {
      boxPrefix: "wt33-pay-method",
      textPrefix: "wt33-pay-method-text",
      hitPrefix: "wt33-pay-method-hit",
      activeBorder: "#c8a65f",
    });
    setWentianPayProviderNodeState(item.provider, item, {
      boxPrefix: "wt33-preview-method",
      textPrefix: "wt33-preview-method-text",
      hitPrefix: "wt33-preview-method-hit",
      activeBorder: "#d9b87a",
    });
    setWentianPayProviderNodeState(item.provider, item, {
      boxPrefix: "wt29",
      textPrefix: "wt29",
      hitPrefix: "wt29",
      textSuffix: "-text",
      hitSuffix: "-hit",
      activeBorder: "#c8a65f",
    });
  });
  const paymentPrice = getWentianSelectedPaymentPrice();
  const member = getWentianMemberSnapshot();
  const buttonText = member.isMember
    ? `续费月卡 ${paymentPrice.text}`
    : `选择月卡 ${paymentPrice.text}`;
  setWentianNodeText("wt33-card-price", paymentPrice.text);
  setWentianNodeText("wt33-submit-text", buttonText);
  setWentianNodeText("wt33-preview-card-value-0", paymentPrice.text);
  setWentianNodeText("wt33-preview-submit-text", buttonText);
}

function getWentianPaymentProviderLabel() {
  return getWentianPaymentProviderMeta().label || (wentianPaymentState.provider === "paypal" ? "PayPal" : (wentianPaymentState.provider === "alipay" ? "支付宝" : "微信支付"));
}

function getWentianPaymentProviderAppLabel() {
  return getWentianPaymentProviderLabel().replace(/支付$/, "");
}

function isWentianMobilePayDevice() {
  if (typeof navigator === "undefined") return false;
  const ua = navigator.userAgent || "";
  return /Android|iPhone|iPad|iPod|Mobile|MicroMessenger|AlipayClient/i.test(ua)
    || (typeof window !== "undefined" && window.matchMedia?.("(max-width: 768px)")?.matches);
}

function shouldUseWentianAipayResourceFlow(provider = wentianPaymentState.provider) {
  return false;
}

function getWentianPreferredPaymentProvider() {
  const providers = getWentianPaymentProviders();
  return providers.find((item) => item.provider === "alipay" && item.enabled)?.provider
    || providers.find((item) => item.enabled)?.provider
    || "wechat";
}

async function hydrateWentianMemberStatus(options = {}) {
  if (wentianMemberStatusPromise && !options.force) return wentianMemberStatusPromise;
  if (wentianMemberState.loaded && !options.force) return null;
  const chartRecordId = getWentianChartPayload().chartRecordId;
  const before = JSON.stringify({
    quota: wentianMemberState.quota,
    product: wentianMemberState.product,
  });
  wentianMemberStatusPromise = wentianFetchJson(`/api/payments/member-status?chartRecordId=${encodeURIComponent(chartRecordId)}`)
    .then((data) => {
      wentianMemberState.loaded = true;
      if (data.quota) wentianMemberState.quota = normalizeWentianQuota({ ...data.quota, chartUsage: data.chartUsage || null });
      if (data.product) wentianMemberState.product = data.product;
      if (Array.isArray(data.providers)) wentianMemberState.providers = data.providers;
      const currentProviderEnabled = !!getWentianPaymentProviderMeta(wentianPaymentState.provider)?.enabled;
      const canPreferAlipay = !wentianPaymentState.orderNo && wentianPaymentState.provider === "wechat";
      if (!currentProviderEnabled || canPreferAlipay) {
        wentianPaymentState.provider = getWentianPreferredPaymentProvider();
      }
      wentianMemberState.mockMode = !!data.mockMode;
      const after = JSON.stringify({
        quota: wentianMemberState.quota,
        product: wentianMemberState.product,
      });
      if (state.route === "screen-4") setWentianQuota(wentianMemberState.quota);
      if (options.rerender && before !== after && ["screen-27", "screen-30", "screen-31", "screen-33", "screen-38", "screen-40", "screen-41"].includes(state.route)) {
        navigatePreservingScroll(state.route, false);
      }
      return data;
    })
    .catch((error) => {
      console.info("wentian member status fallback", error);
      return null;
    })
    .finally(() => {
      wentianMemberStatusPromise = null;
    });
  return wentianMemberStatusPromise;
}

function getWentianPayMethod() {
  if (wentianPaymentState.provider === "paypal") return "redirect";
  return "native";
}

function formatWentianPaymentAmount(amount, currency = "CNY") {
  const value = escapeHtml(amount || "19.90");
  const code = String(currency || "CNY").toUpperCase();
  if (code === "CNY") return `¥${value}`;
  if (code === "USD") return `$${value}`;
  if (code === "HKD") return `HK$${value}`;
  if (code === "SGD") return `S$${value}`;
  return `${code} ${value}`;
}

function getWentianSelectedPaymentPrice(provider = wentianPaymentState.provider) {
  const product = wentianMemberState.product || {};
  const meta = getWentianPaymentProviderMeta(provider) || {};
  const fallback = provider === "paypal"
    ? { amountYuan: "2.99", currency: "USD" }
    : { amountYuan: product.amountYuan || "19.90", currency: product.currency || "CNY" };
  const amountYuan = meta.amountYuan || meta.amount || fallback.amountYuan;
  const currency = meta.currency || fallback.currency;
  return {
    amountYuan,
    currency,
    text: formatWentianPaymentAmount(amountYuan, currency),
  };
}

function stopWentianPaymentPoll() {
  if (wentianPaymentPollTimer) {
    clearInterval(wentianPaymentPollTimer);
    wentianPaymentPollTimer = null;
  }
}

function refreshWentianPaymentScreen() {
  if (state.route === "screen-30") navigate("screen-30", false);
}

function trackWentianPurchase(data = {}) {
  window.yuetianTrackPurchase?.({
    orderNo: data.orderNo || wentianPaymentState.orderNo,
    value: data.amountYuan || wentianPaymentState.amountYuan,
    currency: data.currency || wentianPaymentState.currency || "CNY",
    provider: data.provider || wentianPaymentState.provider,
    productKey: data.productKey || WENTIAN_MEMBER_PRODUCT_KEY,
    surface: "wentian_mobile",
    mockMode: data.mockMode ?? wentianPaymentState.mockMode,
  });
}

async function checkWentianPaymentStatus() {
  if (!wentianPaymentState.orderNo) return null;
  try {
    const data = await wentianFetchJson(`/api/payments/order-status?orderNo=${encodeURIComponent(wentianPaymentState.orderNo)}`);
    wentianPaymentState.status = data.status || wentianPaymentState.status;
    wentianPaymentState.message = data.status === "paid" ? "月卡已开通" : `等待${getWentianPaymentProviderLabel()}完成`;
    if (data.status === "paid") {
      trackWentianPurchase(data);
      stopWentianPaymentPoll();
      await hydrateWentianMemberStatus({ force: true });
    }
    refreshWentianPaymentScreen();
    return data;
  } catch (error) {
    wentianPaymentState.error = error.message || "订单查询失败";
    refreshWentianPaymentScreen();
    return null;
  }
}

function startWentianPaymentPoll() {
  stopWentianPaymentPoll();
  if (!wentianPaymentState.orderNo || wentianPaymentState.mockMode) return;
  wentianPaymentPollTimer = setInterval(checkWentianPaymentStatus, WENTIAN_PAYMENT_POLL_MS);
}

function openWentianUnifiedMemberPage(options = {}) {
  const currentQuery = new URLSearchParams(location.search || "");
  const returnQuery = new URLSearchParams();
  const language = currentQuery.get("lang");
  if (language) returnQuery.set("lang", language);
  const returnSearch = returnQuery.toString();
  const requestedReturnRoute = options.returnRoute ? resolveRoute(options.returnRoute) : "";
  const returnHash = /^screen-\d+$/.test(requestedReturnRoute)
    ? `#${requestedReturnRoute}`
    : (location.hash || "#screen-31");
  const from = `${location.pathname}${returnSearch ? `?${returnSearch}` : ""}${returnHash}`;
  const target = new URL(WENTIAN_UNIFIED_MEMBER_URL, location.origin);
  target.searchParams.set("source", "wentian-mobile");
  if (language) target.searchParams.set("lang", language);
  target.searchParams.set("returnUrl", from);
  target.hash = "member";
  clearWentianAuthReturnState();
  window.location.href = target.toString();
}

async function startWentianMemberPayment(options = {}) {
  openWentianUnifiedMemberPage(options);
}

function openWentianDeepReadingAccess() {
  const account = getWentianAuthDisplay();
  if (wentianMemberState.quota?.isMember) return true;
  if (!account.loggedIn) {
    wentianAuthState.mode = "login";
    wentianAuthState.error = "请先登录，登录后可查看完整基础解读。";
    navigate("screen-40");
    return false;
  }
  navigate("screen-33");
  return false;
}

function getWentianPayPalReturnParams() {
  const params = new URLSearchParams(location.search || "");
  if (params.get("paypal_return") !== "1") return null;
  const orderNo = (params.get("orderNo") || "").trim();
  const paypalOrderId = (params.get("token") || "").trim();
  if (!orderNo || !paypalOrderId) return null;
  return { orderNo, paypalOrderId };
}

function clearWentianPayPalReturnParams() {
  const clean = `${location.pathname}#screen-30`;
  history.replaceState(null, "", clean);
}

async function captureWentianPayPalReturn(params = getWentianPayPalReturnParams()) {
  if (!params) return;
  wentianPaymentState.provider = "paypal";
  wentianPaymentState.orderNo = params.orderNo;
  wentianPaymentState.status = "loading";
  wentianPaymentState.message = "正在确认 PayPal 支付...";
  wentianPaymentState.error = "";
  navigate("screen-30", false);
  try {
    const data = await wentianFetchJson("/api/payments/paypal/capture-order", {
      method: "POST",
      body: { orderNo: params.orderNo, paypalOrderId: params.paypalOrderId },
    });
    wentianPaymentState.status = data.status || "paid";
    if (wentianPaymentState.status === "paid") trackWentianPurchase(data);
    wentianPaymentState.message = data.status === "paid"
      ? "月卡已开通"
      : `等待${getWentianPaymentProviderLabel()}完成`;
    clearWentianPayPalReturnParams();
    await hydrateWentianMemberStatus({ force: true });
  } catch (error) {
    wentianPaymentState.status = "error";
    wentianPaymentState.error = error.message || "PayPal 支付确认失败";
  }
  refreshWentianPaymentScreen();
}

function openWentianPaymentUrl() {
  if (wentianPaymentState.payUrl) window.location.href = wentianPaymentState.payUrl;
}

async function completeWentianMockPayment() {
  if (!wentianPaymentState.orderNo) return;
  wentianPaymentState.message = "正在确认测试支付...";
  refreshWentianPaymentScreen();
  try {
    const data = await wentianFetchJson("/api/payments/mock/complete", {
      method: "POST",
      body: { orderNo: wentianPaymentState.orderNo },
    });
    wentianPaymentState.status = data.status || "paid";
    if (wentianPaymentState.status === "paid") trackWentianPurchase(data);
    wentianPaymentState.message = "月卡已开通";
    await hydrateWentianMemberStatus({ force: true });
  } catch (error) {
    wentianPaymentState.error = error.message || "测试支付失败";
  }
  refreshWentianPaymentScreen();
}

async function hydrateWentianOrders(options = {}) {
  const session = await getWentianAuthSession();
  if (!session?.user) {
    wentianOrderState.loaded = false;
    wentianOrderState.loading = false;
    wentianOrderState.orders = [];
    wentianOrderState.error = "";
    return null;
  }
  if (wentianOrderState.loading) return null;
  if (wentianOrderState.loaded && !options.force) return null;
  wentianOrderState.loading = true;
  wentianOrderState.error = "";
  if (options.rerender && state.route === "screen-48") navigatePreservingScroll("screen-48", false);
  try {
    const data = await wentianFetchJson("/api/payments/refunds");
    wentianOrderState.orders = Array.isArray(data.orders) ? data.orders : [];
    if (wentianRefundTicketState.open && data.policyText) {
      wentianRefundTicketState.message = isWentianEnglishUi()
        ? "Verified paid orders can be submitted directly and the screenshot is optional. Pending orders require a screenshot for manual review."
        : data.policyText;
    }
    wentianOrderState.loaded = true;
  } catch (error) {
    wentianOrderState.error = error.message || "订单读取失败";
  } finally {
    wentianOrderState.loading = false;
    if (options.rerender && state.route === "screen-48") navigatePreservingScroll("screen-48", false);
  }
  return wentianOrderState.orders;
}

function formatWentianDateInput(value) {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  const cn = new Date(date.getTime() + 8 * 60 * 60 * 1000);
  return cn.toISOString().slice(0, 10);
}

function getWentianRefundContactDefault() {
  const user = wentianAuthSession?.user || {};
  return user.user_metadata?.phone || user.email || "";
}

function getWentianRefundSelectedOrder() {
  return (wentianOrderState.orders || []).find((order) => order.orderNo === wentianRefundTicketState.orderNo) || null;
}

function isWentianRefundScreenshotRequired(order = getWentianRefundSelectedOrder()) {
  if (!order) return true;
  if (typeof order.requiresScreenshot === "boolean") return order.requiresScreenshot;
  return order.status !== "paid";
}

function syncWentianRefundTicketFromOrder(order = getWentianRefundSelectedOrder()) {
  if (!order) return;
  wentianRefundTicketState.orderNo = order.orderNo || "";
  wentianRefundTicketState.paymentProvider = ["wechat", "alipay", "paypal"].includes(order.provider) ? order.provider : wentianRefundTicketState.paymentProvider;
  wentianRefundTicketState.paidDate = formatWentianDateInput(order.paidAt || order.createdAt) || wentianRefundTicketState.paidDate;
}

function getWentianRefundOrderStatusLabel(order) {
  if (isWentianEnglishUi()) {
    if (order?.status === "paid") return "Paid";
    if (order?.status === "pending") return "Pending";
    if (order?.status === "created") return "Created";
    if (order?.status === "refunded") return "Refunded";
    return order?.status || "Processing";
  }
  if (order?.status === "paid") return "已支付";
  if (order?.status === "pending") return "待确认";
  if (order?.status === "created") return "刚创建";
  if (order?.status === "refunded") return "已退款";
  return order?.status || "处理中";
}

