const LIUYAO_STORAGE_KEY = "wentian-liuyao-state-v1";
const LIUYAO_SAMPLE_QUESTION = "事业近期是否适合推进新计划？";
const LIUYAO_DEFAULT_QUESTION = "";
const LIUYAO_QUESTION_MAX_LENGTH = 120;
const LIUYAO_DAILY_LIMIT = 3;
const LIUYAO_QUESTION_SUGGESTIONS = [
  "这个项目本月能不能继续推进并见到效果？",
  "这笔合作近期能不能谈成？",
  "我现在要不要换工作方向？",
  "这段关系接下来适不适合主动沟通？"
];
const LIUYAO_ZHOUYI_ORIGINALS = {
  15: {
    gua: "谦：亨，君子有终。",
    xiang: "象曰：地中有山，谦；君子以裒多益寡，称物平施。"
  },
  20: {
    gua: "观：盥而不荐，有孚颙若。",
    xiang: "象曰：风行地上，观；先王以省方，观民设教。"
  },
  46: {
    gua: "升：元亨。用见大人，勿恤。南征吉。",
    xiang: "象曰：地中生木，升；君子以顺德，积小以高大。"
  }
};
const LIUYAO_VALUES = [7, 8, 9, 6];
const LIUYAO_TOSS_ANIMATION_MS = 1000;
const LIUYAO_PULL_MAX = 132;
const LIUYAO_READY_POWER = 0.18;
const LIUYAO_SWIPE_THRESHOLD = Math.round(LIUYAO_PULL_MAX * LIUYAO_READY_POWER);
const LIUYAO_DEFAULT_POWER = 0.62;
const LIUYAO_TRIGRAM_BY_BITS = {
  "111": { gua: "乾", name: "天", key: "qian" },
  "110": { gua: "兑", name: "泽", key: "dui" },
  "101": { gua: "离", name: "火", key: "li" },
  "100": { gua: "震", name: "雷", key: "zhen" },
  "011": { gua: "巽", name: "风", key: "xun" },
  "010": { gua: "坎", name: "水", key: "kan" },
  "001": { gua: "艮", name: "山", key: "gen" },
  "000": { gua: "坤", name: "地", key: "kun" }
};

function getLiuyaoCastScreenHeight() {
  const state = getLiuyaoState();
  if (state.mode === "online" && liuyaoCastModalOpen) return 844;
  const question = normalizeLiuyaoQuestion(state.question);
  const gate = normalizeLiuyaoQuestionGate(state.questionGate, question);
  const progress = getLiuyaoProgress(state);
  if (!gate?.allowed && progress <= 0) return 844;
  if (state.mode === "manual") return 1180;
  return getLiuyaoResult(state) ? 1040 : 980;
}
const LIUYAO_LINE_LABELS = ["初爻", "二爻", "三爻", "四爻", "五爻", "上爻"];
const LIUYAO_MANUAL_EMPTY_COINS = [null, null, null];
let liuyaoState = null;
let liuyaoTossTimer = null;
let liuyaoTossAnimation = null;
let liuyaoSwipeStart = null;
let liuyaoQuestionGateLoading = false;
let liuyaoQuotaLoading = false;
let liuyaoCastModalOpen = false;
let liuyaoResetConfirmOpen = false;

function lockLiuyaoCasterScroll(locked) {
  document.body?.classList.toggle("liuyao-caster-open", Boolean(locked));
}

function setLiuyaoCasterModalOpen(open) {
  liuyaoCastModalOpen = Boolean(open);
  if (!liuyaoCastModalOpen) {
    liuyaoResetConfirmOpen = false;
    lockLiuyaoCasterScroll(false);
  }
}

function normalizeLiuyaoCast(raw) {
  const value = Number(raw?.value);
  if (!LIUYAO_VALUES.includes(value)) return null;
  const coins = Array.isArray(raw?.coins) && raw.coins.length === 3
    ? raw.coins.map(Number).map((coin) => coin === 3 ? 3 : 2)
    : value === 6 ? [2, 2, 2] : value === 7 ? [3, 2, 2] : value === 8 ? [3, 3, 2] : [3, 3, 3];
  const power = Math.max(0, Math.min(100, Math.round(Number(raw?.power) || 0)));
  const pull = Math.max(0, Math.min(LIUYAO_PULL_MAX, Math.round(Number(raw?.pull) || 0)));
  const duration = Math.max(0, Math.min(6000, Math.round(Number(raw?.duration) || 0)));
  return { value, coins, manual: Boolean(raw?.manual), at: Number(raw?.at) || Date.now(), power, pull, duration };
}

function normalizeLiuyaoCoinFace(value) {
  const face = Number(value);
  return face === 3 || face === 2 ? face : null;
}

function normalizeLiuyaoManualCoins(raw, casts = []) {
  return Array.from({ length: 6 }, (_, lineIndex) => {
    const cast = normalizeLiuyaoCast(casts[lineIndex]);
    const source = Array.isArray(raw?.[lineIndex]) ? raw[lineIndex] : (cast?.manual ? cast.coins : []);
    return [0, 1, 2].map((coinIndex) => normalizeLiuyaoCoinFace(source?.[coinIndex]));
  });
}

function makeLiuyaoManualCoins() {
  return Array.from({ length: 6 }, () => LIUYAO_MANUAL_EMPTY_COINS.slice());
}

function normalizeLiuyaoQuestion(value) {
  return String(value || "").replace(/\s+/g, " ").trim().slice(0, LIUYAO_QUESTION_MAX_LENGTH);
}

function normalizeLiuyaoQuota(raw) {
  if (raw?.testingUnlimited) {
    const limit = Math.max(1, Number(raw?.limit || raw?.dailyLimit || 999));
    const used = Math.max(0, Number(raw?.used ?? raw?.dailyUsed ?? 0));
    return {
      ...raw,
      limit,
      used,
      remaining: limit,
      dailyLimit: limit,
      dailyUsed: used,
      dailyRemaining: limit,
      exhausted: false,
      testingUnlimited: true,
      checkedAt: Number(raw?.checkedAt) || Date.now(),
    };
  }
  const limit = Math.max(1, Number(raw?.limit || raw?.dailyLimit || LIUYAO_DAILY_LIMIT));
  const used = Math.max(0, Number(raw?.used ?? raw?.dailyUsed ?? 0));
  const remaining = Math.max(0, Number(raw?.remaining ?? raw?.dailyRemaining ?? (limit - used)));
  return {
    limit,
    used,
    remaining,
    date: String(raw?.date || ""),
    exhausted: remaining <= 0,
    checkedAt: Number(raw?.checkedAt) || Date.now(),
  };
}

function mergeLiuyaoQuota(currentRaw, nextRaw) {
  const next = normalizeLiuyaoQuota(nextRaw);
  if (next.testingUnlimited) return next;
  if (!currentRaw) return next;
  const current = normalizeLiuyaoQuota(currentRaw);
  const sameKnownDate = current.date && next.date && current.date === next.date;
  const sameUnknownDate = !current.date && !next.date;
  if ((sameKnownDate || sameUnknownDate) && next.used < current.used) return current;
  return next;
}

function normalizeLiuyaoQuestionGate(raw, question) {
  if (!raw || typeof raw !== "object") return null;
  const gateQuestion = normalizeLiuyaoQuestion(raw.question || raw.normalizedQuestion || "");
  if (gateQuestion && gateQuestion !== question) return null;
  return {
    question,
    allowed: raw.allowed === true,
    reason: normalizeLiuyaoQuestion(raw.reason || ""),
    suggestion: normalizeLiuyaoQuestion(raw.suggestion || ""),
    labels: Array.isArray(raw.labels) ? raw.labels.map(normalizeLiuyaoQuestion).filter(Boolean).slice(0, 4) : [],
    quota: raw.quota ? normalizeLiuyaoQuota(raw.quota) : null,
    checkedAt: Number(raw.checkedAt) || Date.now(),
    retryable: raw.retryable === true,
  };
}

function makeLiuyaoDefaultState() {
  return {
    recordId: makeWentianUuid(),
    mode: "online",
    question: LIUYAO_DEFAULT_QUESTION,
    createdAt: Date.now(),
    casts: [],
    manualCoins: makeLiuyaoManualCoins(),
    questionGate: null,
    quota: null,
  };
}

function getLiuyaoState() {
  if (liuyaoState) return liuyaoState;
  try {
    const parsed = JSON.parse(localStorage.getItem(LIUYAO_STORAGE_KEY) || "null");
    if (parsed && typeof parsed === "object") {
      const casts = Array.isArray(parsed.casts) ? parsed.casts.slice(0, 6).map(normalizeLiuyaoCast) : [];
      const storedQuestion = normalizeLiuyaoQuestion(parsed.question || LIUYAO_DEFAULT_QUESTION);
      const question = storedQuestion === LIUYAO_SAMPLE_QUESTION && !casts.filter(Boolean).length ? "" : storedQuestion;
      liuyaoState = {
        recordId: isWentianUuid(parsed.recordId) ? parsed.recordId : makeWentianUuid(),
        mode: parsed.mode === "manual" ? "manual" : "online",
        question,
        createdAt: Number(parsed.createdAt) || Date.now(),
        casts,
        manualCoins: normalizeLiuyaoManualCoins(parsed.manualCoins, casts),
        questionGate: normalizeLiuyaoQuestionGate(parsed.questionGate, question),
        quota: parsed.quota ? normalizeLiuyaoQuota(parsed.quota) : null,
      };
      return liuyaoState;
    }
  } catch (_err) {}
  liuyaoState = makeLiuyaoDefaultState();
  return liuyaoState;
}

function formatLiuyaoMovingLineText(movingLines, prefix = "") {
  const lines = Array.isArray(movingLines) ? movingLines : [];
  const labels = lines.map((line) => line?.label).filter(Boolean);
  const text = labels.length ? labels.join("、") : "无";
  return `${prefix}${text}`;
}

function saveLiuyaoState() {
  try {
    localStorage.setItem(LIUYAO_STORAGE_KEY, JSON.stringify(getLiuyaoState()));
  } catch (_err) {}
}

function saveLiuyaoQuestionFromDom() {
  const input = document.getElementById("liuyao-question");
  if (!input) return;
  const state = getLiuyaoState();
  const nextQuestion = normalizeLiuyaoQuestion(input.value);
  const count = document.querySelector(".liuyao-big-question span");
  if (count) count.textContent = formatLiuyaoQuestionCount(nextQuestion);
  if (state.question !== nextQuestion) {
    const hadCasts = getLiuyaoValidCasts(state).length > 0;
    state.question = nextQuestion;
    state.questionGate = null;
    if (hadCasts) {
      clearLiuyaoTossAnimation();
      state.recordId = makeWentianUuid();
      state.createdAt = Date.now();
      state.casts = [];
    }
    const status = document.getElementById("liuyao-question-status");
    if (status) {
      status.textContent = translateWentianText("改好后点提交占问，重新审题。");
      status.dataset.tone = "hint";
    }
  }
  saveLiuyaoState();
  updateLiuyaoQuestionSubmitDom();
}

function clearLiuyaoTossAnimation() {
  if (liuyaoTossTimer) {
    clearTimeout(liuyaoTossTimer);
    liuyaoTossTimer = null;
  }
  liuyaoTossAnimation = null;
  liuyaoSwipeStart = null;
}

function navigatePreservingScroll(route, push = false) {
  const scrollX = window.scrollX || document.documentElement.scrollLeft || 0;
  const scrollY = window.scrollY || document.documentElement.scrollTop || 0;
  navigate(route, push);
  window.scrollTo(scrollX, scrollY);
  window.setTimeout(() => window.scrollTo(scrollX, scrollY), 0);
  window.setTimeout(() => window.scrollTo(scrollX, scrollY), 80);
  window.setTimeout(() => window.scrollTo(scrollX, scrollY), 220);
}

function navigateWentianProfilePreservingListScroll() {
  const list = document.getElementById("wentian-profile-list");
  const scrollTop = list?.scrollTop || 0;
  const selectedId = wentianArchiveDraftId || getWentianSelectedArchiveId(getWentianArchiveList());
  navigatePreservingScroll("screen-25", false);
  const restore = () => {
    const nextList = document.getElementById("wentian-profile-list");
    if (nextList) {
      const maxScrollTop = Math.max(0, nextList.scrollHeight - nextList.clientHeight);
      nextList.scrollTop = Math.min(scrollTop, maxScrollTop);
    }
    if (selectedId) updateWentianProfileSelectionDom(selectedId);
  };
  window.requestAnimationFrame(restore);
  window.setTimeout(restore, 80);
  window.setTimeout(restore, 220);
}

function navigateLiuyaoCastPreservingScroll() {
  navigatePreservingScroll("screen-17", false);
}

function setLiuyaoMode(mode) {
  clearLiuyaoTossAnimation();
  setLiuyaoCasterModalOpen(false);
  saveLiuyaoQuestionFromDom();
  const state = getLiuyaoState();
  state.mode = mode === "manual" ? "manual" : "online";
  if (state.mode === "online") state.casts = state.casts.filter(Boolean);
  saveLiuyaoState();
  navigate("screen-17", false);
}

function resetLiuyaoState() {
  clearLiuyaoTossAnimation();
  liuyaoResetConfirmOpen = false;
  setLiuyaoCasterModalOpen(false);
  const quota = getLiuyaoState().quota || null;
  liuyaoState = makeLiuyaoDefaultState();
  liuyaoState.quota = quota;
  saveLiuyaoState();
  navigate("screen-17", false);
}

function requestLiuyaoReset() {
  liuyaoResetConfirmOpen = true;
  navigate("screen-17", false);
}

function cancelLiuyaoReset() {
  liuyaoResetConfirmOpen = false;
  navigate("screen-17", false);
}

function confirmLiuyaoReset() {
  resetLiuyaoState();
}

function getSecureRandomByte() {
  if (window.crypto?.getRandomValues) {
    const bytes = new Uint8Array(1);
    window.crypto.getRandomValues(bytes);
    return bytes[0];
  }
  return Math.floor(Math.random() * 256);
}

function clampLiuyaoPower(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return LIUYAO_DEFAULT_POWER;
  return Math.max(0.18, Math.min(1, number));
}

function makeLiuyaoCoinCast(gesture = {}) {
  const power = clampLiuyaoPower(gesture.power);
  const pull = Math.max(0, Math.min(LIUYAO_PULL_MAX, Math.round(Number(gesture.pull) || power * LIUYAO_PULL_MAX)));
  const duration = Math.max(0, Math.min(6000, Math.round(Number(gesture.duration) || 0)));
  const deltaX = Math.round(Number(gesture.deltaX) || 0);
  const seed = Math.round(power * 1000) + pull * 7 + duration * 3 + deltaX * 11;
  const coins = [0, 1, 2].map((_, index) => {
    const wobble = ((duration + pull + index * 37) % 9) - 4;
    const threshold = Math.max(38, Math.min(62, 50 + Math.round((power - 0.5) * 18) + wobble));
    return ((getSecureRandomByte() + seed + index * 73) % 100) < threshold ? 3 : 2;
  });
  return {
    value: coins.reduce((sum, coin) => sum + coin, 0),
    coins,
    manual: false,
    at: Date.now(),
    power: Math.round(power * 100),
    pull,
    duration,
  };
}

function getLiuyaoManualCoins(state = getLiuyaoState(), lineIndex = 0) {
  if (!Array.isArray(state.manualCoins) || state.manualCoins.length < 6) {
    state.manualCoins = normalizeLiuyaoManualCoins(state.manualCoins, state.casts);
  }
  if (!Array.isArray(state.manualCoins[lineIndex])) {
    state.manualCoins[lineIndex] = LIUYAO_MANUAL_EMPTY_COINS.slice();
  }
  return state.manualCoins[lineIndex];
}

function makeLiuyaoManualCastFromCoins(coins) {
  const faces = [0, 1, 2].map((index) => normalizeLiuyaoCoinFace(coins?.[index]));
  if (faces.some((face) => !face)) return null;
  return normalizeLiuyaoCast({
    value: faces.reduce((sum, face) => sum + face, 0),
    coins: faces,
    manual: true,
    at: Date.now(),
  });
}

function setLiuyaoQuestionGateResult(result) {
  const state = getLiuyaoState();
  const question = normalizeLiuyaoQuestion(state.question);
  if (result?.quota) state.quota = mergeLiuyaoQuota(state.quota, result.quota);
  state.questionGate = {
    question,
    allowed: result?.allowed === true,
    reason: normalizeLiuyaoQuestion(result?.reason || ""),
    suggestion: normalizeLiuyaoQuestion(result?.suggestion || ""),
    labels: Array.isArray(result?.labels) ? result.labels.map(normalizeLiuyaoQuestion).filter(Boolean).slice(0, 4) : [],
    quota: state.quota,
    checkedAt: Date.now(),
    retryable: result?.retryable === true,
  };
  saveLiuyaoState();
  return state.questionGate;
}

function getLiuyaoQuota(state = getLiuyaoState()) {
  return normalizeLiuyaoQuota(state.quota || state.questionGate?.quota || {
    limit: LIUYAO_DAILY_LIMIT,
    used: 0,
    remaining: LIUYAO_DAILY_LIMIT,
  });
}

function isLiuyaoQuotaExhausted(state = getLiuyaoState()) {
  const question = normalizeLiuyaoQuestion(state.question);
  const gate = normalizeLiuyaoQuestionGate(state.questionGate, question);
  return !gate?.allowed && getLiuyaoQuota(state).remaining <= 0;
}

function renderLiuyaoQuotaBadge(state = getLiuyaoState()) {
  const quota = getLiuyaoQuota(state);
  const text = liuyaoQuotaLoading ? "今日次数确认中" : (quota.testingUnlimited ? "测试期不限次数" : `今日已占 ${quota.used}/${quota.limit}`);
  return `<span class="liuyao-quota-badge ${quota.remaining <= 0 ? "is-empty" : ""}">${escapeHtml(text)}</span>`;
}

function getLiuyaoQuestionGateMessage(state = getLiuyaoState()) {
  if (liuyaoQuestionGateLoading) {
    return { tone: "loading", text: "正在审题，合格才起卦。" };
  }
  const question = normalizeLiuyaoQuestion(state.question);
  const gate = normalizeLiuyaoQuestionGate(state.questionGate, question);
  if (!gate?.allowed && getLiuyaoQuota(state).remaining <= 0) {
    return { tone: "error", text: "今日六爻占卜已满 3 次，明天再起卦。" };
  }
  if (!question) {
    return { tone: "hint", text: "先写清一件事；空问、乱点、随便试，不起卦。" };
  }
  if (!gate) {
    return { tone: "hint", text: "起卦前会先按“一事一占”审题。" };
  }
  if (gate.allowed) {
    return { tone: "ok", text: gate.reason || "审题通过，可以起卦。" };
  }
  return {
    tone: "error",
    text: [gate.reason || "问题还不够清楚，暂不起卦。", gate.suggestion || ""].filter(Boolean).join("\n"),
  };
}

function renderLiuyaoQuestionGateStatus(state = getLiuyaoState()) {
  const status = getLiuyaoQuestionGateMessage(state);
  return `<p id="liuyao-question-status" class="liuyao-question-status" data-tone="${escapeHtml(status.tone)}">${escapeHtml(status.text)}</p>`;
}

function getLiuyaoQuestionSubmitMeta(state = getLiuyaoState()) {
  const question = normalizeLiuyaoQuestion(state.question);
  const gate = normalizeLiuyaoQuestionGate(state.questionGate, question);
  if (liuyaoQuestionGateLoading) {
    return { label: "审题中…", disabled: true, state: "loading" };
  }
  if (!gate?.allowed && getLiuyaoQuota(state).remaining <= 0) {
    return { label: "今日已满", disabled: true, state: "rejected" };
  }
  if (gate?.allowed) {
    return { label: "已通过", disabled: true, state: "approved" };
  }
  if (gate && !gate.allowed) {
    return {
      label: gate.retryable ? "重新提交" : "修改后提交",
      disabled: !gate.retryable,
      state: "rejected",
    };
  }
  return { label: "提交占问", disabled: !question, state: "idle" };
}

function renderLiuyaoQuestionSubmit(state = getLiuyaoState()) {
  const meta = getLiuyaoQuestionSubmitMeta(state);
  return `
    <button
      type="button"
      class="liuyao-question-submit ${meta.state ? `is-${meta.state}` : ""}"
      data-action="liuyao-submit-question"
      ${meta.disabled ? "disabled" : ""}
    >${escapeHtml(meta.label)}</button>
  `;
}

function getLiuyaoQuestionSuggestions(state = getLiuyaoState()) {
  const question = normalizeLiuyaoQuestion(state.question);
  const gate = normalizeLiuyaoQuestionGate(state.questionGate, question);
  if (gate?.allowed || liuyaoQuestionGateLoading) return [];
  if (/网站|项目|计划|产品|上线|发布/.test(question)) {
    return [
      "这个项目本月能不能继续推进并见到效果？",
      "这个网站近期能不能带来真实客户？",
      "现在要不要先收缩计划、只做一个核心功能？"
    ];
  }
  if (/合作|客户|合同|订单/.test(question)) {
    return [
      "这笔合作近期能不能谈成？",
      "这个客户本周会不会继续推进？",
      "这份合同现在适不适合签？"
    ];
  }
  if (/感情|婚姻|复合|对象|伴侣/.test(question)) {
    return [
      "这段关系接下来适不适合主动沟通？",
      "对方近期会不会回应我？",
      "这段感情还值不值得继续推进？"
    ];
  }
  return LIUYAO_QUESTION_SUGGESTIONS;
}

function renderLiuyaoQuestionSuggestions(state = getLiuyaoState()) {
  const suggestions = getLiuyaoQuestionSuggestions(state).slice(0, 4);
  if (!suggestions.length) return "";
  return `
    <div class="liuyao-question-suggestions">
      <span>可选示例</span>
      <div>
        ${suggestions.map((item) => `
          <button type="button" data-action="liuyao-question-suggestion" data-question="${escapeHtml(encodeURIComponent(item))}">${escapeHtml(item)}</button>
        `).join("")}
      </div>
    </div>
  `;
}

function applyLiuyaoQuestionSuggestion(value) {
  const text = normalizeLiuyaoQuestion(value);
  if (!text) return;
  clearLiuyaoTossAnimation();
  const state = getLiuyaoState();
  const hadCasts = getLiuyaoValidCasts(state).length > 0;
  state.question = text;
  state.questionGate = null;
  if (hadCasts) {
    state.recordId = makeWentianUuid();
    state.createdAt = Date.now();
    state.casts = [];
    state.manualCoins = makeLiuyaoManualCoins();
  }
  saveLiuyaoState();
  navigate("screen-17", false);
  window.setTimeout(() => document.getElementById("liuyao-question")?.focus?.(), 0);
}

function updateLiuyaoQuestionSubmitDom(state = getLiuyaoState()) {
  const button = document.querySelector('[data-action="liuyao-submit-question"]');
  const meta = getLiuyaoQuestionSubmitMeta(state);
  if (button) {
    button.textContent = translateWentianText(
      button.classList.contains("liuyao-start-button") && meta.state === "idle" ? "开始起卦" : meta.label
    );
    button.disabled = meta.disabled;
    ["idle", "loading", "approved", "rejected"].forEach((name) => {
      button.classList.toggle(`is-${name}`, meta.state === name);
    });
  }
  updateLiuyaoQuestionLockedDom(state);
}

function updateLiuyaoQuestionLockedDom(state = getLiuyaoState()) {
  const question = normalizeLiuyaoQuestion(state.question);
  const ready = Boolean(normalizeLiuyaoQuestionGate(state.questionGate, question)?.allowed);
  const progress = getLiuyaoProgress(state);
  const complete = progress >= 6;
  const lockText = liuyaoQuestionGateLoading ? "审题中，稍候开放" : "提交通过后开放投币";
  const panel = document.querySelector(".liuyao-coin-panel");
  const quotaBadge = document.querySelector(".liuyao-quota-badge");
  if (quotaBadge) quotaBadge.outerHTML = renderLiuyaoQuotaBadge(state);
  if (panel) {
    panel.classList.toggle("is-ready", ready);
    panel.classList.toggle("is-waiting", !ready);
  }
  const stage = document.querySelector('[data-action="liuyao-swipe-cast"]');
  if (stage) {
    const disabled = !ready || liuyaoQuestionGateLoading || complete || state.mode !== "online";
    stage.classList.toggle("is-disabled", disabled);
    stage.setAttribute("aria-disabled", disabled ? "true" : "false");
    stage.setAttribute("tabindex", disabled ? "-1" : "0");
    stage.setAttribute("aria-label", translateWentianText(disabled ? lockText : `按住铜钱上拉，松手投第 ${progress + 1} 爻`));
    const cue = stage.querySelector(".liuyao-swipe-cue");
    if (cue) cue.textContent = translateWentianText(disabled ? lockText : `按住铜钱上拉，松手投第 ${progress + 1} 爻`);
    const force = stage.querySelector(".liuyao-force-label");
    if (force && !ready) force.textContent = translateWentianText("待审题");
  }
  const onlineAction = document.querySelector('[data-action="liuyao-open-caster"]');
  if (onlineAction) {
    onlineAction.disabled = !ready || liuyaoQuestionGateLoading || Boolean(liuyaoTossAnimation?.active);
    onlineAction.textContent = translateWentianText(
      liuyaoQuestionGateLoading ? "审题中…" : (!ready ? "提交通过后开放投币" : `全屏投第 ${progress + 1} 爻`)
    );
  }
  if (!ready) {
    document.querySelectorAll('.liuyao-line-row[data-action="liuyao-manual-line"]').forEach((item) => {
      item.removeAttribute("data-action");
    });
  }
}

function formatLiuyaoQuestionCount(question = "") {
  const count = Array.from(String(question || "")).length;
  return getWentianLanguageCode() === "en" ? `${count} chars` : `${count} 字`;
}

function parseLiuyaoGateJson(text) {
  const raw = String(text || "").trim();
  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const source = fenced ? fenced[1] : raw;
  const start = source.indexOf("{");
  const end = source.lastIndexOf("}");
  if (start < 0 || end <= start) return null;
  try {
    return JSON.parse(source.slice(start, end + 1));
  } catch (_err) {
    return null;
  }
}

function reviewLiuyaoQuestionLocally(question) {
  const normalizedQuestion = normalizeLiuyaoQuestion(question);
  const compact = normalizedQuestion.replace(/[\s，。！？、,.!?；;：“”"'（）()【】\[\]]+/g, "");
  const fail = (reason, suggestion, labels = ["一事一占"]) => ({
    allowed: false,
    normalizedQuestion,
    reason,
    suggestion,
    labels,
  });

  if (!normalizedQuestion) {
    return fail("请先写清楚要问的一件事。", "一句话只问一件具体事情，再起卦。");
  }
  if (/^(随便|随机|娱乐|玩玩|试试|测试|乱点|看看|不知道|无所谓|都行|随便玩玩|随便看看|随机看看|测一下|测测|试一下|试试看|占着玩|测着玩)$/.test(compact)) {
    return fail("这个问题太随意，暂不起卦。", "请写清楚具体对象和想看的结果。", ["问题太散"]);
  }
  if (/^(事业|财运|感情|婚姻|健康|工作|学业|运势|赚钱|求财|桃花|考试|合作|项目|网站)(怎么样|如何|好吗|看看|测测|测一下)?$/.test(compact)) {
    return fail("问题还太泛，暂不起卦。", "请具体到一件事，例如“这个项目本月能不能推进”。", ["问题太泛"]);
  }
  const looksLikeCasualChat = /(宝宝|宝贝|亲爱的|老公|老婆|在吗|忙吗|吃了吗|睡了吗|下课了吗|上课了吗|到家了吗|回来了吗|想我吗|爱我吗|有没有空|你是不是|是不是你|是不是在|哈哈|呵呵|嘻嘻|早安|晚安)/i.test(normalizedQuestion);
  const hasDivinationMatter = /(项目|合作|客户|合同|订单|面试|考试|offer|录取|工作|离职|跳槽|创业|开店|上线|发布|推进|签约|回款|到账|投资|财运|感情|婚姻|复合|分手|怀孕|健康|手术|治疗|搬家|买房|卖房|租房|官司|家宅|父母|孩子|伴侣|对象|关系)/i.test(normalizedQuestion);
  if (looksLikeCasualChat && !hasDivinationMatter) {
    return fail("这句话更像日常聊天，不属于正式占问。", "请改成一件需要判断结果的事情，例如：这段关系这个月还能不能推进？", ["非占问"]);
  }
  if ((normalizedQuestion.match(/[？?]/g) || []).length > 1 || /同时|另外|还有|顺便|以及/.test(normalizedQuestion)) {
    return fail("一次只问一件事。", "请先删到一个核心问题，再提交。", ["一事一占"]);
  }

  const hasSpecificSubject = /(我|我们|本人|自己|这个|这件|该|现在|本月|今年|最近|网站|项目|公司|店|生意|工作|客户|合作|合同|订单|产品|账号|平台|考试|offer|面试|房子|投资|资金|对方|他|她|TA|孩子|家人|父母|伴侣|对象|老板|同事|合伙人)/i.test(normalizedQuestion);
  const hasOutcome = /(能不能|能否|是否|可否|会不会|要不要|该不该|适不适合|可以吗|成不成|有没有|何时|多久|结果|赚钱|盈利|回本|成交|签约|通过|录取|复合|结婚|分手|离职|跳槽|搬家|买|卖|租|开店|上线|发布|推进|合作|投资|到账|怀孕|好转)/i.test(normalizedQuestion);
  const hasQuestionCue = /[？?]|吗|呢|如何|怎样|怎么样|能|该|是否|可否|会不会|要不要/.test(normalizedQuestion);

  const isEnglishQuestion = /^[\x00-\x7F]+$/.test(normalizedQuestion) && /[A-Za-z]/.test(normalizedQuestion);
  if (isEnglishQuestion) {
    const lowerQuestion = normalizedQuestion.toLowerCase();
    const hasEnglishSubject = /\b(i|we|my|our|client|customer|project|contract|order|partner|company|job|offer|interview|relationship|house|investment|money|payment|account|product|website|business)\b/.test(lowerQuestion);
    const hasEnglishEvent = /\b(approve|sign|close|continue|move|launch|publish|pay|receive|pass|get|win|work|succeed|proceed|finish|deliver|cooperate|invest|buy|sell|rent|hire|leave|change)\b/.test(lowerQuestion);
    const hasEnglishCue = /[?]|\b(will|can|should|whether|when|how|is|are|do|does|would|could)\b/.test(lowerQuestion);
    const hasEnglishTimeOrScope = /\b(today|tomorrow|this|next|month|week|year|before|after|by|within|soon|january|february|march|april|may|june|july|august|september|october|november|december|20\d{2})\b/.test(lowerQuestion);
    if (compact.length >= 18 && hasEnglishSubject && hasEnglishEvent && hasEnglishCue && hasEnglishTimeOrScope) {
      return {
        allowed: true,
        normalizedQuestion,
        reason: "The question names the subject, event, outcome, and timing.",
        suggestion: "",
        labels: ["One question"],
      };
    }
    return fail("The question is not specific enough.", "State one subject, one event, the result you want to know, and a clear time frame.", ["One question"]);
  }

  if (compact.length < 8 || !hasSpecificSubject || !hasOutcome || !hasQuestionCue) {
    return fail("问题还不够具体，暂不起卦。", "请写清对象、事件和想看的结果。", ["问题不具体"]);
  }
  return {
    allowed: true,
    normalizedQuestion,
    reason: "问题具体到对象、事件和结果，符合一事一占原则。",
    suggestion: "",
    labels: ["一事一占"],
  };
}

async function reviewLiuyaoQuestionViaChat(question) {
  const localGate = reviewLiuyaoQuestionLocally(question);
  if (String(window.SITE_CONFIG?.liuyaoQuestionGateMode || "remote").toLowerCase() === "local") {
    return localGate;
  }
  if (!localGate.allowed) return localGate;
  try {
    const data = await wentianPostJson("/api/ai/liuyao-question", {
      question,
      clientId: getWentianClientId(),
      chatMode: "liuyao_question_gate",
      divinationContext: { type: "liuyao_question_gate", question, clientId: getWentianClientId(), recordId: getLiuyaoState().recordId },
    }, 6000, 0);
    if (typeof data?.allowed === "boolean") return data;
    const parsed = parseLiuyaoGateJson(data?.reply);
    if (!parsed) throw new Error("chat gate parse failed");
    return parsed;
  } catch (_err) {
    const quota = normalizeLiuyaoQuota(getLiuyaoState().quota);
    if (quota.remaining > 0) {
      return {
        ...localGate,
        allowed: true,
        normalizedQuestion: localGate.normalizedQuestion || question,
        reason: "本地审题通过，可以起卦。后台次数稍后同步。",
        suggestion: "后台恢复后会继续同步今日次数。",
        labels: [...new Set([...(localGate.labels || ["一事一占"]), "本地通过"])].slice(0, 4),
        quota,
      };
    }
    return {
      allowed: false,
      normalizedQuestion: question,
      reason: "今日六爻占卜已满 3 次，明天再起卦。",
      suggestion: "",
      labels: ["今日已满"],
      quota,
    };
  }
}

async function refreshLiuyaoQuota() {
  if (liuyaoQuotaLoading) return;
  const liuyao = getLiuyaoState();
  const quota = liuyao.quota ? normalizeLiuyaoQuota(liuyao.quota) : null;
  if (quota?.checkedAt && Date.now() - quota.checkedAt < 120000) return;
  liuyaoQuotaLoading = true;
  try {
    const data = await wentianPostJson("/api/ai/liuyao-question", {
      action: "quota",
      clientId: getWentianClientId(),
      divinationContext: { type: "liuyao_quota", clientId: getWentianClientId() },
    }, 6000, 0);
    if (data?.quota) {
      liuyao.quota = mergeLiuyaoQuota(liuyao.quota, data.quota);
      saveLiuyaoState();
      if (state.route === "screen-17") navigate("screen-17", false);
    }
  } catch (_err) {
    // The submit path still checks the server before allowing a new divination.
  } finally {
    liuyaoQuotaLoading = false;
    if (state.route === "screen-17") navigate("screen-17", false);
  }
}

function queueLiuyaoQuotaRefresh() {
  window.setTimeout(refreshLiuyaoQuota, 0);
}

async function ensureLiuyaoQuestionAllowed() {
  if (liuyaoQuestionGateLoading) return false;
  saveLiuyaoQuestionFromDom();
  const state = getLiuyaoState();
  const question = normalizeLiuyaoQuestion(state.question);
  if (!question) {
    setLiuyaoQuestionGateResult({
      allowed: false,
      reason: "请先写清楚要问的一件事。",
      suggestion: "一句话只问一件具体事情，再起卦。",
      labels: ["一事一占"],
    });
    navigate("screen-17", false);
    return false;
  }
  if (isLiuyaoQuotaExhausted(state)) {
    setLiuyaoQuestionGateResult({
      allowed: false,
      reason: "今日六爻占卜已满 3 次，明天再起卦。",
      suggestion: "手机端和电脑端共用每日 3 次额度。",
      labels: ["今日已满"],
      quota: state.quota,
    });
    navigate("screen-17", false);
    return false;
  }
  const cached = normalizeLiuyaoQuestionGate(state.questionGate, question);
  if (cached?.allowed) return true;
  if (cached && !cached.retryable) {
    navigate("screen-17", false);
    return false;
  }
  liuyaoQuestionGateLoading = true;
  navigate("screen-17", false);
  try {
    const data = await reviewLiuyaoQuestionViaChat(question);
    const gate = setLiuyaoQuestionGateResult({
      allowed: data?.allowed === true,
      reason: data?.reason || (data?.allowed ? "审题通过，可以起卦。" : "问题还不够清楚，暂不起卦。"),
      suggestion: data?.suggestion || "",
      labels: data?.labels || [],
      quota: data?.quota,
      retryable: data?.retryable === true,
    });
    return gate.allowed;
  } catch (_err) {
    const gate = setLiuyaoQuestionGateResult(reviewLiuyaoQuestionLocally(question));
    return gate.allowed;
  } finally {
    liuyaoQuestionGateLoading = false;
    navigate("screen-17", false);
  }
}

function prepareLiuyaoOnlineTossState() {
  saveLiuyaoQuestionFromDom();
  const state = getLiuyaoState();
  state.mode = "online";
  state.casts = state.casts.filter(Boolean);
  if (state.casts.length >= 6) {
    state.recordId = makeWentianUuid();
    state.createdAt = Date.now();
    state.casts = [];
  }
  return state;
}

function focusLiuyaoCasterModal(options = {}) {
  window.setTimeout(() => {
    const modal = document.querySelector(".liuyao-caster-modal");
    const caster = modal?.querySelector('[data-action="liuyao-swipe-cast"]');
    if (options.scroll !== false) modal?.scrollIntoView?.({ block: "start", behavior: "smooth" });
    caster?.focus?.({ preventScroll: true });
    if (modal) window.setTimeout(() => lockLiuyaoCasterScroll(liuyaoCastModalOpen), 180);
  }, 0);
}

function openLiuyaoCasterModal() {
  const state = getLiuyaoState();
  if (state.mode !== "online" || getLiuyaoProgress(state) >= 6) return;
  setLiuyaoCasterModalOpen(true);
  navigate("screen-17", false);
  focusLiuyaoCasterModal();
}

function closeLiuyaoCasterModal() {
  setLiuyaoCasterModalOpen(false);
  navigate("screen-17", false);
}

function refreshLiuyaoCasterModalDom(options = {}) {
  const modal = document.querySelector(".liuyao-caster-modal");
  if (!modal || state.route !== "screen-17") return false;
  const current = getLiuyaoState();
  const html = renderLiuyaoCasterModal(current, { complete: getLiuyaoProgress(current) >= 6 });
  if (!html) {
    modal.remove();
    return true;
  }
  const template = document.createElement("template");
  template.innerHTML = html.trim();
  const next = template.content.firstElementChild;
  if (!next) return false;
  modal.replaceWith(next);
  lockLiuyaoCasterScroll(liuyaoCastModalOpen);
  if (options.focus) {
    next.querySelector('[data-action="liuyao-swipe-cast"]')?.focus?.({ preventScroll: true });
  }
  return true;
}

function finishLiuyaoAnimatedToss() {
  const pending = liuyaoTossAnimation?.cast;
  liuyaoTossTimer = null;
  liuyaoTossAnimation = null;
  if (!pending) return;
  const state = getLiuyaoState();
  state.mode = "online";
  state.casts = state.casts.filter(Boolean);
  if (state.casts.length < 6) state.casts.push(pending);
  saveLiuyaoState();
  const complete = state.casts.length >= 6;
  setLiuyaoCasterModalOpen(!complete);
  if (complete) {
    navigate("screen-20");
    return;
  }
  if (!refreshLiuyaoCasterModalDom({ focus: true })) {
    navigate("screen-17", false);
    focusLiuyaoCasterModal();
  }
}

function beginLiuyaoAnimatedToss(gesture = {}) {
  if (liuyaoTossAnimation?.active) return false;
  const state = prepareLiuyaoOnlineTossState();
  if (state.casts.length >= 6) return false;
  const cast = makeLiuyaoCoinCast(gesture);
  setLiuyaoCasterModalOpen(true);
  liuyaoTossAnimation = {
    active: true,
    cast,
    lineIndex: state.casts.length,
    power: cast.power,
    pull: cast.pull,
    startedAt: Date.now(),
  };
  saveLiuyaoState();
  if (!refreshLiuyaoCasterModalDom({ focus: true })) {
    navigate("screen-17", false);
    focusLiuyaoCasterModal();
  } else {
    focusLiuyaoCasterModal({ scroll: false });
  }
  liuyaoTossTimer = setTimeout(finishLiuyaoAnimatedToss, LIUYAO_TOSS_ANIMATION_MS);
  return true;
}

async function startLiuyaoAnimatedToss(gesture = {}) {
  if (!(await ensureLiuyaoQuestionAllowed())) return false;
  return beginLiuyaoAnimatedToss(gesture);
}

async function tossLiuyaoLine(all = false) {
  if (!(await ensureLiuyaoQuestionAllowed())) return false;
  clearLiuyaoTossAnimation();
  setLiuyaoCasterModalOpen(false);
  const state = prepareLiuyaoOnlineTossState();
  do {
    state.casts.push(makeLiuyaoCoinCast({ power: LIUYAO_DEFAULT_POWER, pull: LIUYAO_PULL_MAX * LIUYAO_DEFAULT_POWER }));
  } while (all && state.casts.length < 6);
  saveLiuyaoState();
  if (state.casts.length >= 6) navigate("screen-20");
  else navigate("screen-17", false);
  return true;
}

async function cycleLiuyaoManualLine(index) {
  if (!(await ensureLiuyaoQuestionAllowed())) return false;
  clearLiuyaoTossAnimation();
  saveLiuyaoQuestionFromDom();
  const state = getLiuyaoState();
  state.mode = "manual";
  while (state.casts.length < 6) state.casts.push(null);
  const current = normalizeLiuyaoCast(state.casts[index]);
  const nextValue = current ? LIUYAO_VALUES[(LIUYAO_VALUES.indexOf(current.value) + 1) % LIUYAO_VALUES.length] : 7;
  state.casts[index] = normalizeLiuyaoCast({ value: nextValue, manual: true, at: Date.now() });
  state.manualCoins = normalizeLiuyaoManualCoins(state.manualCoins, state.casts);
  saveLiuyaoState();
  navigateLiuyaoCastPreservingScroll();
  return true;
}

async function setLiuyaoManualCoin(lineIndex, coinIndex, face) {
  if (!(await ensureLiuyaoQuestionAllowed())) return false;
  const line = Math.max(0, Math.min(5, Math.round(Number(lineIndex) || 0)));
  const coin = Math.max(0, Math.min(2, Math.round(Number(coinIndex) || 0)));
  const coinFace = normalizeLiuyaoCoinFace(face);
  if (!coinFace) return false;
  clearLiuyaoTossAnimation();
  setLiuyaoCasterModalOpen(false);
  saveLiuyaoQuestionFromDom();
  const state = getLiuyaoState();
  state.mode = "manual";
  while (state.casts.length < 6) state.casts.push(null);
  state.manualCoins = normalizeLiuyaoManualCoins(state.manualCoins, state.casts);
  const row = getLiuyaoManualCoins(state, line).slice();
  row[coin] = coinFace;
  state.manualCoins[line] = row;
  state.casts[line] = null;
  saveLiuyaoState();
  navigateLiuyaoCastPreservingScroll();
  return true;
}

async function confirmLiuyaoManualLine(lineIndex) {
  if (!(await ensureLiuyaoQuestionAllowed())) return false;
  const line = Math.max(0, Math.min(5, Math.round(Number(lineIndex) || 0)));
  clearLiuyaoTossAnimation();
  setLiuyaoCasterModalOpen(false);
  saveLiuyaoQuestionFromDom();
  const state = getLiuyaoState();
  state.mode = "manual";
  while (state.casts.length < 6) state.casts.push(null);
  state.manualCoins = normalizeLiuyaoManualCoins(state.manualCoins, state.casts);
  const cast = makeLiuyaoManualCastFromCoins(getLiuyaoManualCoins(state, line));
  if (!cast) return false;
  state.casts[line] = cast;
  state.manualCoins[line] = cast.coins.slice();
  saveLiuyaoState();
  navigateLiuyaoCastPreservingScroll();
  return true;
}

function clearLiuyaoManualLine(lineIndex) {
  const line = Math.max(0, Math.min(5, Math.round(Number(lineIndex) || 0)));
  clearLiuyaoTossAnimation();
  const state = getLiuyaoState();
  state.mode = "manual";
  while (state.casts.length < 6) state.casts.push(null);
  state.manualCoins = normalizeLiuyaoManualCoins(state.manualCoins, state.casts);
  state.manualCoins[line] = LIUYAO_MANUAL_EMPTY_COINS.slice();
  state.casts[line] = null;
  saveLiuyaoState();
  navigateLiuyaoCastPreservingScroll();
}

function clearLastLiuyaoManualLine() {
  clearLiuyaoTossAnimation();
  const state = getLiuyaoState();
  state.mode = "manual";
  while (state.casts.length < 6) state.casts.push(null);
  state.manualCoins = normalizeLiuyaoManualCoins(state.manualCoins, state.casts);
  for (let line = 5; line >= 0; line -= 1) {
    if (normalizeLiuyaoCast(state.casts[line])) {
      state.manualCoins[line] = LIUYAO_MANUAL_EMPTY_COINS.slice();
      state.casts[line] = null;
      saveLiuyaoState();
      navigateLiuyaoCastPreservingScroll();
      return;
    }
  }
}

async function showLiuyaoResultIfAllowed() {
  if (!(await ensureLiuyaoQuestionAllowed())) return false;
  if (getLiuyaoResult()) {
    navigate("screen-20");
    return true;
  }
  return false;
}

function getLiuyaoLineType(value) {
  return {
    6: { value: 6, name: "老阴", nature: "阴动", broken: true, moving: true, mark: "×", changesTo: "阳", changedBroken: false, coinText: "阴阴阴" },
    7: { value: 7, name: "少阳", nature: "阳静", broken: false, moving: false, mark: "", changesTo: "阳", changedBroken: false, coinText: "阳阴阴" },
    8: { value: 8, name: "少阴", nature: "阴静", broken: true, moving: false, mark: "", changesTo: "阴", changedBroken: true, coinText: "阳阳阴" },
    9: { value: 9, name: "老阳", nature: "阳动", broken: false, moving: true, mark: "○", changesTo: "阴", changedBroken: true, coinText: "阳阳阳" }
  }[Number(value)] || null;
}

function getLiuyaoValidCasts(state = getLiuyaoState()) {
  return state.casts.map(normalizeLiuyaoCast).filter(Boolean);
}

function getLiuyaoProgress(state = getLiuyaoState()) {
  return getLiuyaoValidCasts(state).length;
}

function getLiuyaoHexFromBools(bools) {
  const lower = LIUYAO_TRIGRAM_BY_BITS[bools.slice(0, 3).map(Boolean).map(Number).join("")];
  const upper = LIUYAO_TRIGRAM_BY_BITS[bools.slice(3, 6).map(Boolean).map(Number).join("")];
  const entry = upper && lower ? YANGZHAI_HEX_INDEX[`${upper.gua}-${lower.gua}`] : null;
  return {
    upper,
    lower,
    no: entry?.no || "",
    name: entry?.name || `${upper?.name || ""}${lower?.name || ""}`,
    key: `${upper?.gua || ""}-${lower?.gua || ""}`
  };
}

function getLiuyaoResult(state = getLiuyaoState()) {
  const casts = state.casts.map(normalizeLiuyaoCast);
  if (casts.length < 6 || casts.some((cast) => !cast)) return null;
  const lines = casts.map((cast, index) => {
    const type = getLiuyaoLineType(cast.value);
    return { ...type, index, label: LIUYAO_LINE_LABELS[index], coins: cast.coins || [], manual: Boolean(cast.manual) };
  });
  const originalBools = lines.map((line) => !line.broken);
  const changedBools = lines.map((line) => line.moving ? !line.changedBroken : !line.broken);
  const primary = getLiuyaoHexFromBools(originalBools);
  const changed = getLiuyaoHexFromBools(changedBools);
  const movingLines = lines.filter((line) => line.moving);
  return { recordId: state.recordId || makeWentianUuid(), question: state.question || LIUYAO_DEFAULT_QUESTION, createdAt: state.createdAt, lines, primary, changed, movingLines };
}

function getLiuyaoHexReading(hex) {
  if (!hex) return { summary: "本卦资料待补。", xian: "", hou: "", liu: "" };
  const master = window.getYijingMasterEntryByName?.(hex.name) || window.getYijingMasterEntryByNum?.(hex.no);
  const guaci = window.getGuaciEntryByName?.(hex.name);
  return {
    summary: applyWentianApprovedClassicDisplayText(master?.summary || guaci?.liu || "此卦重在审时度势，先明当前处境，再定进退。"),
    xian: applyWentianApprovedClassicDisplayText(master?.xian || guaci?.xian || ""),
    hou: applyWentianApprovedClassicDisplayText(master?.hou || guaci?.hou || ""),
    liu: applyWentianApprovedClassicDisplayText(master?.liu || guaci?.liu || ""),
    source: master?.source || ""
  };
}

function getLiuyaoZhouyiOriginal(hex) {
  const original = LIUYAO_ZHOUYI_ORIGINALS[Number(hex?.no)];
  if (original) {
    return {
      label: "周易原文",
      text: [original.gua, original.xiang].filter(Boolean).join("\n"),
      source: "《周易》卦辞、象辞"
    };
  }
  const reading = getLiuyaoHexReading(hex);
  const fallback = firstReadableSentence(reading.liu || reading.summary, "");
  return {
    label: "卦辞摘录",
    text: fallback ? compactLiuyaoOriginalText(fallback) : "此卦卦辞待补录，先按卦象结构与动爻取用。",
    source: formatLiuyaoOriginalSource(reading.source)
  };
}

function getYijingHexagramImageSrc(no) {
  const index = Number(no);
  if (!Number.isInteger(index) || index < 1 || index > 64) return "";
  return `../images/yijing-hexagrams/${String(index).padStart(2, "0")}.webp`;
}

function formatLiuyaoHexMeta(hex) {
  const noText = hex?.no ? `第${hex.no}卦` : "卦象";
  const upper = hex?.upper?.name || "";
  const lower = hex?.lower?.name || "";
  const guaText = upper || lower ? ` · ${upper}上${lower}下` : "";
  return `${noText}${guaText}`;
}

function renderLiuyaoHexImage(hex, label) {
  const src = getYijingHexagramImageSrc(hex?.no);
  if (!src) return "";
  const alt = `${label}：${formatLiuyaoHexMeta(hex)} ${hex?.name || ""}`;
  return `<img class="liuyao-hex-image" src="${src}" alt="${escapeHtml(alt)}" loading="lazy">`;
}

function renderLiuyaoOriginalExcerpt(hex) {
  const original = getLiuyaoZhouyiOriginal(hex);
  return `
    <div class="liuyao-original-quote">
      <b>${escapeHtml(original.label)}</b>
      <p>${escapeHtml(original.text)}</p>
      <small>${escapeHtml(original.source)}</small>
    </div>
  `;
}

function renderLiuyaoMiniHex(lines, options = {}) {
  const displayLines = [5, 4, 3, 2, 1, 0].map((index) => lines?.[index] || null);
  return `
    <span class="liuyao-mini-hex" aria-label="${escapeHtml(options.label || "六爻卦象")}" title="${escapeHtml(options.label || "六爻卦象")}">
      ${displayLines.map((line) => {
        const broken = options.changed && line ? line.changedBroken : line?.broken;
        return `
          <i class="${broken ? "is-yin" : "is-yang"} ${line?.moving ? "is-moving" : ""}">
            <b></b>${broken ? "<b></b>" : ""}
          </i>
        `;
      }).join("")}
    </span>
  `;
}

function firstReadableSentence(text, fallback = "") {
  const source = String(text || "").replace(/原句：/g, "").replace(/讲解：/g, "").replace(/\s+/g, " ").trim();
  return source.split(/[。！？]/).find((part) => part.trim().length >= 6)?.trim() || fallback;
}

function compactLiuyaoOriginalText(text, maxLength = 56) {
  const chars = Array.from(String(text || "").replace(/\s+/g, " ").trim());
  if (chars.length <= maxLength) return chars.join("");
  return `${chars.slice(0, maxLength).join("")}…`;
}

function formatLiuyaoOriginalSource(source) {
  const clean = String(source || "").trim();
  if (!clean || /^output[\\/]/i.test(clean)) return "本地卦辞资料";
  return clean;
}

function getLiuyaoTopicAdvice(question, result) {
  const text = String(question || "");
  const moving = result.movingLines.length;
  if (/感情|婚姻|复合|对象|伴侣|爱情/.test(text)) return moving ? "感情看动爻，先处理变化点，不急着逼对方表态。" : "感情无动先守边界，重在稳定沟通，不宜反复试探。";
  if (/财|钱|投资|生意|收入|合作/.test(text)) return moving ? "财事有变，先控风险和合同，再谈扩张。" : "财事宜稳，先守现金流，少做高杠杆决定。";
  if (/病|健康|身体|手术/.test(text)) return "健康类问题以现实检查为准，此卦只看节奏：先确认风险，再定行动。";
  if (/事业|工作|跳槽|项目|计划|职位|考试/.test(text)) return moving ? "事业有变化点，适合小步推进，用结果换空间。" : "事业先稳住主线，少换方向，把一个成果做扎实。";
  return moving ? "当前局面有变化点，先看动爻，再看变卦走向。" : "当前局面偏静，重看本卦，不宜反复重占同一件事。";
}

function getLiuyaoTrigramNature(trigram) {
  return trigram?.name || "象";
}

function getLiuyaoFullHexName(hex) {
  const upper = hex?.upper?.name || "";
  const lower = hex?.lower?.name || "";
  const name = hex?.name || "本卦";
  if ((upper || lower) && name.startsWith(`${upper}${lower}`)) return name;
  return upper || lower ? `${upper}${lower}${name}` : name;
}

function genLiuyaoAIText(result = getLiuyaoResult()) {
  if (!result) return "";
  const hex = result.primary || {};
  const changed = result.changed || {};
  const moving = Array.isArray(result.movingLines) ? result.movingLines : [];
  const upperGua = hex.upper?.gua || "";
  const lowerGua = hex.lower?.gua || "";
  const upperNature = getLiuyaoTrigramNature(hex.upper);
  const lowerNature = getLiuyaoTrigramNature(hex.lower);
  const changedUpperNature = getLiuyaoTrigramNature(changed.upper);
  const changedLowerNature = getLiuyaoTrigramNature(changed.lower);
  let text = `【卦象概述】\n所得卦象为${getLiuyaoFullHexName(hex)}（第${hex.no || "-"}卦）。上卦${upperGua || upperNature}为${upperNature}，下卦${lowerGua || lowerNature}为${lowerNature}。`;
  text += upperNature === lowerNature
    ? "上下同体，纯卦之象，力量集中而纯粹。"
    : `${upperNature}居上而${lowerNature}居下，两者相互作用，需审卦中各爻之动静。`;
  text += `\n\n【针对所问】\n就「${result.question || "所问之事"}」而言，此卦提示：`;
  const no = Number(hex.no) || 0;
  if (no && no <= 16) text += "当前形势尚在发展初期，宜静观其变，不宜急进。保持耐心，等待时机成熟。事物初生，虽有艰难，但蕴含无限可能。";
  else if (no && no <= 32) text += "目前处于关键转折期，需审时度势，把握机会。顺应时势而动，可得事半功倍之效。但须谨慎行事，不可冒进。";
  else if (no && no <= 48) text += "形势已经较为明朗，宜顺势而为。注意守住已有成果，稳中求进。此时最忌贪多冒进，当知足常乐。";
  else text += "当前局面已近圆满，宜收束整理。反思过往经验，总结得失，为未来新的起点做好充分准备。";
  if (moving.length > 0) {
    text += `\n\n【动爻分析】\n本卦有${moving.length}个动爻：${moving.map((line) => line.label).join("、")}。动爻为卦中变化之关键，提示事态发展的方向与力量。`;
    text += `变卦为${getLiuyaoFullHexName(changed)}，事态将由${hex.name || "本卦"}之象转向${changed.name || "变卦"}之象，即从${upperNature}${lowerNature}之势演变为${changedUpperNature}${changedLowerNature}之格局。需顺应变化，灵活应对。`;
  } else {
    text += "\n\n【稳定之卦】\n本卦无动爻，为静卦。事态较为稳定，不会有太大变化。宜保持现状，循序渐进。";
  }
  text += "\n\n【总结】\n综合卦象分析，建议保持内心清明，顺应自然规律。凡事以诚为本，不必过分焦虑。时机到来之时，自然水到渠成。";
  return text;
}

function renderLiuyaoLineVisual(line, prefix) {
  const lineClass = line?.broken ? "is-yin" : "is-yang";
  return `<span class="liuyao-line-visual ${lineClass}" data-line="${prefix}">${line?.broken ? "<i></i><i></i>" : "<i></i>"}</span>`;
}

function renderLiuyaoHexStack(lines, options = {}) {
  const displayLines = [5, 4, 3, 2, 1, 0].map((index) => lines?.[index] || null);
  const landingIndex = Number.isInteger(options.landingIndex)
    ? options.landingIndex
    : (liuyaoTossAnimation?.active ? liuyaoTossAnimation.lineIndex : -1);
  const freshWindow = Number(options.freshWindow) || 2600;
  const now = Date.now();
  const isEn = getWentianLanguageCode() === "en";
  return `
    <div class="liuyao-hex-stack ${options.compact ? "is-compact" : ""}">
      ${displayLines.map((line, displayIndex) => {
        const realIndex = 5 - displayIndex;
        const isFresh = line?.at && now - line.at >= 0 && now - line.at <= freshWindow;
        const lineLabel = isEn ? `Line ${realIndex + 1}` : LIUYAO_LINE_LABELS[realIndex];
        const lineMeta = line
          ? `${line.value} ${isEn ? translateWentianText(line.name, "en") : line.name}${line.mark ? ` ${line.mark}` : ""}`
          : (isEn ? "Unset" : "未定");
        return `
          <button class="liuyao-line-row ${line?.moving ? "is-moving" : ""} ${line ? "" : "is-empty"} ${realIndex === landingIndex ? "is-landing" : ""} ${isFresh ? "is-new" : ""}" type="button" ${options.manual ? `data-action="liuyao-manual-line" data-line-index="${realIndex}"` : ""}>
            <span class="liuyao-line-label">${lineLabel}</span>
            ${line ? renderLiuyaoLineVisual(line, `${options.id || "hex"}-${realIndex}`) : `<span class="liuyao-line-visual is-empty"><i></i></span>`}
            <span class="liuyao-line-meta">${lineMeta}</span>
          </button>
        `;
      }).join("")}
    </div>
  `;
}

function getLiuyaoCoinFaceLabel(coin, code = getWentianLanguageCode()) {
  const isEn = getWentianLanguageOption(code).code === "en";
  return coin === 3 ? (isEn ? "Heads" : "正") : (isEn ? "Tails" : "反");
}

function renderLiuyaoCoinFaceStrip(coins = [], label = "") {
  const faces = Array.isArray(coins) && coins.length ? coins : [3, 2, 3];
  const isEn = getWentianLanguageCode() === "en";
  const title = label || (isEn ? "Landing Result" : "落地结果");
  return `
    <div class="liuyao-coin-face-strip" aria-label="${escapeHtml(title)}">
      <span>${escapeHtml(title)}</span>
      ${faces.map((coin, index) => `
        <em class="${coin === 3 ? "is-head" : "is-tail"}">
          <i>${index + 1}</i>${getLiuyaoCoinFaceLabel(coin)}
        </em>
      `).join("")}
    </div>
  `;
}

function renderLiuyaoCoinRow(state, options = {}) {
  const last = getLiuyaoValidCasts(state).at(-1);
  const tossing = liuyaoTossAnimation?.active && state.mode === "online";
  const progress = getLiuyaoProgress(state);
  const disabled = state.mode !== "online" || progress >= 6 || options.complete || options.disabled;
  const isEn = getWentianLanguageCode() === "en";
  const disabledLabel = options.lockText || (isEn ? "Hexagram Ready" : "卦已成");
  const coins = tossing ? liuyaoTossAnimation.cast.coins : (last?.coins || [3, 2, 3]);
  const showFaces = tossing || Boolean(last);
  const powerPercent = tossing ? Math.max(18, Math.min(100, Number(liuyaoTossAnimation.power) || 62)) : 0;
  const powerRatio = powerPercent ? powerPercent / 100 : 0;
  const meterRatio = tossing ? powerRatio : (last?.power ? Math.max(0, Math.min(1, last.power / 100)) : 0);
  const throwY = Math.round(-66 - powerRatio * 74);
  const label = tossing
    ? (isEn ? `Force ${powerPercent}% · coins turning` : `力度 ${powerPercent}% · 铜钱翻转中`)
    : disabled
      ? disabledLabel
      : (isEn ? `Swipe up and release to cast line ${progress + 1}` : `按住铜钱上拉，松手投第 ${progress + 1} 爻`);
  const forceLabel = tossing
    ? (isEn ? `Current force ${powerPercent}%` : `本次力度 ${powerPercent}%`)
    : options.lockText
      ? (isEn ? "Waiting for Review" : "待审题")
    : last?.power
      ? (isEn ? `Last force ${last.power}%` : `上次力度 ${last.power}%`)
      : (isEn ? "Swipe to build force" : "上拉蓄力");
  const renderCoin = (coin, index) => {
    const glyphs = isEn
      ? ["", "", "", ""]
      : (coin === 3 ? ["乾", "隆", "通", "宝"] : ["宝", "泉", "通", "宝"]);
    const face = getLiuyaoCoinFaceLabel(coin);
    const mark = showFaces ? (isEn ? face.charAt(0) : face) : (isEn ? "" : "待");
    return `
      <span class="liuyao-coin-token ${coin === 3 ? "is-head" : "is-tail"}" style="--d:${index * 0.1}s" aria-label="${showFaces ? `${face}${isEn ? " coin" : "面铜钱"}` : (isEn ? "Waiting coin" : "待落地铜钱")}">
        <span class="liuyao-coin ${coin === 3 ? "is-yang" : "is-yin"}">
          <i class="coin-glyph is-top">${glyphs[0]}</i>
          <i class="coin-glyph is-right">${glyphs[1]}</i>
          <b aria-hidden="true"></b>
          <i class="coin-glyph is-bottom">${glyphs[2]}</i>
          <i class="coin-glyph is-left">${glyphs[3]}</i>
        </span>
        <em class="liuyao-coin-mark">${mark}</em>
      </span>
    `;
  };
  return `
    <div class="liuyao-coin-stage ${options.modal ? "is-modal" : ""} ${last ? "has-cast" : ""} ${tossing ? "is-tossing" : ""} ${disabled ? "is-disabled" : ""}"
      data-action="liuyao-swipe-cast"
      role="button"
      tabindex="${disabled ? "-1" : "0"}"
      aria-label="${escapeHtml(label)}"
      aria-disabled="${disabled ? "true" : "false"}"
      style="--pull-y:0px;--drag-rot:0deg;--drag-rot-neg:0deg;--power:${powerRatio.toFixed(2)};--power-fill:${meterRatio.toFixed(2)};--throw-y:${throwY}px;">
      ${coins.map(renderCoin).join("")}
      <span class="liuyao-power-meter" aria-hidden="true"><i></i></span>
      <span class="liuyao-force-label">${escapeHtml(forceLabel)}</span>
      <span class="liuyao-swipe-cue">${escapeHtml(label)}</span>
    </div>
    ${showFaces
      ? renderLiuyaoCoinFaceStrip(
        coins,
        tossing
          ? (isEn ? "Landing next" : "即将落地")
          : (isEn ? `Line ${progress}` : `第 ${progress} 爻`)
      )
      : `<div class="liuyao-coin-face-strip is-empty"><span>${isEn ? "Swipe up to reveal the result." : "上拉后显示正反"}</span></div>`}
  `;
}

function getLiuyaoQuestionInputValue(state) {
  const question = state.question || LIUYAO_DEFAULT_QUESTION;
  if (getWentianLanguageCode() === "en" && question === LIUYAO_DEFAULT_QUESTION) {
    return translateWentianText(question, "en");
  }
  return question;
}

function getLiuyaoCastLines(state = getLiuyaoState()) {
  return state.casts.map(normalizeLiuyaoCast).map((cast, index) => cast ? {
    ...getLiuyaoLineType(cast.value),
    index,
    label: LIUYAO_LINE_LABELS[index],
    coins: cast.coins || [],
    manual: Boolean(cast.manual),
    at: cast.at,
    power: cast.power,
  } : null);
}

function renderLiuyaoCoinSummary(state, options = {}) {
  const progress = getLiuyaoProgress(state);
  const last = getLiuyaoValidCasts(state).at(-1);
  const disabled = Boolean(options.disabled || options.complete);
  const tossing = liuyaoTossAnimation?.active && state.mode === "online";
  const title = options.complete ? "六爻已成" : progress ? `已落第 ${progress} 爻` : "三枚铜钱待落地";
  const buttonText = options.complete
    ? "卦已成"
    : (options.lockText || (tossing ? "查看落币" : `投第 ${progress + 1} 爻`));
  const desc = last
    ? `上次力度 ${last.power || 0}% · ${last.coins.map(getLiuyaoCoinFaceLabel).join(" ")}`
    : "提交占问通过后，进入全屏投币。";
  return `
    <div class="liuyao-coin-summary ${disabled ? "is-disabled" : ""}">
      <div>
        <span>${escapeHtml(title)}</span>
        <strong>${escapeHtml(tossing ? "抛币中…" : (options.complete ? "卦已成" : `第 ${progress + 1} 爻待投`))}</strong>
        <em>${escapeHtml(desc)}</em>
      </div>
      ${renderLiuyaoCoinFaceStrip(last?.coins || [3, 2, 3], last ? `第 ${progress} 爻` : "待投铜钱")}
      <button type="button" data-action="liuyao-open-caster" ${disabled ? "disabled" : ""}>${escapeHtml(buttonText)}</button>
    </div>
  `;
}

function renderLiuyaoCasterModal(state, options = {}) {
  if (!liuyaoCastModalOpen || state.mode !== "online") return "";
  const progress = getLiuyaoProgress(state);
  const complete = progress >= 6 || options.complete;
  if (complete) return "";
  const tossing = liuyaoTossAnimation?.active && state.mode === "online";
  const lines = getLiuyaoCastLines(state);
  const landingIndex = liuyaoTossAnimation?.active ? liuyaoTossAnimation.lineIndex : progress - 1;
  const last = getLiuyaoValidCasts(state).at(-1);
  const isEn = getWentianLanguageCode() === "en";
  return `
    <div class="liuyao-caster-modal" role="dialog" aria-modal="true" aria-label="${escapeHtml(isEn ? "Coin Cast" : "在线投币")}">
      <div class="liuyao-caster-head">
        <button type="button" data-action="liuyao-close-caster" aria-label="${escapeHtml(isEn ? "Close coin cast" : "关闭投币")}">‹</button>
        <div>
          <span>${isEn ? "Coin Cast" : "在线投币"}</span>
          <strong>${escapeHtml(tossing ? (isEn ? `Landing Line ${progress + 1}` : `第 ${progress + 1} 爻落地中`) : (isEn ? `Cast Line ${progress + 1}` : `投第 ${progress + 1} 爻`))}</strong>
        </div>
        <div class="liuyao-caster-actions">
          <button class="liuyao-caster-reset" type="button" data-action="liuyao-reset" ${tossing ? "disabled" : ""}>${isEn ? "Reset" : "清空重来"}</button>
          <em>${escapeHtml(tossing ? (isEn ? "Coins turning" : "铜钱翻转") : (isEn ? "Swipe and release" : "上拉松手"))}</em>
        </div>
      </div>
      <div class="liuyao-caster-body">
        ${renderLiuyaoCoinRow(state, { ...options, complete, modal: true })}
      </div>
      <div class="liuyao-caster-result">
        <div>
          <span>${escapeHtml(last ? (isEn ? "Last Landing" : "上次落地") : (isEn ? "Landing Log" : "落地记录"))}</span>
          <strong>${escapeHtml(last ? `${last.coins.map((coin) => getLiuyaoCoinFaceLabel(coin)).join(" / ")} · ${isEn ? translateWentianText(getLiuyaoLineType(last.value).name, "en") : getLiuyaoLineType(last.value).name}` : (isEn ? "Waiting for the first line" : "等待第一个落爻"))}</strong>
        </div>
        ${renderLiuyaoHexStack(lines, { id: "cast-modal", compact: true, landingIndex })}
      </div>
    </div>
  `;
}

function renderLiuyaoResetConfirm() {
  if (!liuyaoResetConfirmOpen) return "";
  const isEn = getWentianLanguageCode() === "en";
  return `
    <div class="liuyao-reset-confirm" role="dialog" aria-modal="true" aria-label="${escapeHtml(isEn ? "Confirm reset" : "确认清空重来")}">
      <div class="liuyao-reset-confirm-card">
        <strong>${isEn ? "Reset this cast?" : "清空重来？"}</strong>
        <p>${isEn ? "This clears the current lines and takes you back to a fresh cast." : "当前已投的爻会清空，回到重新起卦。"}</p>
        <div>
          <button type="button" data-action="liuyao-reset-cancel">${isEn ? "Cancel" : "取消"}</button>
          <button type="button" class="primary" data-action="liuyao-reset-confirm">${isEn ? "Confirm Reset" : "确认清空"}</button>
        </div>
      </div>
    </div>
  `;
}

function renderLiuyaoManualCoinInput(state, options = {}) {
  const disabled = Boolean(options.disabled);
  const casts = Array.from({ length: 6 }, (_, index) => normalizeLiuyaoCast(state.casts[index]));
  const nextIndex = casts.findIndex((cast) => !cast);
  const complete = nextIndex < 0 && casts.every(Boolean);
  const activeIndex = complete ? -1 : nextIndex;
  const currentIndex = activeIndex >= 0 ? activeIndex : 5;
  const currentCoins = activeIndex >= 0 ? getLiuyaoManualCoins(state, currentIndex) : [];
  const currentCoinCount = currentCoins.filter(Boolean).length;
  const currentCast = makeLiuyaoManualCastFromCoins(currentCoins);
  const completedRows = casts
    .map((cast, lineIndex) => ({ cast, lineIndex, type: cast ? getLiuyaoLineType(cast.value) : null }))
    .filter((item) => item.cast && item.type);
  const renderFaceButton = (lineIndex, coinIndex, value, current) => `
    <button
      type="button"
      class="${current === value ? "is-active" : ""}"
      data-action="liuyao-manual-coin"
      data-line-index="${lineIndex}"
      data-coin-index="${coinIndex}"
      data-coin-face="${value}"
      ${disabled ? "disabled" : ""}
      aria-label="${escapeHtml(getLiuyaoCoinFaceLabel(value))}"
    >${getWentianLanguageCode() === "en" ? (value === 3 ? "H" : "T") : getLiuyaoCoinFaceLabel(value)}</button>
  `;
  return `
    <div class="liuyao-manual-card ${disabled ? "is-disabled" : ""}">
      <div class="liuyao-manual-head">
        <div>
          <span>真实铜钱录入</span>
          <strong>按初爻到上爻，逐爻填三枚铜钱</strong>
        </div>
        <em>${getLiuyaoProgress(state)}/6</em>
      </div>
      <p>每次只录当前这一爻：现实中抛三枚铜钱，再按结果点正反；三枚录满后点确认进入下一爻。</p>
      ${complete ? `
        <div class="liuyao-manual-done">
          <strong>六爻已录完</strong>
          <span>可以查看卦象解读，或重录上一爻。</span>
          <button type="button" class="liuyao-manual-undo" data-action="liuyao-manual-clear-last" ${disabled ? "disabled" : ""}>重录上一爻</button>
        </div>
      ` : `
        <div class="liuyao-manual-current">
          <div class="liuyao-manual-current-head">
            <div>
              <strong>${LIUYAO_LINE_LABELS[currentIndex]}</strong>
              <span>第 ${currentIndex + 1}/6 爻</span>
            </div>
            <em>${currentCoinCount}/3</em>
          </div>
          <div class="liuyao-manual-status">${currentCoinCount >= 3 ? `本爻已成：${currentCast?.value || ""} ${currentCast ? getLiuyaoLineType(currentCast.value).name : ""}。确认后进入下一爻。` : "抛三枚铜钱后，依次录入第 1、2、3 枚。"}</div>
          <div class="liuyao-manual-coins">
            ${[0, 1, 2].map((coinIndex) => `
              <div class="liuyao-manual-coin-pick">
                <i>第 ${coinIndex + 1} 枚</i>
                <span>
                  ${renderFaceButton(currentIndex, coinIndex, 3, currentCoins[coinIndex])}
                  ${renderFaceButton(currentIndex, coinIndex, 2, currentCoins[coinIndex])}
                </span>
              </div>
            `).join("")}
          </div>
          <div class="liuyao-manual-current-actions">
            <button type="button" class="liuyao-manual-clear" data-action="liuyao-manual-clear-line" data-line-index="${currentIndex}" ${disabled || !currentCoins.some(Boolean) ? "disabled" : ""}>清空本爻</button>
            <button type="button" class="liuyao-manual-confirm" data-action="liuyao-manual-confirm-line" data-line-index="${currentIndex}" ${disabled || !currentCast ? "disabled" : ""}>${currentIndex >= 5 ? "确认成卦" : "确认本爻"}</button>
          </div>
        </div>
      `}
      ${completedRows.length ? `
        <div class="liuyao-manual-history">
          <span>已录入</span>
          <div>
            ${completedRows.map(({ cast, lineIndex, type }) => `<i>${LIUYAO_LINE_LABELS[lineIndex]} ${cast.value}${type.name}${type.mark ? type.mark : ""}</i>`).join("")}
          </div>
        </div>
      ` : ""}
    </div>
  `;
}

function renderLiuyaoAppHeader(id, title, state = getLiuyaoState(), options = {}) {
  const quota = getLiuyaoQuota(state);
  const badge = options.badge || (quota.testingUnlimited ? "测试不限" : `${quota.used}/${quota.limit}`);
  return `
    <div class="liuyao-app-header" aria-label="${escapeHtml(title)}">
      ${wentianBackPill(id, 18, 42, 'data-action="back" aria-label="返回"')}
      <div class="liuyao-app-title">
        <strong>${escapeHtml(title)}</strong>
        <span>${escapeHtml(badge)}</span>
      </div>
      ${options.reset ? `<button type="button" class="liuyao-header-reset" data-action="liuyao-reset">${escapeHtml(options.resetLabel || "重来")}</button>` : '<span class="liuyao-header-spacer"></span>'}
    </div>
  `;
}

function renderLiuyaoFlowSteps(activeIndex) {
  const items = ["审题", "起卦", "解卦"];
  return `
    <div class="liuyao-flow-steps" aria-label="六爻流程">
      ${items.map((label, index) => `
        <div class="liuyao-flow-step ${index === activeIndex ? "is-active" : ""} ${index < activeIndex ? "is-done" : ""}">
          <span class="liuyao-flow-step-dot">${index < activeIndex ? "✓" : index + 1}</span>
          <span class="liuyao-flow-step-label">${escapeHtml(label)}</span>
        </div>
        ${index < items.length - 1 ? `<i class="liuyao-flow-line ${index < activeIndex ? "is-done" : ""}"></i>` : ""}
      `).join("")}
    </div>
  `;
}

function renderLiuyaoQuestionStartButton(state = getLiuyaoState()) {
  const meta = getLiuyaoQuestionSubmitMeta(state);
  const label = meta.state === "idle" ? "开始起卦" : meta.label;
  return `
    <button
      type="button"
      class="liuyao-question-submit liuyao-start-button ${meta.state ? `is-${meta.state}` : ""}"
      data-action="liuyao-submit-question"
      ${meta.disabled ? "disabled" : ""}
    >${escapeHtml(label)}</button>
  `;
}

function renderLiuyaoQuestionStage(state = getLiuyaoState()) {
  return `
    <section class="liuyao-stage liuyao-stage-ask">
      <div class="liuyao-ask-title">
        <h2>你想问什么？</h2>
        <p>一事一卦，越具体越准</p>
      </div>
      <label class="liuyao-big-question" for="liuyao-question">
        <textarea id="liuyao-question" maxlength="${LIUYAO_QUESTION_MAX_LENGTH}" rows="8" placeholder="例如：这周面试能顺利通过吗？">${escapeHtml(getLiuyaoQuestionInputValue(state))}</textarea>
        <span>${formatLiuyaoQuestionCount(getLiuyaoQuestionInputValue(state))}</span>
      </label>
      ${renderLiuyaoQuestionStartButton(state)}
      <div class="liuyao-ask-review">
        ${renderLiuyaoQuotaBadge(state)}
        ${renderLiuyaoQuestionGateStatus(state)}
      </div>
      ${renderLiuyaoQuestionSuggestions(state)}
    </section>
  `;
}

function renderLiuyaoModeCard(state = getLiuyaoState(), locked = false) {
  return `
    <section class="liuyao-mode-card">
      <div class="liuyao-section-title">
        <label>起卦方式</label>
        <em>${state.mode === "manual" ? "手动起卦" : "在线投币"}</em>
      </div>
      <div>
        <button type="button" class="${state.mode === "online" ? "is-active" : ""}" data-action="liuyao-mode" data-mode="online" ${locked ? "disabled" : ""}>在线投币</button>
        <button type="button" class="${state.mode === "manual" ? "is-active" : ""}" data-action="liuyao-mode" data-mode="manual" ${locked ? "disabled" : ""}>手动起卦</button>
      </div>
    </section>
  `;
}

function renderLiuyaoManualCoinInput(state, options = {}) {
  const disabled = Boolean(options.disabled);
  const casts = Array.from({ length: 6 }, (_, index) => normalizeLiuyaoCast(state.casts[index]));
  const nextIndex = casts.findIndex((cast) => !cast);
  const complete = nextIndex < 0 && casts.every(Boolean);
  const activeIndex = complete ? -1 : nextIndex;
  const currentIndex = activeIndex >= 0 ? activeIndex : 5;
  const currentCoins = activeIndex >= 0 ? getLiuyaoManualCoins(state, currentIndex) : [];
  const currentCoinCount = currentCoins.filter(Boolean).length;
  const currentCast = makeLiuyaoManualCastFromCoins(currentCoins);
  const completedRows = casts
    .map((cast, lineIndex) => ({ cast, lineIndex, type: cast ? getLiuyaoLineType(cast.value) : null }))
    .filter((item) => item.cast && item.type);
  const isEn = getWentianLanguageCode() === "en";
  const renderFaceButton = (lineIndex, coinIndex, value, current) => `
    <button
      type="button"
      class="${current === value ? "is-active" : ""}"
      data-action="liuyao-manual-coin"
      data-line-index="${lineIndex}"
      data-coin-index="${coinIndex}"
      data-coin-face="${value}"
      ${disabled ? "disabled" : ""}
      aria-label="${escapeHtml(getLiuyaoCoinFaceLabel(value))}"
    >${getWentianLanguageCode() === "en" ? (value === 3 ? "H" : "T") : getLiuyaoCoinFaceLabel(value)}</button>
  `;
  const currentTypeName = currentCast ? (isEn ? translateWentianText(getLiuyaoLineType(currentCast.value).name, "en") : getLiuyaoLineType(currentCast.value).name) : "";
  return `
    <section class="liuyao-manual-card ${disabled ? "is-disabled" : ""}">
      <div class="liuyao-manual-head">
        <div>
          <span>${isEn ? "Real Coin Entry" : "真实铜钱录入"}</span>
          <strong>${escapeHtml(complete ? (isEn ? "All Six Lines Recorded" : "六爻已录满") : (isEn ? `Line ${currentIndex + 1}` : LIUYAO_LINE_LABELS[currentIndex]))}</strong>
        </div>
        <em>${escapeHtml(complete ? "6/6" : `${currentCoinCount}/3`)}</em>
      </div>
      <p class="liuyao-manual-copy">${escapeHtml(
        complete
          ? (isEn ? "All six lines are ready. Open the reading, or redo the previous line if needed." : "六爻已满，可直接查看卦象；如需修正，可重录上一爻。")
          : (isEn ? `Record line ${currentIndex + 1} of 6. Toss three real coins, then confirm Heads or Tails for each one.` : `第 ${currentIndex + 1}/6 爻，每爻录入三枚铜钱，按正反依次确认。`)
      )}</p>
      ${complete ? `
        <div class="liuyao-manual-done">
          <strong>${isEn ? "Hexagram Ready" : "卦已成"}</strong>
          <span>${isEn ? "The original hexagram, changed hexagram, and moving lines are ready." : "本卦、变卦和动爻都已生成。"}</span>
          <div class="liuyao-manual-current-actions">
            <button type="button" class="liuyao-manual-clear" data-action="liuyao-manual-clear-last" ${disabled ? "disabled" : ""}>${isEn ? "Redo Previous Line" : "重录上一爻"}</button>
            <button type="button" class="liuyao-manual-confirm" data-action="liuyao-show-result">${isEn ? "View Reading" : "查看解卦"}</button>
          </div>
        </div>
      ` : `
        <div class="liuyao-manual-current">
          <div class="liuyao-manual-current-head">
            <div>
              <strong>${isEn ? `Line ${currentIndex + 1}` : LIUYAO_LINE_LABELS[currentIndex]}</strong>
              <span>${isEn ? `${currentIndex + 1}/6 lines` : `第 ${currentIndex + 1}/6 爻`}</span>
            </div>
            <em>${currentCoinCount}/3</em>
          </div>
          <div class="liuyao-manual-status">${escapeHtml(
            currentCoinCount >= 3
              ? (isEn
                ? `Current line: ${currentCast?.value || ""} ${currentTypeName}. Confirm to unlock the next line.`
                : `本爻已成：${currentCast?.value || ""} ${currentCast ? getLiuyaoLineType(currentCast.value).name : ""}，确认后进入下一爻。`)
              : (isEn ? "After tossing three coins, record Coin 1, Coin 2, then Coin 3." : "抛三枚铜钱后，依次录入第 1、2、3 枚。")
          )}</div>
          <div class="liuyao-manual-coins">
            ${[0, 1, 2].map((coinIndex) => `
              <div class="liuyao-manual-coin-pick">
                <i>${isEn ? `Coin ${coinIndex + 1}` : `第 ${coinIndex + 1} 枚`}</i>
                <span>
                  ${renderFaceButton(currentIndex, coinIndex, 3, currentCoins[coinIndex])}
                  ${renderFaceButton(currentIndex, coinIndex, 2, currentCoins[coinIndex])}
                </span>
              </div>
            `).join("")}
          </div>
          <div class="liuyao-manual-current-actions">
            <button type="button" class="liuyao-manual-clear" data-action="liuyao-manual-clear-line" data-line-index="${currentIndex}" ${disabled || !currentCoins.some(Boolean) ? "disabled" : ""}>${isEn ? "Clear Line" : "清空本爻"}</button>
            <button type="button" class="liuyao-manual-confirm" data-action="liuyao-manual-confirm-line" data-line-index="${currentIndex}" ${disabled || !currentCast ? "disabled" : ""}>${isEn ? (currentIndex >= 5 ? "Confirm Hexagram" : "Confirm Line") : (currentIndex >= 5 ? "确认成卦" : "确认本爻")}</button>
          </div>
        </div>
      `}
      ${completedRows.length ? `
        <div class="liuyao-manual-history">
          <span>${isEn ? "Recorded" : "已录入"}</span>
          <div>
            ${completedRows.map(({ cast, lineIndex, type }) => `<i>${isEn ? `Line ${lineIndex + 1}` : LIUYAO_LINE_LABELS[lineIndex]} ${cast.value} ${isEn ? translateWentianText(type.name, "en") : type.name}${type.mark ? ` ${type.mark}` : ""}</i>`).join("")}
          </div>
        </div>
      ` : ""}
    </section>
  `;
}

function renderLiuyaoAppHeader(id, title, state = getLiuyaoState(), options = {}) {
  const quota = getLiuyaoQuota(state);
  const isEn = getWentianLanguageCode() === "en";
  const badge = options.badge || (quota.testingUnlimited ? (isEn ? "Unlimited" : "测试不限") : `${quota.used}/${quota.limit}`);
  const heading = isEn ? translateWentianText(title, "en") : title;
  return `
    <div class="liuyao-app-header" aria-label="${escapeHtml(heading)}">
      ${wentianBackPill(id, 18, 42, `data-action="back" aria-label="${isEn ? "Back" : "返回"}"`)}
      <div class="liuyao-app-title">
        <strong>${escapeHtml(heading)}</strong>
        <span>${escapeHtml(badge)}</span>
      </div>
      ${options.reset ? `<button type="button" class="liuyao-header-reset" data-action="liuyao-reset">${escapeHtml(options.resetLabel || (isEn ? "Reset" : "重来"))}</button>` : '<span class="liuyao-header-spacer"></span>'}
    </div>
  `;
}

function renderLiuyaoFlowSteps(activeIndex) {
  const isEn = getWentianLanguageCode() === "en";
  const items = isEn ? ["Question Check", "Cast", "Reading"] : ["审题", "起卦", "解卦"];
  return `
    <div class="liuyao-flow-steps" aria-label="${escapeHtml(isEn ? "Liuyao Flow" : "六爻流程")}">
      ${items.map((label, index) => `
        <div class="liuyao-flow-step ${index === activeIndex ? "is-active" : ""} ${index < activeIndex ? "is-done" : ""}">
          <span class="liuyao-flow-step-dot">${index < activeIndex ? "✓" : index + 1}</span>
          <span class="liuyao-flow-step-label">${escapeHtml(label)}</span>
        </div>
        ${index < items.length - 1 ? `<i class="liuyao-flow-line ${index < activeIndex ? "is-done" : ""}"></i>` : ""}
      `).join("")}
    </div>
  `;
}

function renderLiuyaoQuestionStage(state = getLiuyaoState()) {
  const isEn = getWentianLanguageCode() === "en";
  const questionValue = getLiuyaoQuestionInputValue(state);
  return `
    <section class="liuyao-stage liuyao-stage-ask">
      <div class="liuyao-ask-title">
        <h2>${isEn ? "What do you want to ask?" : "你想问什么？"}</h2>
        <p>${isEn ? "One clear matter works best" : "一事一卦，越具体越准"}</p>
      </div>
      <label class="liuyao-big-question" for="liuyao-question">
        <textarea id="liuyao-question" maxlength="${LIUYAO_QUESTION_MAX_LENGTH}" rows="8" placeholder="${escapeHtml(isEn ? "Example: Will this interview go well?" : "例如：这周面试能顺利通过吗？")}">${escapeHtml(questionValue)}</textarea>
        <span>${formatLiuyaoQuestionCount(questionValue)}</span>
      </label>
      ${renderLiuyaoQuestionStartButton(state)}
      <div class="liuyao-ask-review">
        ${renderLiuyaoQuotaBadge(state)}
        ${renderLiuyaoQuestionGateStatus(state)}
      </div>
      ${renderLiuyaoQuestionSuggestions(state)}
    </section>
  `;
}

function renderLiuyaoModeCard(state = getLiuyaoState(), locked = false) {
  const isEn = getWentianLanguageCode() === "en";
  return `
    <section class="liuyao-mode-card">
      <div class="liuyao-section-title">
        <label>${isEn ? "Casting Method" : "起卦方式"}</label>
        <em>${state.mode === "manual" ? (isEn ? "Manual Casting" : "手动起卦") : (isEn ? "Coin Cast" : "在线投币")}</em>
      </div>
      <div>
        <button type="button" class="${state.mode === "online" ? "is-active" : ""}" data-action="liuyao-mode" data-mode="online" ${locked ? "disabled" : ""}>${isEn ? "Coin Cast" : "在线投币"}</button>
        <button type="button" class="${state.mode === "manual" ? "is-active" : ""}" data-action="liuyao-mode" data-mode="manual" ${locked ? "disabled" : ""}>${isEn ? "Manual Casting" : "手动起卦"}</button>
      </div>
    </section>
  `;
}

function renderLiuyaoCastStage(state, details = {}) {
  const progress = details.progress || getLiuyaoProgress(state);
  const complete = Boolean(details.complete);
  const result = details.completeResult || (complete ? getLiuyaoResult(state) : null);
  const lines = details.lines || getLiuyaoCastLines(state);
  const isEn = getWentianLanguageCode() === "en";
  const questionLockText = details.questionLockText || "";
  const gateBusy = Boolean(details.gateBusy);
  const questionReady = Boolean(details.questionReady);
  const tossing = liuyaoTossAnimation?.active && state.mode === "online";
  const trigramEn = {
    qian: { roman: "Qian", name: "Heaven" },
    dui: { roman: "Dui", name: "Lake" },
    li: { roman: "Li", name: "Fire" },
    zhen: { roman: "Zhen", name: "Thunder" },
    xun: { roman: "Xun", name: "Wind" },
    kan: { roman: "Kan", name: "Water" },
    gen: { roman: "Gen", name: "Mountain" },
    kun: { roman: "Kun", name: "Earth" }
  };
  const getTriEn = (tri) => trigramEn[tri?.key] || { roman: tri?.gua || "", name: tri?.name || "" };
  const formatCastHexTitle = (hex, fallback) => {
    if (!isEn) return hex?.name || fallback;
    const upper = getTriEn(hex?.upper).name;
    const lower = getTriEn(hex?.lower).name;
    if (upper && lower && upper !== lower) return `${upper} / ${lower}`;
    return upper || lower || fallback;
  };
  const formatCastHexMeta = (hex) => {
    if (!isEn) return formatLiuyaoHexMeta(hex);
    const upper = getTriEn(hex?.upper);
    const lower = getTriEn(hex?.lower);
    const parts = [];
    if (hex?.no) parts.push(`Hex ${hex.no}`);
    if (upper.roman && lower.roman) parts.push(`${upper.roman}/${lower.roman}`);
    return parts.join(" · ") || "Hex";
  };
  const movingText = result
    ? (isEn
      ? (result.movingLines?.length ? result.movingLines.map((line) => `Line ${Number(line.index) + 1}`).join(", ") : "No moving lines")
      : formatLiuyaoMovingLineText(result.movingLines))
    : (isEn ? "None" : "无");
  const modeLocked = progress > 0 || complete || tossing;
  return `
    <section class="liuyao-stage liuyao-stage-cast">
      ${renderLiuyaoFlowSteps(complete ? 2 : 1)}
      <div class="liuyao-question-pill">
        <i></i>
        <span data-wentian-i18n-skip="1">${escapeHtml(normalizeLiuyaoQuestion(state.question) || (isEn ? "Question" : "所问之事"))}</span>
      </div>
      ${renderLiuyaoModeCard(state, modeLocked)}
      ${state.mode === "manual"
        ? renderLiuyaoManualCoinInput(state, { disabled: gateBusy || !questionReady })
        : `
          <section class="liuyao-coin-panel">
            <div class="liuyao-section-title">
              <label>${complete ? "六爻已成" : `第 ${Math.min(progress + 1, 6)} 爻`}</label>
              <em>在线投币</em>
            </div>
            ${renderLiuyaoCoinSummary(state, { complete, disabled: gateBusy || !questionReady, lockText: questionReady ? "" : questionLockText })}
          </section>
        `}
      <section class="liuyao-progress-card">
        <div class="liuyao-progress-head">
          <strong>六爻进度</strong>
          <span>${escapeHtml(formatWentianDateTime(new Date(state.createdAt || Date.now())))}</span>
          <em>${complete ? "6/6" : `${progress}/6`}</em>
        </div>
        ${result ? `
          <div class="liuyao-progress-result">
            <div>
              <span>本卦</span>
              <strong>${escapeHtml(result.primary?.name || "本卦")}</strong>
              <em>${escapeHtml(formatLiuyaoHexMeta(result.primary))}</em>
            </div>
            <div>
              <span>变卦</span>
              <strong>${escapeHtml(result.changed?.name || "变卦")}</strong>
              <em>${escapeHtml(formatLiuyaoHexMeta(result.changed))}</em>
            </div>
            <b>动爻：${escapeHtml(movingText)}</b>
          </div>
        ` : ""}
        ${tossing ? `<p class="liuyao-cast-note">本次力度 ${Math.max(18, Math.min(100, Number(liuyaoTossAnimation.power) || 62))}%；铜钱翻转 1 秒后落入第 ${progress + 1} 爻。</p>` : ""}
        ${renderLiuyaoHexStack(lines, { id: "cast" })}
      </section>
      ${complete ? `
        <section class="liuyao-result-preview">
          <strong>六爻已成</strong>
          <p>本卦 / 变卦 / 动爻 / 古籍摘录 / 许大师 AI 解卦</p>
          <button type="button" data-action="liuyao-show-result">查看卦象解读</button>
        </section>
      ` : ""}
    </section>
  `;
}

function renderLiuyaoCoinSummary(state, options = {}) {
  const progress = getLiuyaoProgress(state);
  const last = getLiuyaoValidCasts(state).at(-1);
  const complete = Boolean(options.complete);
  const disabled = Boolean(options.disabled && !complete);
  const tossing = liuyaoTossAnimation?.active && state.mode === "online";
  const nextLine = Math.min(progress + 1, 6);
  const lineType = last ? getLiuyaoLineType(last.value) : null;
  const action = complete ? "liuyao-show-result" : "liuyao-open-caster";
  const isEn = getWentianLanguageCode() === "en";
  const buttonText = complete
    ? (isEn ? "View Reading" : "查看解卦")
    : (options.lockText || (tossing ? (isEn ? "Watch Coins" : "查看落币") : (isEn ? `Cast Line ${nextLine}` : `投第 ${nextLine} 爻`)));
  const status = complete
    ? (isEn ? "Six Lines Complete" : "六爻已成")
    : tossing
      ? (isEn ? "Coins Landing..." : "铜钱落定中")
      : progress
        ? (isEn ? `Line ${progress} Recorded` : `第 ${progress} 爻已录`)
        : (isEn ? "Ready to Cast" : "准备起卦");
  const desc = last
    ? (isEn ? `Last force ${last.power || 0}% / ${last.coins.map(getLiuyaoCoinFaceLabel).join(" ")}` : `上次力度 ${last.power || 0}% / ${last.coins.map(getLiuyaoCoinFaceLabel).join(" ")}`)
    : (options.lockText || (isEn ? "Lightly toss three coins to build six lines." : "轻抛三枚铜钱，连起六爻。"));
  const headLabel = complete ? (isEn ? "Coin Cast" : "在线投币") : (isEn ? "Current Cast" : "当前起卦");
  const shellLabel = complete ? (isEn ? "Coin Cast" : "在线投币") : (isEn ? `Line ${nextLine}` : `第 ${nextLine} 爻`);
  const shellValue = complete ? (isEn ? "Six Lines Complete" : "六爻已成") : (lineType ? `${last.value} ${lineType.name}` : (isEn ? "Waiting for coins" : "等待落币"));
  const shellHint = lineType
    ? `${lineType.mark || ""} ${lineType.name}`.trim()
    : (isEn ? "Focus on one line at a time. After it lands, the next line opens automatically." : "每次只看当前一爻，落定后自动进入下一爻。");
  const emptyCoinText = isEn ? "<i>Coin 1</i><i>Coin 2</i><i>Coin 3</i>" : "<i>第 1 枚</i><i>第 2 枚</i><i>第 3 枚</i>";
  return `
    <section class="liuyao-coin-summary ${disabled ? "is-disabled" : ""} ${complete ? "is-complete" : ""}">
      <div class="liuyao-coin-summary-head">
        <div>
          <span>${escapeHtml(headLabel)}</span>
          <strong>${escapeHtml(status)}</strong>
          <em>${escapeHtml(desc)}</em>
        </div>
        <b>${escapeHtml(complete ? "6/6" : `${progress}/6`)}</b>
      </div>
      <div class="liuyao-coin-summary-shell">
        <div class="liuyao-coin-summary-copy">
          <span>${escapeHtml(shellLabel)}</span>
          <strong>${escapeHtml(shellValue)}</strong>
          <em>${escapeHtml(shellHint)}</em>
        </div>
        <div class="liuyao-coin-summary-chips">
          ${(last?.coins || []).map((coin, index) => `<i>${isEn ? `Coin ${index + 1}` : `第 ${index + 1} 枚`} ${escapeHtml(getLiuyaoCoinFaceLabel(coin))}</i>`).join("") || emptyCoinText}
        </div>
        <button type="button" data-action="${action}" ${disabled ? "disabled" : ""}>${escapeHtml(buttonText)}</button>
      </div>
    </section>
  `;
}
function renderLiuyaoManualCoinInput(state, options = {}) {
  const disabled = Boolean(options.disabled);
  const casts = Array.from({ length: 6 }, (_, index) => normalizeLiuyaoCast(state.casts[index]));
  const nextIndex = casts.findIndex((cast) => !cast);
  const complete = nextIndex < 0 && casts.every(Boolean);
  const activeIndex = complete ? -1 : nextIndex;
  const currentIndex = activeIndex >= 0 ? activeIndex : 5;
  const currentCoins = activeIndex >= 0 ? getLiuyaoManualCoins(state, currentIndex) : [];
  const currentCoinCount = currentCoins.filter(Boolean).length;
  const currentCast = makeLiuyaoManualCastFromCoins(currentCoins);
  const completedRows = casts
    .map((cast, lineIndex) => ({ cast, lineIndex, type: cast ? getLiuyaoLineType(cast.value) : null }))
    .filter((item) => item.cast && item.type);
  const renderFaceButton = (lineIndex, coinIndex, value, current) => `
    <button
      type="button"
      class="${current === value ? "is-active" : ""}"
      data-action="liuyao-manual-coin"
      data-line-index="${lineIndex}"
      data-coin-index="${coinIndex}"
      data-coin-face="${value}"
      ${disabled ? "disabled" : ""}
      aria-label="${escapeHtml(getLiuyaoCoinFaceLabel(value))}"
    >${getWentianLanguageCode() === "en" ? (value === 3 ? "H" : "T") : getLiuyaoCoinFaceLabel(value)}</button>
  `;
  return `
    <section class="liuyao-manual-card ${disabled ? "is-disabled" : ""}">
      <div class="liuyao-manual-head">
        <div>
          <span>真实铜钱录入</span>
          <strong>${escapeHtml(complete ? "六爻已录满" : LIUYAO_LINE_LABELS[currentIndex])}</strong>
        </div>
        <em>${escapeHtml(complete ? "6/6" : `${currentCoinCount}/3`)}</em>
      </div>
      <p class="liuyao-manual-copy">${escapeHtml(complete ? "六爻已满，可直接查看卦象；如需修正，可重录上一爻。" : `第 ${currentIndex + 1}/6 爻，每爻录入三枚铜钱，按正反依次确认。`)}</p>
      ${complete ? `
        <div class="liuyao-manual-done">
          <strong>卦已成</strong>
          <span>本卦、变卦和动爻都已生成。</span>
          <div class="liuyao-manual-current-actions">
            <button type="button" class="liuyao-manual-clear" data-action="liuyao-manual-clear-last" ${disabled ? "disabled" : ""}>重录上一爻</button>
            <button type="button" class="liuyao-manual-confirm" data-action="liuyao-show-result">查看解卦</button>
          </div>
        </div>
      ` : `
        <div class="liuyao-manual-current">
          <div class="liuyao-manual-current-head">
            <div>
              <strong>${LIUYAO_LINE_LABELS[currentIndex]}</strong>
              <span>第 ${currentIndex + 1}/6 爻</span>
            </div>
            <em>${currentCoinCount}/3</em>
          </div>
          <div class="liuyao-manual-status">${escapeHtml(currentCoinCount >= 3 ? `本爻已成：${currentCast?.value || ""} ${currentCast ? getLiuyaoLineType(currentCast.value).name : ""}，确认后进入下一爻。` : "抛三枚铜钱后，依次录入第 1、2、3 枚。")}</div>
          <div class="liuyao-manual-coins">
            ${[0, 1, 2].map((coinIndex) => `
              <div class="liuyao-manual-coin-pick">
                <i>第 ${coinIndex + 1} 枚</i>
                <span>
                  ${renderFaceButton(currentIndex, coinIndex, 3, currentCoins[coinIndex])}
                  ${renderFaceButton(currentIndex, coinIndex, 2, currentCoins[coinIndex])}
                </span>
              </div>
            `).join("")}
          </div>
          <div class="liuyao-manual-current-actions">
            <button type="button" class="liuyao-manual-clear" data-action="liuyao-manual-clear-line" data-line-index="${currentIndex}" ${disabled || !currentCoins.some(Boolean) ? "disabled" : ""}>清空本爻</button>
            <button type="button" class="liuyao-manual-confirm" data-action="liuyao-manual-confirm-line" data-line-index="${currentIndex}" ${disabled || !currentCast ? "disabled" : ""}>${currentIndex >= 5 ? "确认成卦" : "确认本爻"}</button>
          </div>
        </div>
      `}
      ${completedRows.length ? `
        <div class="liuyao-manual-history">
          <span>已录入</span>
          <div>
            ${completedRows.map(({ cast, lineIndex, type }) => `<i>${LIUYAO_LINE_LABELS[lineIndex]} ${cast.value}${type.name}${type.mark ? type.mark : ""}</i>`).join("")}
          </div>
        </div>
      ` : ""}
    </section>
  `;
}

function renderLiuyaoCastStage(state, details = {}) {
  const progress = details.progress || getLiuyaoProgress(state);
  const complete = Boolean(details.complete);
  const result = details.completeResult || (complete ? getLiuyaoResult(state) : null);
  const lines = details.lines || getLiuyaoCastLines(state);
  const isEn = getWentianLanguageCode() === "en";
  const questionLockText = details.questionLockText || "";
  const gateBusy = Boolean(details.gateBusy);
  const questionReady = Boolean(details.questionReady);
  const tossing = liuyaoTossAnimation?.active && state.mode === "online";
  const trigramEn = {
    qian: { roman: "Qian", name: "Heaven" },
    dui: { roman: "Dui", name: "Lake" },
    li: { roman: "Li", name: "Fire" },
    zhen: { roman: "Zhen", name: "Thunder" },
    xun: { roman: "Xun", name: "Wind" },
    kan: { roman: "Kan", name: "Water" },
    gen: { roman: "Gen", name: "Mountain" },
    kun: { roman: "Kun", name: "Earth" }
  };
  const getTriEn = (tri) => trigramEn[tri?.key] || { roman: tri?.gua || "", name: tri?.name || "" };
  const formatCastHexTitle = (hex, fallback) => {
    if (!isEn) return hex?.name || fallback;
    const upper = getTriEn(hex?.upper).name;
    const lower = getTriEn(hex?.lower).name;
    if (upper && lower && upper !== lower) return `${upper} / ${lower}`;
    return upper || lower || fallback;
  };
  const formatCastHexMeta = (hex) => {
    if (!isEn) return formatLiuyaoHexMeta(hex);
    const upper = getTriEn(hex?.upper);
    const lower = getTriEn(hex?.lower);
    const parts = [];
    if (hex?.no) parts.push(`Hex ${hex.no}`);
    if (upper.roman && lower.roman) parts.push(`${upper.roman}/${lower.roman}`);
    return parts.join(" · ") || "Hex";
  };
  const movingText = result
    ? (isEn
      ? (result.movingLines?.length ? result.movingLines.map((line) => `Line ${Number(line.index) + 1}`).join(", ") : "No moving lines")
      : formatLiuyaoMovingLineText(result.movingLines))
    : (isEn ? "None" : "无");
  const modeLocked = progress > 0 || complete || tossing;
  return `
    <section class="liuyao-stage liuyao-stage-cast">
      ${renderLiuyaoFlowSteps(complete ? 2 : 1)}
      <div class="liuyao-question-pill">
        <i></i>
        <span data-wentian-i18n-skip="1">${escapeHtml(normalizeLiuyaoQuestion(state.question) || (isEn ? "Question" : "所问之事"))}</span>
      </div>
      ${renderLiuyaoModeCard(state, modeLocked)}
      ${state.mode === "manual"
        ? renderLiuyaoManualCoinInput(state, { disabled: gateBusy || !questionReady })
        : renderLiuyaoCoinSummary(state, { complete, disabled: gateBusy || !questionReady, lockText: questionReady ? "" : questionLockText })}
      <section class="liuyao-progress-card">
        <div class="liuyao-progress-head">
          <strong>${isEn ? "Casting Progress" : "六爻进度"}</strong>
          <span>${escapeHtml(formatWentianDateTime(new Date(state.createdAt || Date.now())))}</span>
          <em>${complete ? "6/6" : `${progress}/6`}</em>
        </div>
        ${result ? `
          <div class="liuyao-progress-result">
            <div>
              <span>${isEn ? "Original" : "本卦"}</span>
              <strong>${escapeHtml(formatCastHexTitle(result.primary, isEn ? "Original" : "本卦"))}</strong>
              <em>${escapeHtml(formatCastHexMeta(result.primary))}</em>
            </div>
            <div>
              <span>${isEn ? "Changed" : "变卦"}</span>
              <strong>${escapeHtml(formatCastHexTitle(result.changed, isEn ? "Changed" : "变卦"))}</strong>
              <em>${escapeHtml(formatCastHexMeta(result.changed))}</em>
            </div>
            <b>${isEn ? "Moving: " : "动爻："}${escapeHtml(movingText)}</b>
          </div>
        ` : ""}
        ${tossing ? `<p class="liuyao-cast-note">${isEn ? `Current force ${Math.max(18, Math.min(100, Number(liuyaoTossAnimation.power) || 62))}%. Coins land on Line ${progress + 1} in about 1 second.` : `本次力度 ${Math.max(18, Math.min(100, Number(liuyaoTossAnimation.power) || 62))}% ，铜钱约 1 秒后落入第 ${progress + 1} 爻。`}</p>` : ""}
        ${renderLiuyaoHexStack(lines, { id: "cast" })}
      </section>
      ${complete ? `
        <section class="liuyao-result-preview">
          <strong>${isEn ? "Current Hexagram" : "六爻已成"}</strong>
          <p>${isEn ? "Original, changed, moving lines, and AI reading." : "本卦、变卦、动爻和许大师解卦已准备好。"}</p>
          <button type="button" data-action="liuyao-show-result">${isEn ? "Read Hexagram" : "查看卦象解读"}</button>
        </section>
      ` : ""}
    </section>
  `;
}

function renderLiuyaoManualCoinInput(state, options = {}) {
  const disabled = Boolean(options.disabled);
  const casts = Array.from({ length: 6 }, (_, index) => normalizeLiuyaoCast(state.casts[index]));
  const nextIndex = casts.findIndex((cast) => !cast);
  const complete = nextIndex < 0 && casts.every(Boolean);
  const activeIndex = complete ? -1 : nextIndex;
  const currentIndex = activeIndex >= 0 ? activeIndex : 5;
  const currentCoins = activeIndex >= 0 ? getLiuyaoManualCoins(state, currentIndex) : [];
  const currentCoinCount = currentCoins.filter(Boolean).length;
  const currentCast = makeLiuyaoManualCastFromCoins(currentCoins);
  const completedRows = casts
    .map((cast, lineIndex) => ({ cast, lineIndex, type: cast ? getLiuyaoLineType(cast.value) : null }))
    .filter((item) => item.cast && item.type);
  const isEn = getWentianLanguageCode() === "en";
  const renderFaceButton = (lineIndex, coinIndex, value, current) => `
    <button
      type="button"
      class="${current === value ? "is-active" : ""}"
      data-action="liuyao-manual-coin"
      data-line-index="${lineIndex}"
      data-coin-index="${coinIndex}"
      data-coin-face="${value}"
      ${disabled ? "disabled" : ""}
      aria-label="${escapeHtml(getLiuyaoCoinFaceLabel(value))}"
    >${getWentianLanguageCode() === "en" ? (value === 3 ? "H" : "T") : getLiuyaoCoinFaceLabel(value)}</button>
  `;
  const currentTypeName = currentCast ? (isEn ? translateWentianText(getLiuyaoLineType(currentCast.value).name, "en") : getLiuyaoLineType(currentCast.value).name) : "";
  return `
    <section class="liuyao-manual-card ${disabled ? "is-disabled" : ""}">
      <div class="liuyao-manual-head">
        <div>
          <span>${isEn ? "Real Coin Entry" : "真实铜钱录入"}</span>
          <strong>${escapeHtml(complete ? (isEn ? "All Six Lines Recorded" : "六爻已录满") : (isEn ? `Line ${currentIndex + 1}` : LIUYAO_LINE_LABELS[currentIndex]))}</strong>
        </div>
        <em>${escapeHtml(complete ? "6/6" : `${currentCoinCount}/3`)}</em>
      </div>
      <p class="liuyao-manual-copy">${escapeHtml(
        complete
          ? (isEn ? "All six lines are ready. Open the reading, or redo the previous line if needed." : "六爻已满，可直接查看卦象；如需修正，可重录上一爻。")
          : (isEn ? `Record line ${currentIndex + 1} of 6. Toss three real coins, then confirm Heads or Tails for each one.` : `第 ${currentIndex + 1}/6 爻，每爻录入三枚铜钱，按正反依次确认。`)
      )}</p>
      ${complete ? `
        <div class="liuyao-manual-done">
          <strong>${isEn ? "Hexagram Ready" : "卦已成"}</strong>
          <span>${isEn ? "The original hexagram, changed hexagram, and moving lines are ready." : "本卦、变卦和动爻都已生成。"}</span>
          <div class="liuyao-manual-current-actions">
            <button type="button" class="liuyao-manual-clear" data-action="liuyao-manual-clear-last" ${disabled ? "disabled" : ""}>${isEn ? "Redo Previous Line" : "重录上一爻"}</button>
            <button type="button" class="liuyao-manual-confirm" data-action="liuyao-show-result">${isEn ? "View Reading" : "查看解卦"}</button>
          </div>
        </div>
      ` : `
        <div class="liuyao-manual-current">
          <div class="liuyao-manual-current-head">
            <div>
              <strong>${isEn ? `Line ${currentIndex + 1}` : LIUYAO_LINE_LABELS[currentIndex]}</strong>
              <span>${isEn ? `${currentIndex + 1}/6 lines` : `第 ${currentIndex + 1}/6 爻`}</span>
            </div>
            <em>${currentCoinCount}/3</em>
          </div>
          <div class="liuyao-manual-status">${escapeHtml(
            currentCoinCount >= 3
              ? (isEn
                ? `Current line: ${currentCast?.value || ""} ${currentTypeName}. Confirm to unlock the next line.`
                : `本爻已成：${currentCast?.value || ""} ${currentCast ? getLiuyaoLineType(currentCast.value).name : ""}，确认后进入下一爻。`)
              : (isEn ? "After tossing three coins, record Coin 1, Coin 2, then Coin 3." : "抛三枚铜钱后，依次录入第 1、2、3 枚。")
          )}</div>
          <div class="liuyao-manual-coins">
            ${[0, 1, 2].map((coinIndex) => `
              <div class="liuyao-manual-coin-pick">
                <i>${isEn ? `Coin ${coinIndex + 1}` : `第 ${coinIndex + 1} 枚`}</i>
                <span>
                  ${renderFaceButton(currentIndex, coinIndex, 3, currentCoins[coinIndex])}
                  ${renderFaceButton(currentIndex, coinIndex, 2, currentCoins[coinIndex])}
                </span>
              </div>
            `).join("")}
          </div>
          <div class="liuyao-manual-current-actions">
            <button type="button" class="liuyao-manual-clear" data-action="liuyao-manual-clear-line" data-line-index="${currentIndex}" ${disabled || !currentCoins.some(Boolean) ? "disabled" : ""}>${isEn ? "Clear Line" : "清空本爻"}</button>
            <button type="button" class="liuyao-manual-confirm" data-action="liuyao-manual-confirm-line" data-line-index="${currentIndex}" ${disabled || !currentCast ? "disabled" : ""}>${isEn ? (currentIndex >= 5 ? "Confirm Hexagram" : "Confirm Line") : (currentIndex >= 5 ? "确认成卦" : "确认本爻")}</button>
          </div>
        </div>
      `}
      ${completedRows.length ? `
        <div class="liuyao-manual-history">
          <span>${isEn ? "Recorded" : "已录入"}</span>
          <div>
            ${completedRows.map(({ cast, lineIndex, type }) => `<i>${isEn ? `Line ${lineIndex + 1}` : LIUYAO_LINE_LABELS[lineIndex]} ${cast.value} ${isEn ? translateWentianText(type.name, "en") : type.name}${type.mark ? ` ${type.mark}` : ""}</i>`).join("")}
          </div>
        </div>
      ` : ""}
    </section>
  `;
}

function sourceLiuyaoCastScreen() {
  const state = getLiuyaoState();
  queueLiuyaoQuotaRefresh();
  const casts = state.casts.map(normalizeLiuyaoCast);
  const lines = getLiuyaoCastLines(state);
  const progress = getLiuyaoProgress(state);
  const complete = progress === 6 && casts.length >= 6 && casts.every(Boolean);
  const tossing = liuyaoTossAnimation?.active && state.mode === "online";
  const gateBusy = liuyaoQuestionGateLoading;
  const question = normalizeLiuyaoQuestion(state.question);
  const gate = normalizeLiuyaoQuestionGate(state.questionGate, question);
  const questionReady = Boolean(gate?.allowed);
  const quotaEmpty = isLiuyaoQuotaExhausted(state);
  const questionLockText = quotaEmpty ? "今日已满，明天再占" : gateBusy ? "审题中，稍候开放" : "提交通过后开放投币";
  const completeResult = complete ? getLiuyaoResult(state) : null;
  const screenHeight = getLiuyaoCastScreenHeight();
  const casterOptions = { complete, disabled: gateBusy || !questionReady, lockText: questionReady ? "" : questionLockText };

  if (state.mode === "online" && liuyaoCastModalOpen && !complete) {
    return `
      ${renderLiuyaoCasterModal(state, casterOptions)}
      ${renderLiuyaoResetConfirm()}
    `;
  }

  return `
    <div class="liuyao-phone-screen" style="min-height:${screenHeight}px">
      ${renderLiuyaoAppHeader("ly17", complete ? "起卦" : "六爻占卜", state, { reset: questionReady || progress > 0 || complete })}
      ${questionReady || progress > 0 || complete
        ? renderLiuyaoCastStage(state, { progress, complete, completeResult, lines, gateBusy, questionReady, questionLockText })
        : renderLiuyaoQuestionStage(state)}
      ${sourceAppBottomNav("首页", 755)}
    </div>
    ${renderLiuyaoCasterModal(state, casterOptions)}
    ${renderLiuyaoResetConfirm()}
  `;
}

function sourceLiuyaoResultScreen() {
  const state = getLiuyaoState();
  const result = getLiuyaoResult();
  const isEn = getWentianLanguageCode() === "en";
  const trigramEn = {
    qian: { roman: "Qian", name: "Heaven" },
    dui: { roman: "Dui", name: "Lake" },
    li: { roman: "Li", name: "Fire" },
    zhen: { roman: "Zhen", name: "Thunder" },
    xun: { roman: "Xun", name: "Wind" },
    kan: { roman: "Kan", name: "Water" },
    gen: { roman: "Gen", name: "Mountain" },
    kun: { roman: "Kun", name: "Earth" }
  };
  const getTriEn = (tri) => trigramEn[tri?.key] || { roman: tri?.gua || "", name: tri?.name || "" };
  const formatHexTitleEn = (hex) => {
    const upper = getTriEn(hex?.upper).name;
    const lower = getTriEn(hex?.lower).name;
    if (upper && lower) return `${upper} over ${lower}`;
    return upper || lower || `Hexagram ${hex?.no || ""}`.trim();
  };
  const formatHexMetaEn = (hex) => {
    const upper = getTriEn(hex?.upper);
    const lower = getTriEn(hex?.lower);
    const parts = [];
    if (hex?.no) parts.push(`Hexagram ${hex.no}`);
    if (upper.roman && lower.roman) parts.push(`${upper.roman} over ${lower.roman}`);
    return parts.join(" / ");
  };
  const formatHexTransformTitleEn = (hex) => {
    const upper = getTriEn(hex?.upper).name;
    const lower = getTriEn(hex?.lower).name;
    if (!upper && !lower) return `Hexagram ${hex?.no || ""}`.trim();
    return upper && lower && upper !== lower ? `${upper} / ${lower}` : (upper || lower);
  };
  const formatHexSideEn = (tri, side) => {
    const item = getTriEn(tri);
    return `${item.roman} (${item.name}) ${side}`;
  };
  const formatMovingTextEn = (movingLines) => {
    const lines = Array.isArray(movingLines) ? movingLines : [];
    if (!lines.length) return "No moving lines";
    return lines.map((line) => `Line ${Number(line.index) + 1}`).join(", ");
  };
  const buildAiTextEn = () => {
    if (!result) return "";
    const originalTitle = formatHexTitleEn(result.primary);
    const changedTitle = hasChanged ? formatHexTitleEn(result.changed) : originalTitle;
    const movingCount = Array.isArray(result.movingLines) ? result.movingLines.length : 0;
    const movingLineText = formatMovingTextEn(result.movingLines);
    const cleanQuestion = String(result.question || "this matter").replace(/[?.!]+$/g, "");
    const lowerQuestion = cleanQuestion.toLowerCase();
    let suggestion = "Move in smaller steps, verify the response at each turn, and avoid forcing the pace before the signal is clear.";
    if (/(project|work|job|career|offer|client|cooperation|contract|business|deal)/i.test(lowerQuestion)) {
      suggestion = "This is better handled through steady progress, clear scope, and tight follow-through on terms and timing.";
    } else if (/(relationship|love|partner|marriage|reconcile|dating)/i.test(lowerQuestion)) {
      suggestion = "Keep communication steady, watch the other side's response, and do not rush for an immediate answer.";
    } else if (/(money|finance|income|investment|payment)/i.test(lowerQuestion)) {
      suggestion = "Protect cash flow first, control risk, and confirm the next step before expanding further.";
    } else if (/(exam|study|school|application)/i.test(lowerQuestion)) {
      suggestion = "Stay with the core plan, tighten execution, and let results accumulate before changing direction.";
    }
    const movingSummary = movingCount
      ? (movingCount === 1
        ? `${movingLineText} is the key change point. Watch what shifts after the next concrete move, then adjust.`
        : `${movingLineText} are the key change points. Watch what shifts after the next concrete move, then adjust.`)
      : `No moving lines appear, so keep the main direction stable and judge by consistent follow-through.`;
    const overview = movingCount
      ? `The original hexagram is ${originalTitle}, changing through ${movingLineText} into ${changedTitle}. This shows a live situation that can move if you respond at the right time.`
      : `The original hexagram is ${originalTitle}. With no moving lines, the situation is relatively steady and favors clarity over repeated probing.`;
    return [
      `[Overview]
${overview}` ,
      `[For Your Question]
For "${cleanQuestion}", the sign is workable, but progress depends on timing, discipline, and not overreaching too early.`,
      `[Moving Lines]
${movingSummary}`,
      `[Suggestion]
${suggestion}`
    ].join("\n\n");
  };
  if (!result) {
    return `
      <div class="liuyao-phone-screen liuyao-result-screen" style="min-height:844px">
        ${renderLiuyaoAppHeader("ly20", isEn ? "Reading" : "\u89e3\u5366", state)}
        <div class="liuyao-empty-card">
          <strong>${isEn ? "Casting Not Complete" : "\u5c1a\u672a\u5b8c\u6210\u8d77\u5366"}</strong>
          <span>${isEn ? "Cast all six lines first, or finish them manually." : "\u8bf7\u5148\u6295\u6ee1\u516d\u723b\uff0c\u6216\u7528\u624b\u52a8\u8d77\u5366\u8865\u5168\u516d\u723b\u3002"}</span>
          <button type="button" data-route="screen-17">${isEn ? "Back to Casting" : "\u8fd4\u56de\u8d77\u5366"}</button>
        </div>
        ${sourceAppBottomNav("首页", 755)}
      </div>
    `;
  }
  const screenHeight = getLiuyaoResultScreenHeight();
  const hasChanged = result.changed?.key && result.changed.key !== result.primary?.key;
  const movingText = isEn ? formatMovingTextEn(result.movingLines) : formatLiuyaoMovingLineText(result.movingLines);
  const aiText = isEn ? buildAiTextEn() : genLiuyaoAIText(result);
  const primaryTitle = isEn ? formatHexTitleEn(result.primary) : result.primary.name;
  const changedTitle = isEn ? formatHexTitleEn(hasChanged ? result.changed : result.primary) : (hasChanged ? result.changed.name : result.primary.name);
  const primaryTransformTitle = isEn ? formatHexTransformTitleEn(result.primary) : result.primary.name;
  const changedTransformTitle = isEn ? formatHexTransformTitleEn(hasChanged ? result.changed : result.primary) : (hasChanged ? result.changed.name : result.primary.name);
  const heroMeta = isEn ? formatHexMetaEn(result.primary) : formatLiuyaoHexMeta(result.primary);
  const heroUpper = isEn ? formatHexSideEn(result.primary.upper, "above") : `${result.primary.upper?.gua || ""}\uFF08${result.primary.upper?.name || ""}\uFF09\u4E0A`;
  const heroLower = isEn ? formatHexSideEn(result.primary.lower, "below") : `${result.primary.lower?.gua || ""}\uFF08${result.primary.lower?.name || ""}\uFF09\u4E0B`;
  return `
    <div class="liuyao-phone-screen liuyao-result-screen" style="min-height:${screenHeight}px">
      ${renderLiuyaoAppHeader("ly20", isEn ? "Reading" : "\u89e3\u5366", state, { reset: true, resetLabel: isEn ? "Reset" : "\u91cd\u6765" })}
      <section class="liuyao-stage liuyao-stage-result">
        ${renderLiuyaoFlowSteps(2)}
        <div class="liuyao-result-hero">
          ${renderLiuyaoMiniHex(result.lines, { label: isEn ? `Original hexagram lines: ${primaryTitle}` : `\u672c\u5366\u516d\u723b\uff1a${result.primary.name}` })}
          <div>
            <span>${isEn ? `Hexagram ${escapeHtml(result.primary.no || "-")}` : `\u7b2c${escapeHtml(result.primary.no || "-")}\u5366`}</span>
            <strong>${escapeHtml(primaryTitle)}</strong>
            <em>${escapeHtml(heroMeta)}</em>
            <p>
              <b>${escapeHtml(heroUpper)}</b>
              <i></i>
              <b>${escapeHtml(heroLower)}</b>
            </p>
          </div>
        </div>
        <div class="liuyao-result-transform">
          <div>
            <span>${isEn ? "Original" : "\u672c\u5366"}</span>
            <strong>${escapeHtml(primaryTransformTitle)}</strong>
          </div>
          <div class="liuyao-result-arrow">
            <b>-></b>
            <em>${escapeHtml(movingText)}</em>
          </div>
          <div>
            <span>${isEn ? "Changed" : "\u53d8\u5366"}</span>
            <strong>${escapeHtml(changedTransformTitle)}</strong>
          </div>
        </div>
        <div class="liuyao-reading-card liuyao-question-result-card">
          <span>${isEn ? "Question" : "\u6240\u95ee\u4e4b\u4e8b"}</span>
          <strong data-wentian-i18n-skip="1">${escapeHtml(result.question || (isEn ? "Question" : "\u6240\u95ee\u4e4b\u4e8b"))}</strong>
        </div>
        <div class="liuyao-ai-card liuyao-master-card">
          <div class="liuyao-master-head">
            <i>${isEn ? "Xu" : "\u8bb8"}</i>
            <div>
              <strong>${isEn ? "Master Xu Reading" : "\u8bb8\u5927\u5e08 \u89e3\u5366"}</strong>
              <span>${isEn ? "AI Reading" : "AI \u547d\u7406\u5206\u6790"}</span>
            </div>
          </div>
          <p class="liuyao-ai-reading">${escapeHtml(aiText)}</p>
          <button type="button" class="primary" data-action="liuyao-ask-xu">${isEn ? "Start AI Reading" : "\u5f00\u59cbAI\u89e3\u5366"}</button>
        </div>
        <div class="liuyao-actions is-single">
          <button type="button" data-action="liuyao-reset">${isEn ? "Cast Again" : "\u91cd\u65b0\u8d77\u5366"}</button>
        </div>
      </section>
      ${sourceAppBottomNav("首页", 755)}
      </div>
  `;
}
function getLiuyaoResultScreenHeight() {
  const result = getLiuyaoResult();
  if (!result) return 844;
  const questionLength = Array.from(result.question || "").length;
  const extraLines = Math.max(0, Math.ceil((questionLength - 24) / 20));
  return Math.min(1380, 1180 + extraLines * 22);
}

function makeLiuyaoXuContext(result = getLiuyaoResult()) {
  if (!result) return null;
  const state = getLiuyaoState();
  if (!isWentianUuid(state.recordId)) {
    state.recordId = result.recordId || makeWentianUuid();
    saveLiuyaoState();
  }
  const primaryReading = getLiuyaoHexReading(result.primary);
  const changedReading = getLiuyaoHexReading(result.changed);
  const primaryOriginal = getLiuyaoZhouyiOriginal(result.primary);
  const changedOriginal = getLiuyaoZhouyiOriginal(result.changed);
  const movingText = formatLiuyaoMovingLineText(result.movingLines);
  const primaryTip = firstReadableSentence(primaryReading.summary, "先看本卦所处局面。");
  const changedTip = result.movingLines.length
    ? firstReadableSentence(changedReading.summary, "变卦看后续走向。")
    : "无动爻时变卦与本卦同体，重在守当前局面。";
  const advice = getLiuyaoTopicAdvice(result.question, result);
  const primaryText = `第${result.primary.no || "-"}卦 ${result.primary.name || ""}（${result.primary.upper?.name || ""}上${result.primary.lower?.name || ""}下）`;
  const changedText = `第${result.changed.no || "-"}卦 ${result.changed.name || ""}（${result.changed.upper?.name || ""}上${result.changed.lower?.name || ""}下）`;
  const linesText = result.lines
    .map((line) => `${line.label}:${line.value}${line.name}${line.mark ? line.mark : ""}`)
    .join("；");
  return {
    type: "liuyao",
    recordId: state.recordId,
    title: `六爻占卜：${result.primary.name}${result.movingLines.length ? ` 之 ${result.changed.name}` : ""}`,
    summaryLine: movingText,
    question: result.question,
    createdAt: result.createdAt,
    castAtText: formatWentianDateTime(new Date(result.createdAt || Date.now())),
    primaryText,
    changedText,
    movingText,
    linesText,
    primaryOriginalText: primaryOriginal.text,
    changedOriginalText: changedOriginal.text,
    primaryTip,
    changedTip,
    advice,
  };
}

function getLiuyaoXuOpeningMessage(context) {
  if (!context) return "我按这卦看这件事。你可以继续问成败、应期、动爻或行动取舍。";
  const cleanQuestion = String(context.question || "所问之事").replace(/[？?。.!！]+$/g, "");
  return [
    "我按这卦看这件事。",
    `你刚才占问：「${cleanQuestion}」。`,
    `卦象：${context.primaryText || "本卦"}${context.changedText ? `，变卦 ${context.changedText}` : ""}，动爻：${context.movingText || "无"}。`,
    "可以继续问这件事能不能成、什么时候动、该进该退，或具体怎么做。"
  ].join("\n");
}

function openLiuyaoXuChat() {
  const context = makeLiuyaoXuContext();
  if (!context) {
    navigate("screen-17", false);
    return;
  }
  setWentianXuChatContext(context);
  navigate("screen-4");
}

function canUseLiuyaoSwipeCaster(target) {
  if (!target || target.getAttribute("aria-disabled") === "true") return false;
  if (liuyaoQuestionGateLoading) return false;
  const state = getLiuyaoState();
  const question = normalizeLiuyaoQuestion(state.question);
  const gate = normalizeLiuyaoQuestionGate(state.questionGate, question);
  return Boolean(gate?.allowed) && state.mode === "online" && getLiuyaoProgress(state) < 6 && !liuyaoTossAnimation?.active;
}

function getLiuyaoSwipeMetrics(event, start = liuyaoSwipeStart) {
  if (!start) return { deltaX: 0, deltaY: 0, pull: 0, power: 0, ready: false, duration: 0 };
  const deltaX = event.clientX - start.x;
  const deltaY = event.clientY - start.y;
  const pull = Math.max(0, Math.min(LIUYAO_PULL_MAX, Math.round(-deltaY)));
  const power = Math.max(0, Math.min(1, pull / LIUYAO_PULL_MAX));
  const powerPercent = Math.round(power * 100);
  const horizontalTolerance = Math.max(34, pull * 1.35);
  return {
    deltaX,
    deltaY,
    pull,
    power,
    ready: powerPercent >= Math.round(LIUYAO_READY_POWER * 100) && Math.abs(deltaX) <= horizontalTolerance,
    duration: Date.now() - (start.startedAt || Date.now()),
  };
}

function updateLiuyaoSwipeCasterUi(start, metrics) {
  const target = start?.target;
  if (!target) return;
  if (!start.lastMetrics || metrics.pull >= start.lastMetrics.pull) start.lastMetrics = metrics;
  const progress = getLiuyaoProgress();
  const powerPercent = Math.round(metrics.power * 100);
  target.style.setProperty("--pull-y", `${Math.round(-metrics.pull * 0.38)}px`);
  target.style.setProperty("--power", metrics.power.toFixed(2));
  target.style.setProperty("--power-fill", Math.min(1, metrics.pull / LIUYAO_SWIPE_THRESHOLD).toFixed(2));
  target.style.setProperty("--drag-rot", `${Math.round(metrics.power * 420)}deg`);
  target.style.setProperty("--drag-rot-neg", `${Math.round(metrics.power * -420)}deg`);
  target.classList.toggle("is-ready", metrics.ready);
  const cue = target.querySelector(".liuyao-swipe-cue");
  if (cue) cue.textContent = metrics.ready
    ? `力度 ${powerPercent}% · 松手投第 ${Math.min(progress + 1, 6)} 爻`
    : `继续上拉蓄力 · ${powerPercent}%`;
  const force = target.querySelector(".liuyao-force-label");
  if (force) force.textContent = `力度 ${powerPercent}%`;
}

function resetLiuyaoSwipeCasterUi(target) {
  if (!target) return;
  const state = getLiuyaoState();
  const last = getLiuyaoValidCasts(state).at(-1);
  const progress = getLiuyaoProgress(state);
  const complete = progress >= 6;
  target.style.setProperty("--pull-y", "0px");
  target.style.setProperty("--power", "0");
  target.style.setProperty("--power-fill", "0");
  target.style.setProperty("--drag-rot", "0deg");
  target.style.setProperty("--drag-rot-neg", "0deg");
  const cue = target.querySelector(".liuyao-swipe-cue");
  if (cue) cue.textContent = complete ? "卦已成" : `按住铜钱上拉，松手投第 ${progress + 1} 爻`;
  const force = target.querySelector(".liuyao-force-label");
  if (force) force.textContent = last?.power ? `上次力度 ${last.power}%` : "上拉蓄力";
}

function handleLiuyaoSwipePointerDown(event) {
  const target = event.target.closest?.('[data-action="liuyao-swipe-cast"]');
  if (!canUseLiuyaoSwipeCaster(target)) return;
  liuyaoSwipeStart = {
    pointerId: event.pointerId,
    x: event.clientX,
    y: event.clientY,
    target,
    startedAt: Date.now(),
  };
  target.style.setProperty("--pull-y", "0px");
  target.style.setProperty("--power", "0");
  target.style.setProperty("--power-fill", "0");
  target.style.setProperty("--drag-rot", "0deg");
  target.style.setProperty("--drag-rot-neg", "0deg");
  target.classList.add("is-dragging");
  target.classList.remove("is-ready", "is-prompting");
  target.setPointerCapture?.(event.pointerId);
  updateLiuyaoSwipeCasterUi(liuyaoSwipeStart, getLiuyaoSwipeMetrics(event));
}

function handleLiuyaoSwipePointerMove(event) {
  if (!liuyaoSwipeStart || liuyaoSwipeStart.pointerId !== event.pointerId) return;
  const metrics = getLiuyaoSwipeMetrics(event);
  updateLiuyaoSwipeCasterUi(liuyaoSwipeStart, metrics);
  if (metrics.pull > 8) event.preventDefault();
}

function handleLiuyaoSwipePointerUp(event) {
  if (!liuyaoSwipeStart || liuyaoSwipeStart.pointerId !== event.pointerId) return;
  const start = liuyaoSwipeStart;
  const { target } = start;
  const releaseMetrics = getLiuyaoSwipeMetrics(event, start);
  const metrics = start.lastMetrics && start.lastMetrics.pull > releaseMetrics.pull
    ? { ...releaseMetrics, ...start.lastMetrics, duration: releaseMetrics.duration }
    : releaseMetrics;
  target.classList.remove("is-dragging");
  target.classList.remove("is-ready");
  target.releasePointerCapture?.(event.pointerId);
  liuyaoSwipeStart = null;
  if (metrics.ready) {
    event.preventDefault();
    startLiuyaoAnimatedToss(metrics);
  } else {
    resetLiuyaoSwipeCasterUi(target);
  }
}

function cancelLiuyaoSwipePointer(event) {
  if (!liuyaoSwipeStart || (event?.pointerId && liuyaoSwipeStart.pointerId !== event.pointerId)) return;
  const target = liuyaoSwipeStart.target;
  target?.classList.remove("is-dragging", "is-ready");
  resetLiuyaoSwipeCasterUi(target);
  liuyaoSwipeStart = null;
}

