function sourceZiweiAiDecodePanel() {
  syncWentianChartAiStateFromStorage();
  const member = getWentianMemberSnapshot();
  if (!member.isMember) return "";
  const chapters = getWentianChartAiChapters();
  const userStarted = !!wentianChartAiState.userStarted;
  const isRunning = userStarted && wentianChartAiState.status === "running";
  const hasResults = userStarted && hasWentianChartAiResults();
  const showFinalBoard = !hasResults && !isRunning;
  const visibleChapters = chapters.filter((chapter) => chapter.ready);
  const chapterTotal = chapters.length || 6;
  const chapterDoneCount = chapters.filter((chapter) => chapter.ready).length;
  const isComplete = chapterDoneCount >= chapterTotal;
  const pdfReady = isComplete && !isRunning;
  const runningTask = isRunning ? getWentianAiTask(wentianChartAiState.runningModule) : null;
  const runningChapterIndex = runningTask
    ? chapters.findIndex((chapter) => chapter.modules.includes(runningTask.module))
    : -1;
  const runningTaskLabel = runningTask && runningChapterIndex >= 0
    ? getWentianCompactText(
      `第 ${runningChapterIndex + 1}/${chapterTotal} 卷：${runningTask.label}`,
      `Generating volume ${runningChapterIndex + 1}/${chapterTotal}`
    )
    : "";
  const pdfLabel = getWentianCompactText(pdfReady ? "下载PDF" : "解读完下载", pdfReady ? "Download PDF" : "After reading");
  const coinProgressDeg = chapterTotal ? Math.round((chapterDoneCount / chapterTotal) * 360) : 0;
  const coinMainLabel = getWentianCompactText(isRunning ? "生成" : (isComplete ? "已完" : "总批"), isRunning ? "Making" : (isComplete ? "Done" : "Read"));
  const coinSubLabel = getWentianCompactText(isRunning ? "中" : (isComplete ? "成" : "命"), isRunning ? "Report" : (isComplete ? "All" : "Chart"));
  const statusLabel = getWentianCompactText(
    isRunning ? (runningTaskLabel || `生成中 ${chapterDoneCount}/${chapterTotal}`) : (isComplete ? "已生成" : (hasResults ? `${chapterDoneCount}/${chapterTotal} 已生成` : "待生成")),
    isRunning ? (runningTaskLabel || `Generating ${chapterDoneCount}/${chapterTotal}`) : (isComplete ? "Completed" : (hasResults ? `${chapterDoneCount}/${chapterTotal} generated` : "Pending"))
  );
  const coinActionLabel = getWentianCompactText(isComplete ? "重新总批命" : "总批命", isComplete ? "Regenerate report" : "Generate report");
  const coinClass = [
    "wentian-chart-ai-coin",
    isRunning ? "is-running" : "",
    isComplete ? "is-complete" : "",
    (isRunning || chapterDoneCount || isComplete) ? "has-progress" : "",
  ].filter(Boolean).join(" ");
  const coinAriaLabel = getWentianCompactText(`${coinActionLabel}，已完成 ${chapterDoneCount}/${chapterTotal} 卷`, `${coinActionLabel}, ${chapterDoneCount}/${chapterTotal} complete`);

  return `
    <section class="wentian-chart-ai-panel" data-node-id="source-27-ai-card">
      <header class="wentian-chart-ai-head">
        <div>
          <span class="wentian-chart-ai-kicker"><i aria-hidden="true"></i>AI 命盘解读</span>
        </div>
      </header>
      ${wentianChartAiState.error ? `<p class="wentian-chart-ai-error">${escapeHtml(wentianChartAiState.error)}</p>` : ""}
      ${showFinalBoard ? "" : `<div class="wentian-chart-ai-hero">
        <div class="wentian-chart-ai-hero-copy">
          <span class="wentian-chart-ai-hero-kicker">${escapeHtml(getWentianCompactText("六卷命书", "Volume report"))}</span>
          <strong class="wentian-chart-ai-hero-title">${escapeHtml(getWentianCompactText(isRunning ? "正在生成命书" : "先看总批", isRunning ? "Building your report" : "Start with the overview"))}</strong>
          <p>${escapeHtml(getWentianCompactText(isRunning ? "生成完成后会立即显示，请保持页面打开" : "专题 · 十年 · 流年 · 曲线", isRunning ? "Results appear as soon as they are ready. Keep this page open." : "Topics · Decade · Annual · Curve"))}</p>
          <b class="wentian-chart-ai-hero-status" role="status" aria-live="polite">${escapeHtml(statusLabel)}</b>
        </div>
        <button
          type="button"
          class="${escapeHtml(coinClass)}"
          style="--decode-progress:${coinProgressDeg}deg"
          data-action="wentian-chart-ai-decode"
          aria-label="${escapeHtml(coinAriaLabel)}"
          ${isRunning ? "disabled" : ""}
        >
          <i class="wentian-chart-ai-coin-ring" aria-hidden="true"></i>
          <span>${escapeHtml(coinMainLabel)}</span>
          <b>${escapeHtml(coinSubLabel)}</b>
          <em>${escapeHtml(`${chapterDoneCount}/${chapterTotal}`)}</em>
        </button>
      </div>`}
      <div class="wentian-chart-ai-actions">
        <button type="button" class="wentian-chart-ai-secondary" data-route="screen-4">追问</button>
        <button type="button" class="wentian-chart-ai-secondary" data-action="wentian-open-mingbook-onepage" ${pdfReady ? "" : "disabled"}>${escapeHtml(pdfLabel)}</button>
      </div>
      <p class="wentian-chart-ai-pdf-status" data-wentian-pdf-status></p>
      ${showFinalBoard ? renderWentianFinalVolumeBoard(chapters, {
        coinProgressDeg,
        coinClass,
        coinActionLabel,
        chapterDoneCount,
        chapterTotal,
        coinMainLabel,
        coinSubLabel,
        statusLabel,
      }) : ""}
    </section>
    ${showFinalBoard || !visibleChapters.length ? "" : `<div class="wentian-chart-ai-list">
      ${visibleChapters.map(renderWentianMobileChapter).join("")}
    </div>`}
  `;
}

