function shouldHideWentianFloatingBottomNav(phone) {
  if (!phone || !view) return false;
  const active = document.activeElement;
  if (active && view.contains(active)) {
    const tag = String(active.tagName || "").toLowerCase();
    if (tag === "input" || tag === "textarea" || tag === "select" || active.isContentEditable) return true;
  }
  const viewportHeight = window.visualViewport?.height || 0;
  const windowHeight = window.innerHeight || document.documentElement.clientHeight || 0;
  return viewportHeight > 0 && windowHeight > 0 && viewportHeight < windowHeight - 140;
}

function getWentianFloatingViewportScale() {
  const viewportWidth = window.visualViewport?.width || window.innerWidth || document.documentElement.clientWidth || WENTIAN_PHONE_WIDTH;
  const phone = view?.querySelector?.(".figma-phone");
  const phoneScale = Number.parseFloat(phone?.style?.getPropertyValue("--wentian-phone-scale"));
  return Math.min(1, viewportWidth / WENTIAN_PHONE_WIDTH, Number.isFinite(phoneScale) ? phoneScale : 1);
}

function syncWentianFloatingBottomNav() {
  const phone = view?.querySelector?.(".figma-phone");
  const desktop = window.matchMedia?.("(min-width: 881px)").matches;
  if (!phone || desktop || phone.dataset.nodeId === "screen-8" || phone.dataset.nodeId === "screen-27" || phone.dataset.nodeId === "screen-46") {
    clearWentianFloatingBottomNav();
    return;
  }

  const navNodes = [...phone.querySelectorAll('[data-node-id^="source-bottom-"], [data-node-id^="converted-bottom-"], [data-node-id^="bottom-"]')];
  if (!navNodes.length) {
    document.querySelector(".wentian-floating-bottom-nav")?.remove();
    clearWentianFloatingChartSubmit();
    clearWentianFloatingArchiveConfirm();
    clearWentianFloatingProfileConfirm();
    view?.classList.remove("has-floating-bottom-nav");
    syncWentianFloatingHepanConfirm(phone, getWentianFloatingViewportScale(), 0, shouldHideWentianFloatingBottomNav(phone));
    return;
  }

  const navTop = navNodes.reduce((min, node) => {
    const top = Number.parseFloat(node.style.top);
    return Number.isFinite(top) ? Math.min(min, top) : min;
  }, Infinity);
  const navBottom = navNodes.reduce((max, node) => {
    const top = Number.parseFloat(node.style.top);
    const height = Number.parseFloat(node.style.height);
    return Number.isFinite(top) && Number.isFinite(height) ? Math.max(max, top + height) : max;
  }, 0);
  if (!Number.isFinite(navTop) || !Number.isFinite(navBottom) || navBottom <= navTop) {
    clearWentianFloatingBottomNav();
    return;
  }

  let floating = document.querySelector(".wentian-floating-bottom-nav");
  if (!floating) {
    floating = document.createElement("div");
    floating.className = "wentian-floating-bottom-nav";
    floating.innerHTML = '<div class="wentian-floating-bottom-nav-inner"></div>';
    document.body.appendChild(floating);
  }

  const navHeight = Math.ceil(navBottom - navTop);
  const scale = getWentianFloatingViewportScale();
  const inner = floating.querySelector(".wentian-floating-bottom-nav-inner");
  inner.innerHTML = "";

  navNodes.forEach((node) => {
    const clone = node.cloneNode(true);
    clone.style.visibility = "";
    clone.style.pointerEvents = "";
    delete clone.dataset.wentianNavHidden;
    const top = Number.parseFloat(clone.style.top);
    if (Number.isFinite(top)) clone.style.top = `${Math.round(top - navTop)}px`;
    inner.appendChild(clone);
    node.style.visibility = "hidden";
    node.style.pointerEvents = "none";
    node.dataset.wentianNavHidden = "1";
  });

  floating.style.setProperty("--wentian-floating-nav-scale", String(scale));
  floating.style.setProperty("--wentian-floating-nav-width", `${Math.ceil(WENTIAN_PHONE_WIDTH * scale)}px`);
  floating.style.setProperty("--wentian-floating-nav-height", `${Math.ceil(navHeight * scale)}px`);
  inner.style.height = `${navHeight}px`;
  const hidden = shouldHideWentianFloatingBottomNav(phone);
  floating.classList.toggle("is-hidden", hidden);
  floating.setAttribute("aria-hidden", hidden ? "true" : "false");
  view?.classList.add("has-floating-bottom-nav");
  const submitHidden = false;
  const submitNavHeight = hidden ? 0 : navHeight;
  syncWentianFloatingChartSubmit(phone, scale, submitNavHeight, submitHidden);
  syncWentianFloatingArchiveConfirm(phone, scale, navHeight, hidden);
  syncWentianFloatingProfileConfirm(phone, scale, navHeight, hidden);
  syncWentianFloatingHepanConfirm(phone, scale, navHeight, hidden);
}

function syncWentianFloatingChartSubmit(phone, scale, navHeight, hidden) {
  if (!phone || state.route !== "screen-26") {
    clearWentianFloatingChartSubmit();
    return;
  }
  const submitNodes = [...phone.querySelectorAll('[data-node-id^="source-26-submit"]')];
  if (!submitNodes.length) {
    clearWentianFloatingChartSubmit();
    return;
  }
  const submitTop = submitNodes.reduce((min, node) => {
    const top = Number.parseFloat(node.style.top);
    return Number.isFinite(top) ? Math.min(min, top) : min;
  }, Infinity);
  const submitBottom = submitNodes.reduce((max, node) => {
    const top = Number.parseFloat(node.style.top);
    const height = Number.parseFloat(node.style.height) || (node.classList.contains("fig-text") ? Number.parseFloat(node.style.fontSize) * 1.4 : 0);
    return Number.isFinite(top) && Number.isFinite(height) ? Math.max(max, top + height) : max;
  }, 0);
  if (!Number.isFinite(submitTop) || submitBottom <= submitTop) {
    clearWentianFloatingChartSubmit();
    return;
  }

  let floating = document.querySelector(".wentian-floating-chart-submit");
  if (!floating) {
    floating = document.createElement("div");
    floating.className = "wentian-floating-chart-submit";
    floating.innerHTML = '<div class="wentian-floating-chart-submit-inner"></div>';
    document.body.appendChild(floating);
  }

  const inner = floating.querySelector(".wentian-floating-chart-submit-inner");
  const submitHeight = Math.ceil(submitBottom - submitTop);
  inner.innerHTML = "";
  submitNodes.forEach((node) => {
    const clone = node.cloneNode(true);
    const top = Number.parseFloat(clone.style.top);
    if (Number.isFinite(top)) clone.style.top = `${Math.round(top - submitTop)}px`;
    clone.style.visibility = "";
    clone.style.pointerEvents = "";
    delete clone.dataset.wentianSubmitHidden;
    inner.appendChild(clone);
    node.style.visibility = "hidden";
    node.style.pointerEvents = "none";
    node.dataset.wentianSubmitHidden = "1";
  });
  inner.style.height = `${submitHeight}px`;
  floating.style.setProperty("--wentian-floating-nav-scale", String(scale));
  floating.style.setProperty("--wentian-floating-nav-width", `${Math.ceil(WENTIAN_PHONE_WIDTH * scale)}px`);
  floating.style.setProperty("--wentian-floating-nav-height", `${Math.ceil(navHeight * scale)}px`);
  floating.style.setProperty("--wentian-floating-submit-height", `${Math.ceil(submitHeight * scale)}px`);
  floating.classList.toggle("is-hidden", hidden);
  floating.setAttribute("aria-hidden", hidden ? "true" : "false");
}

